window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_033"]={"n":"陆深","dyn":"明","poems":[{"t":"夜坐念东征将士","f":"七言律诗","c":["长河乘夜渡貔貅，兵气如云拥上游。","大将能挥白羽扇，君王不爱紫貂裘。","十二关山齐故国，百年疆域汉神州。","不眠霜月闻刁斗，自启茅堂望斗牛。"]},{"t":"五七哭桴次吴朝言御史韵二首 其二","f":"七言律诗","c":["六龄携汝即辞家，能变南音语带华。","时向西雍观振鹭，遥从北阙认朝鸦。","乾坤有恨容啼鸟，风雨何心妒落花。","莫向故园传此曲，年年寒食海西涯。"]},{"t":"秋怀十二首 其三","f":"七言律诗","c":["碧草幽花满故园，南山卧对久忘言。","年来行李书千卷，老去生涯水一村。","已辨弓蛇还石虎，毋烦怨鹤与惊猿。","秋光更比春光好，蜂蝶纷纷不到门。"]},{"t":"秋怀十二首 其五","f":"七言律诗","c":["斗帐香消病骨轻，少年忆得赋秋声。","青藜火煖西风劲，白玉堂深昼漏清。","上帝云霄陪绛节，仙人星汉湿金茎。","高山流水空瞻溯，秖恐涓埃报未成。"]},{"t":"秋怀十二首 其七","f":"七言律诗","c":["六代三吴业已荒，英雄遗恨水茫茫。","试量秋与愁多少，始信年随鬓短长。","江上野凫争得食，山中丛桂早含霜。","长门本为黄金赋，赋就《长门》却自伤。"]},{"t":"秋怀十二首 其八","f":"七言律诗","c":["一番风雨报园林，岸柳汀蒲半不禁。","兔魄已随华月满，凤栖应恋碧梧阴。","清商律应笙歌细，白苧功多箧笥深。","起向推移占物候，为谁先有岁寒心。"]},{"t":"山堂晚晴观楫儿作字","f":"七言律诗","c":["论文说剑更争棋，五十年来两鬓丝。","无事可为甘袖手，有山如画且题诗。","望中禾黍秋风粒，梦后芭蕉夜雨枝。","小几映窗承落日，双钩古帖坐教儿。"]},{"t":"和汪有之园亭之作","f":"七言律诗","c":["一区犹愧子云才，薄有茅堂傍水开。","远信经秋凭雁到，问奇长日有人来。","好花隔岸飞红雨，新笋穿篱迸绿苔。","同上玉堂俱出牧，却从湖海望蓬莱。"]},{"t":"辛丑归途中绝句八首 其五","f":"五言绝句","c":["晓行不知程，梦醒闻细浪。","曙月逐鸡声，棹歌来枕上。"]},{"t":"风入松 再和桂洲","f":"古风","c":["绿窗午枕睡初酣。","梦喜脱朝簪。","觉来犹是长安客，垂杨里、空系归骖。","恋主心依晓阙，思亲泪湿春衫。","玉河流水碧于蓝。","花外燕呢喃。","新词谱就凭谁和，重封罢、亲手题缄。","欲待天边鸣雁，秋风寄与江南。"]},{"t":"红白莲歌","f":"七言古诗","c":["白家池馆薰风里，恰在香山最深处。","池流曲曲暗通泉，莲叶亭亭齐覆水。","花红花白相间开，香风香气四边来。","乍比珊瑚出银海，还疑琼蕊下瑶台。","银海瑶台俱可怜，仙舟一叶渡晴川。","素心饱露秋同月，艳质凝脂晓破烟。","歌罢江南不知暑，渚平沙暖新添雨。","江妃映日试红妆，楚客因风摇白羽。","别有风光傍晚看，遥山流翠入阑干。","四面画屏相向立，一机织锦乱交摊。","主人个时玉堂退，纨扇纶巾坐相对。","静虚如此可论心，芳韵于今应作佩。","论心作佩总堪誇，不愧名称君子花。","记得金銮送归夜，分明一朵隔笼纱。"]},{"t":"鲁桥热","f":"七言古诗","c":["赤日行空正当午，老夫畏热如畏虎。","计程归路三千七，值我行年六十五。","昨过任城旧酒楼，山川信美非吾土。","仲宣太白俱仙才，安得并载黄龙浦。","此日池塘杨柳风，此时庭院芭蕉雨。","牙缃架插馀万卷，衮钺心传破千古。","满座时看羽扇摇，半酣起拂吴钩舞。","已约清风成故人，更须霖雨歌明主。","回瞻殿阁忆微凉，却向园庐依茂树。"]},{"t":"秋水篇","f":"七言古诗","c":["江南洁修多水芳，紫菱翠荇下银塘。","银塘遥接芙蓉渚，晓妆亭亭沐秋雨。","摘花美人云锦裳，郁金香佩双鸳鸯。","家住湖南碧湾里，碧烟如纱拍湖水。","少年射策蓬莱宫，文彩隐映芙蓉红。","珊瑚十尺空自好，灵芝九茎何足道。","一为君歌秋水篇，济川稳汎木兰船。","若论颜色休嗟晚，竟堪持补君王衮。"]},{"t":"杨妃病齿图","f":"七言律诗","c":["沈香亭畔催花鼓，华清宫中翠盘舞。","瓠犀半启樱桃颗，可是玉鱼偏作仵。","似将一掬黛娥颦，翻取三郎断肠谱。","归来南内情更多，一曲霓裳泪如雨。"]},{"t":"石斋歌","f":"七言古诗","c":["关西夫子今元老，有石当斋斋更好。","疑从天上堕支机，似向瀛洲擘琼岛。","磨砺堪为百世师，璠玙不数连城宝。","星光璀璨太白精，云根崒嵂西川道。","早年充贡来明庭，玉堂紫阁静仪刑。","擎天八柱开黄道，障海千寻掣巨灵。","有时条理振韶夏，百兽率舞游鱼听。","孤标共仰积铁壁，大手为勒磨崖铭。","授书空传谷城叟，汉室开基一培塿。","何如五色补天材，元付当年取日手。","石斋峨峨高入云，四海苍生共翘首。","万年永藉圣朝安，再拜为歌仁者寿。"]},{"t":"宝丝灯屏歌","f":"古风","c":["鲛人夜织冰蚕丝，不数细滑鹅溪绢。","或云并州快剪刀，剪此一段澄江练。","乃是云南之南万山中，云腴石髓蟠青葱。","酒黄鸦紫祖母绿，复有无价桃花红。","远人不贡车与服，持此射利如射鹄。","遂令长安富豪家，下视隋珠贱和玉。","琐屑璀璨星宿同，水碓火镕俱有功。","短长曲折巧应手，无乃鬼幻神为工。","分经错纬了不乱，各以本色呈绚烂。","霞蒸雾■有无间，遥看一道晴虹贯。","是中白腻若可餐，良工点染开林峦。","似嫌世上缣素弱，颇有劲气生毫端。","制成屏风向灯夕，聊慰风尘远为客。","壮心岂解随物迁，乡书又送经年隔。","酒钱不爱典衣偿，要与明月争辉光，但愿明月长辉光。"]},{"t":"三松图","f":"七言古诗","c":["三松亭亭高插天，离立森爽含风烟。","栋梁廊庙似无用，撑架日月如有权。","浑疑无地着此物，日观其下天坛前。","秦时大夫封不受，汉家武皇来何虔。","潜龙卧龙差可拟，鳞鬣头角俱依然。","懒为行雨六丁怒，彩虬金电挥成鞭。","有似高人傲一世，宁舍富贵耽沈玄。","师山孙子今奇士，家住万山苍翠边。","胸中惟储秘书监，囊里不贮司徒钱。","手种青松一万树，如此三树尤堪怜。","风雷掀舞山岳动，岁华剥落冰霜偏。","古柏空传二百丈，蟠桃浪说三千年。","有时坐石听凉籁，独把黄庭金字编。","神仙官府总一致，朝中宰相山中贤。","题诗一寄可斋子，会见沧海成桑田。"]},{"t":"蓉溪书屋为金司寇","f":"古风","c":["蓉溪江山真画图，蓉溪主人绝代无。","往岁西归结书屋，风前月下闻伊吾。","牙签插架几万轴，云锦照水三千株。","有时溪头风日好，一段秋波净于扫。","水香花气相氤氲，人间别有蓬莱岛。","蜀道时歌李白难，草玄甘抱扬雄老。","只今身复上天衢，太平经济须巨儒。","尚书省里少司寇，御史台中上大夫。","共道孤芳持晚节，还应廊庙忆江湖。","别来几度花开候，每向西风重回首。","补成五色衮龙衣，元是当年摘花手。","复有阶前兰桂行，相期岁暮松筠友。","君不见南阳草庐绿野堂，此溪此屋同垂芳。"]},{"t":"渡淮放歌","f":"七言古诗","c":["出门江南花无数，行尽淮南春欲暮。","风霜添上鬓丝繁，颇悔从前好词赋。","伊吕分明道可行，孔孟咄嗟时不遇。","故人衮衮俱公侯，频岁劝予劳尺素。","亦有封章达姓名，曾傍重瞳屡回顾。","忆昨素冠成陛辞，天子中兴初践祚。","八年林卧心常悬，一捧部符躬莫措。","玉堂天高旧梦回，青宫地切新恩误。","万分何补等涓埃，五十无闻昩时务。","凭将一出期遂初，自保孤忠总如故。","长河浊流足风波，飞鹢扬舲竞津渡。","携家十口儿女情，居安虑危在云路。","遥持一寸报主心，时放歌声和韶頀。"]},{"t":"吕梁洪","f":"七言古诗","c":["青山夭矫如渴龙，堕地直走河流东。","岸崩谷应气犹怒，其下必有鼋鼍宫。","舟人估客尽回首，篙师舵手俱神工。","人言大险亦大胜，如此江山须画中。","宣尼南游鬼物出，伯禹东导神灵通。","天地何心世多故，刘项曹吕皆豪雄。","圣皇恃德不恃险，万里衽席歌同风。","我来其间正初夏，片帆遥映斜阳红。","风幡前麾影接岸，水槛下视波连空。","肩舆十里据高坐，始信静处观无穷。"]},{"t":"大风宿留城","f":"七言古诗","c":["身世浮沈如一舸，一日千里十日坐。","顺风人喜逆风怒，我任天公何不可。","随身所到一问津，去者从右来从左。","古今道路无不然，自有亨衢自坎坷。","黄泥岸高绿树深，遥望前船密如锁。","争先疾趋古所戒，夜宿澄潭傍渔火。"]},{"t":"宝应湖玩月","f":"古风","c":["我生爱月仍爱奇，着意欲到西湖西。","不然具区三万六千顷，坐此一色银玻瓈。","今宵宝应湖南路，桂魄皎皎风凄凄。","水光四接上下合，冰柱十尺云天低。","楼船不渡南北断，危樯密锁乌鸢栖。","我携二客恣清赏，试选高岸成攀跻。","弦光满射白玉镜，斗柄倒浸青云梯。","人间天上非还是，翻疑海外闻天鸡。","瑶华台殿云母障，水晶宫阙黄金泥。","胡床老子兴不浅，挥手弄影沿长堤。","菰蒲何心烂不起，鲛鳄有恨蟠犹啼。","南中卑暑不耐冷，况复风雨尤难齐。","兹行所得差足慰，未觉严冱欺袍绨。","人言春月胜秋月，春月花柳空萋迷。","争如冬月有劲气，复此淮海冰连溪。","酒怀逸兴俱浩荡，霜明雪映工品题。","君不见汉家中郎持汉节风槩，凛凛海上甘牧羝。"]},{"t":"和王元章梅花为段主事子辛赋","f":"七言古诗","c":["画堂六月飞严霜，客持此幅梅花芳。","乍窥疑浮初月影，细对忽丽繁星芒。","塞垣风高吹石裂，岭南天低不受雪。","何似孤山处士家，一段西湖弄华月。","梅花此时殊有韵，青鸟遥传海山信。","度水盈盈玉雪肤，含风袅袅堆鸦鬓。","万种心情春酒缸，起为花神酹一觞。","谁怜白贲元无价，空复红芳号假王。","会稽山农骨已冷，梦入梅花呼不醒。","巡檐且索屋三间，负郭何须田二顷。"]},{"t":"雪村晚酤图","f":"七言古诗","c":["崆峒万木冻不僵，琼瑶一片埋夕阳。","云安道上少行客，百花潭西封草堂。","桥回溪转疑无路，前村依稀后村暮。","时见青帘猎猎招，如闻白雁翩翩度。","天涯摇落空岁华，翠微自有高人家。","林端红叶饱茶灶，梁上青蚨挑画叉。","一斗鹅黄正堪买，拍浮好怀同北海。","不来租吏浑无哗，夙约溪翁如有待。","川源窅窱古人风，幸际车书万国同。","床头何用纪岁历，门外但送邮诗筒。","凭谁致此好气象，必有明君与贤相。","托斋先生素心人，悬此一幅高堂上。","画家画意不画形，当朝戴进最有声。","未歌三白呈祥瑞，先兆六符开太平。"]},{"t":"南峰书院","f":"七言古诗","c":["南峰主人颜如玉，更向峰前筑书屋。","虹光夜夜贯斗牛，秀色冉冉连嵩祝。","复有家传万卷馀，累朝诸父皆诗书。","子云寂寞空玄阁，诸葛经纶有草庐。","南州高士元同谱，玉树冰壶映千古。","风骚共许国无双，韦杜浪誇天尺五。","孤标绝壁倚春晴，风动芸香满院生。","常留云气从龙出，须种梧桐听凤鸣。"]},{"t":"龙江歌","f":"七言古诗","c":["龙江东来万里道，遥接瀛洲与蓬岛。","三江有水剪不断，五湖无波净于扫。","龙江先生江上生，德器文章俱老成。","胸吞云梦已八九，量比汪陂无浊清。","登科弱冠人如贾，辞源倒挽银河泻。","砥柱中流力有馀，扶摇九万风斯下。","掖垣谏草避人焚，宪节西持往校文。","多少鱼龙随变化，一天星斗浸寒云。","云间自爱归来早，莼菜鲈鱼旧盟好。","閒看秋影澄道心，坐见红尘扬碧草。","碧草红尘阅岁年，宣尼当日正知天。","终同渭水非熊兆，会起浮空万斛船。"]},{"t":"瀛海图为李宗易谕德歌","f":"古风","c":["天南咫尺帝城隅，山灵水秀相盘纡。","中有瀛海接银汉，吞九云梦涵五湖。","太行西来走其下，排列七十二朵青珊瑚。","微风吹波縠纹净，明月照影骊珠孤。","汪汪千顷荡星斗，上下一碧随鸥凫。","世传神龙有窟宅，霹雳惊起头角殊。","化为霖雨洒六合，波涛壁立风云粗。","须臾光霁变天地，荏苒花柳呈芳腴。","我闻弱流三万远隔扶桑外，六鳌三岛空传呼。","玉堂学士李太白，家住瀛海真蓬壶。","水心楼阁开云母，风外帘栊蹙浪珠。","有时倚槛一长眺，宛见云中五色清虚都。","心胸已着秘书省，殿陛恭承子大夫。","青钱万选绝代有，白璧连城天下无。","频年文场拔董贾，昨岁武举罗孙吴。","庙堂自当金玉器，鼎鼐竟与盐梅俱。","周家申甫嵩岳降，苏氏轼辙眉山枯。","大贤应运重得地，瀛海似也非其徒。","江南程生近好手，点缀金碧工调朱。","经营意匠入窅眇，翻取商岩旧典谟。","玉颜丈人古冠佩，疑是退直金銮趋。","手挥一筹探海水，坐见清浅连桑榆。","鲁连高蹈带侠气，仲子汗漫甘乘桴。","君不见张子房，借前箸为汉驱。","请看此筹一下，能奠万古之皇图。"]},{"t":"题严介溪所藏何竹鹤画","f":"七言古诗","c":["江南五月黄梅雨，湿云不断生远水。","风流太守竹鹤翁，家住江南水云里。","兴来挥洒出画图，高峰掩映云模糊。","江回路转草堂静，雨崩沙塌溪桥孤。","钤山堂中群玉府，此幅远淡尤足数。","宪使先生最爱才，玉堂学士真博古。","到处护持如有神，携来长安手泽新。","高人韵士千年迹，孝子慈孙百代珍。"]},{"t":"节妇歌","f":"古风","c":["忆昔敌人犯边日，先皇赫怒挥鈇锧。","苍天深意在戢兵，六龙暂驻阴山跸。","古来胜负兵家常，土木之变悲莫当。","忠臣孝子毕誓死，长缨徒手系名王。","维时张公忠勇士，肉骨藁葬蛮荒耳。","陨星莫想诸葛生，落日雕戈挥不起。","中闺裁罢寄征衣，征衣一寄不曾归。","东海深深精卫苦，九疑泪尽山成围。","折钗分镜甘独守，寒影遗孤成左右。","红颜白发须臾间，长夜玄堂重执手。","遗孤无怙亦无恃，期以功勋光后祀。","星联八座位中丞，重译威敷雪前耻。","谁云纲常一日无，呜呼忠臣为君贞妇夫，凭轩涕泗声呜呜。"]},{"t":"开河待闸苦热","f":"古风","c":["长江无六月，此语为谁传。","筠簟纱厨里，何人不可怜。","我家本在三江上，竹树成行更森爽。","画阁含风蘸水开，仙槎到海随潮长。","波摇云梦通具区，地接蓬莱与方丈。","何似黄尘千尺高，脱巾群饮总称豪。","银床玉井无由觅，赤脚层冰何处逃。","徒闻东郡泉千派，不济南湖水一篙。","临流欲渡还晞发，待看西岩吐新月。","万贯谁缠鹤背轻，一蓬自笑鸠巢拙。","人间合有清凉方，半捲湘帘坐超忽。","君不见陶潜酿秫，两疏赐金。","罹此毒热，听我吴吟。"]},{"t":"星月歌","f":"七言古诗","c":["大星无光月如水，紫烟辟寒天万里。","金吾木柝声不骄，火树星桥接空起。","恭承休假作上元，满目韶华帝城里。","团圞三五宵可怜，浅薄一分春奈尔。","胡床浩兴空昔年，秋色不似长安妍。","五凤楼前迎万乘，六鳌海上拥群仙。","欢游秪厌春更短，欲挽空壶涵百川。","机中红雨催花落，天上青娥妒扇圆。","九衢罗绮人如蚁，五侯甲第黄金炬。","底用还乡作昼行，真堪穷汉经年煮。","别有工夫巧夺天，制成二八当窗女。","回纹晕采剪越绫，五色含光漏湘楮。","云母琉璃俱有神，银河牛渚恍通津。","常抛金弹誇豪侠，独抱明珰泣蜃人。","火具时时闻战伐，飞流一一绕勾陈。","谁家帘幕留欢住，几处笙歌按拍新。","节物人情岂相待，后夜迟迟出沧海。","每惊旧发羞鸾镜，却倚新声填欸乃。","仙人自古有羡期，书生妄意图元恺。","但祈灯月两相和，岁岁年年常不改。"]},{"t":"秋日入佘山观昭庆三栝松","f":"七言古诗","c":["云间山水称绝奇，简远开豁无不宜。","村村花柳足佳丽，亦有落落蛟龙姿。","新秋晴日照古寺，鸣丝偃盖风离离。","阁前两株疏且瘦，左右拱揖如佳儿。","独怜众草没昙院，不见十尺围桐皮。","稍偏一株在东麓，蓊翳拔起三虬枝。","擎空似欲拿云雨，匝地更与成涟漪。","我闻佳树以地贵，豫章赤水非人为。","云间栝松重昭庆，往往盆盎时见之。","此来得共恣幽赏，山深谷暝何迟迟。","未嗟才大难为用，颇恨地僻稀相知。","摩挲风霜有古意，指点时代多遐思。","东廊一僧最朴野，导我屋角开重篱。","为言秋高八九月，风前落子堪萌滋。","迩来区赋要往役，此事久废从先师。","山中岁月已如此，世上风波纷路岐。","坐成三叹倚石壁，欲别未别空犹夷。","苍髯戟戟老发秃，白云冉冉游丝垂。","此山九峰居第一，谁为姓佘谁所遗。","或云种茶似阳羡，吴歈楚调聊相随。","陆家放鹤还沙际，张季思鲈今水湄。","他日青松能待我，茯苓琥珀总宜诗。"]},{"t":"悠然亭","f":"古风","c":["濠梁有鱼水，庄惠无尔我。","吾犹恨多事，忘言岂不可。","俯仰天地同悠然，鱼忘于水水忘渊。","澄鲜一色月转汉，泼刺数声风起船。","封君本是方叔后，老气盘空薄牛斗。","长啸江湖范蠡书，逃名松菊王弘酒。","庭中潴泉泉上亭，亭外万叠青山青。","有时出云作细雨，此际游小开南溟。","坐来一日当千日，未论他年百四十。","海棠花发春气浓，一片胭脂镜中湿。"]},{"t":"赤壁歌","f":"楚辞体","c":["我闻赤壁乃是曹刘之战场，襟锁巴蜀，喉控荆襄。","丹崖插江几千尺，疑是煆烂半面之昆冈。","下有波涛走万里，上有椒桂森众芳。","紫苔斓斑伏虎豹，红云缥缈游凤凰。","当时烈烈南风发，北岸舟楫灰飞扬。","蛟螭失势易为缚，何奈太白多寒光。","时移运去疾流电，江山如故天苍苍。","平生好奇癖山水，梦寐彷佛徒彷徨。","昔有苏子瞻，来自白玉堂。","扁舟夜载七月凉，月明把酒酹周郎。","英雄多有恨，涕泪徒浪浪。","尔来数百载，胜事不可常。","陶子五月使潇湘，殷勤请戒十日粮。","黄州弭节聊徜徉，须凌绝顶出上方。","翘扶桑兮俯八荒，清风时来声琅琅，为我一诵秋水章。"]},{"t":"子醇雨后陪宿道馆有赠","f":"七言古诗","c":["春灯着花照春雨，窈窕仙宫对床语。","龙池冥冥杂花寒，鱼书雁信多愁绪。","一百五日又已过，二十四桥何处所。","容台美人锦绣肠，能为楚歌歌白苧。","候我明光起草馀，更约城南看花侣。","长安风尘缁素衣，故园魂梦牵春渚。","三军草露白铁袍，五侯宅第黄金炬。","闻鸡起击珊瑚鞭，共慰此身同逆旅。"]},{"t":"夜泊真州","f":"古风","c":["前岁泊船真州江，满船明月摇船窗。","今年复向真州住，黄昏待月月欲吐。","明月照人无丑好，来来去去令人老。","一杯船尾得月多，听我试唱真州歌。","真州歌将奈何大，船如屋船船官鹾。","危樯插空飞不入，铁锁钩联密如织。","语音嘈唧了不分，同是经商异南北。","居民大半趋四坝，倡女沿河晚妆罢。","短担双檐唤卖鲜，小舠三桨轻如驾。","连楼夹巷簇簇新，家家许住异乡人。","共道今年生意少，下客折本上客贫。","江南春山叠叠绿，荆楚转运遥联属。","南京供奉日日过，金字黄旗去还续。","君不见文信公，几陷虎口中。","但愿路日通，不怨东西逢逆风。"]},{"t":"雨后于都司分种红蕉","f":"七言古诗","c":["今日不知来日事，百年枉作万年图。","青青一种芭蕉树，春雨敷荣秋雨枯。","忆昨岁晚雪飞白，都阃门墙映红碧。","依稀记得建阳过，南北东西总为客。","建阳县令薛给事，开尊北堂邀我至。","对花云是美人蕉，不怕风霜逞娇媚。","前月京师附书还，为传给事死谏官。","见花怜花为花恼，万丈雪山毛骨寒。","都司刘郎举武举，每以危言动天子。","螭头豹尾不肯留，独鞚花虬行万里。","万里边庭绝羽书，手种芭蕉三百株。","一宵蹄齧苦不戒，粉碎玉人伤绿珠。","共汝朝来有归兴，细雨沈沈满三径。","携锄斸取旧根荄，且种窗前欹枕听。"]},{"t":"题李蒲汀学士所藏赵千里射熊图","f":"七言古诗","c":["王孙藻思锦绣纹，点染青山萦白云。","避雁霜高锦树出，射熊风劲角弓闻。","似是西原猎场下，公子翩翩齐骋马。","捷如流电气十倍，满弯明月神潇洒。","沙平草浅石径长，左驰右突不可当。","直前一发遂得隽，岂但百步能穿杨。","古来妙传誇绝艺，此幅摩挲今几世。","周诗蔼蔼歌梦祥，汉馆离离是何处。","蒲汀学士人中龙，勘画披图最有工。","致身本在霄汉上，雅兴时落山林中。","武功文事亦素具，细认丹青有奇趣。","尚父曾闻载后车，宣尼尚且供先簿。","试看更兆掌中珠，雄风骏骨头角殊。","他年隔座屏风里，唤取良工拓此图。"]},{"t":"南宫北郭踏雪","f":"七言古诗","c":["前夜维扬玩寒月，今朝燕冀寒踏雪。","百年快事能几回，谁料兹行两奇绝。","漠漠郊原一掌平，纷纷珠贝缀难成。","玉堂瑶圃随行上，缟带银杯逐步生。","复有软舆和盖重，何似渔翁一蓑冻。","白马翩翩千里骄，红旗闪闪长亭送。","臂鹰走狗谁家儿，颇忆东原年少时。","双飞一箭穿云下，九尾千年匝地驰。","壮气老来馀白首，熊裘貂帽鹅黄酒。","扫竹寻梅何事无，柳絮梨花随处有。","东方又动朝日红，耀色流光四望通。","矮屋欲埋孤出栋，遥山先映最高峰。","试问天公资发育，前须巽二后滕六。","苍生赤腹望丰年，黄扉紫阁尤惊目。","谁持坚白攻异同，燮理调和唯至公。","不见狻猊巧抟换，消得东皇一夜风。"]},{"t":"文峰歌为郑正郎","f":"古风","c":["云路东南永，闽关紫翠重。","蓬莱宫阙近，突兀见文峰。","文峰拔地几千尺，巨灵夜卓凌空碧。","特立疑从五老分，高标正傍三山出。","三山秀色钟异人，文峰先生尤绝伦。","身同砥柱障东海，力挽华岳开西秦。","二十明经取上第，六曹郎署称无二。","作雨为霖本有期，擎天捧日真能事。","当今好手张平山，写出巉岩水墨间。","美人被服何雅素，坐看白云相往还。","先生爱山兼爱画，风物江南两奇迈。","停骖驻节费追陪，高堂素壁时张挂。","旧家门巷对山居，共道相传百代馀。","开图宛见文峰面，若论连城玉不如。"]},{"t":"竹岩歌","f":"古风","c":["君不见程公竹岩重新安，上有凤雏双羽翰，下有龙孙欲迸青琅玕。","嶙峋白璧连城价，摇动清风六月寒。","美人岁晚爱颜色，身踞虎豹凭阑干。","秖今仙游向湘浦，唯馀落月辉林峦。","调和六琯制大雅，镇压百里成伟观。","孟生泪尽不复茁，唐皇感之比二难。","江南程氏古司马，别有伊洛分派如波澜。","谁云今人不如昔，竹岩太中相应看。","仲氏外台握风纪，俨哉伯子和气端。","正公壁立几万仞，要比季子铁豸冠。","四时正气郁不改，东南秀色若可餐。","扫除炎热砺世钝，一为长歌天地宽。","呜呼竹岩不可见，见此孤标遗荫回风湍。"]},{"t":"西岩歌","f":"古风","c":["君不见昆山产玉高嶙峋，当年一片称绝伦。","迩来几千载，元气酝藉含至淳。","乃有参天卓地壁立之西岩，窅窱洞府栖仙真。","春色桃花误流水，秋清桂树当月轮。","紫芝瑶草满下界，祥虹瑞霭往往早暮相鲜新。","箕山将让许，武陵聊避秦。","远观田变海，昔传岳降神。","自如先生古柱史，甲第华堂住其趾。","少年风彩真玉人，陆家兄弟安足齿。","满门忠孝世所希，江南数作鸣珂里。","状元宰相应黑头，季弟今为天下士。","大儿文学早作畿辅师，直言忠谏丹青里。","小儿颖异似杨修，已署门生拜天子。","有孙行年十六七，一举乡书众中起。","珊瑚与珠树，过眼纷可喜。","先生况是真仙才，酒尊常对昆山开。","消除日月归棋局，舒卷丝纶有钓台。","屦杖登山疾于驾，有时临海望蓬莱。","玉耶人耶两难辨，但见秋容秀色远与鸾鹤相徘徊。","五千道德閒常诵，三度蟠桃手自栽。","只今七十逢初度，刚是浮生第一回。","山中好风日，天末负趋陪。","短篇遥当长年颂，愿借澄湖作寿杯。","参天卓地之西岩，永与朱颜黑发相追随。"]},{"t":"题画","f":"七言古诗","c":["春风花柳溪桥路，剩有韶华管送迎。","隔岸青山千尺起，闻歌多少别离情。","此图点染还清润，似是钱塘戴文进。","张公好画如有神，高筑金台同买骏。","内庭多暇日正长，湘帘半捲当华堂。","时时拂拭见古意，欲效丹青比梦良。"]},{"t":"雨中汎舟闻座客琵琶","f":"七言古诗","c":["兰舟急雨横银塘，水芳沙鸟滋暮凉。","烟云弥望接蜃气，楼阁失地含龙光。","于时披襟坐盘薄，爱听潇淅鸣舷艎。","座中有客偏好事，独把琵琶临醉乡。","一拢一撚有古意，欲弹未弹先断肠。","四弦嘈嘈乍入手，似与风雨随低昂。","曾传青衫泣司马，岂是紫塞啼王嫱。","孤臣忠愤重离别，壮士感激多慨慷。","鹍弦铁拨世希有，此曲杳眇尤难当。","谁裁无价紫桫椤，乃有双盘金凤凰。","我生两耳才具足，妙解那得如中郎。","老怀政尔苦冰炭，试遣陶写凭消详。","须臾返棹更东下，云物一空江水长。"]},{"t":"可泉图","f":"七言古诗","c":["我识可泉三十年，今朝为赋可泉篇。","秦川蜀川浑漫尔，相忆相逢俱偶然。","君家去天才尺咫，云树苍苍万山里。","羲昊曾留画卦文，陆郎未试煎茶水。","当年妙小富文章，春日承恩上玉堂。","客过每劳占剑气，人传从此破天荒。","一朝汨没青山下，印月行风倍潇洒。","遥从西郡梦三刀，又向南台骑五马。","皖城东下是苏州，银色流璃万顷秋。","匡庐天外飞犹落，杨子江心泥不流。","济南突地七十二，钱塘江头水西寺。","还将词翰旧风流，总属参知新政事。","一夜秋期梦故乡，某山某水暂徜徉。","如流车马来阿曲，似水门庭复晋阳。","晋阳相看吾已老，开图宛听泉声好。","白练横拖万里长，银河倒挽三山小。","溶溶漾漾更逶迤，东流终向凤凰池。","聊从汉使乘秋日，正是商岩大旱时。","满地苍生望霖雨，天瓢一滴何如此。","由来邹孟达逢原，安用蒙庄齐物理。","谁云嶓冢不胜舟，谁谓昆崙最上头。","请看逝者无昏旦，化作江河入海流。"]},{"t":"松鹤图","f":"七言古诗","c":["遥空受秋万里碧，松露团团野花白。","藤梢橘刺纷陆离，细水涓涓绕云石。","我疑此图是玄圃，中有双禽鸣且舞。","霜翎砂顶足生韵，玄裳风轻月将午。","当家妙品在逼真，况是写生须入神。","古来高人重图画，欲令见者常如新。","我闻胎仙三千岁，摩挲此幅能几世。","乃知丹青空尔为，别有不朽超绝艺。"]},{"t":"枯木竹石图","f":"古风","c":["人间何处真不俗，雨后山前两竿竹。","雪村老人幽兴多，落笔龙孙削苍玉。","离离乱石出涧底，古木压枝虬欲起。","相思天际望美人，月明一片湘江水。","君不见工师取才，伶伦裁管。","兼收并蓄，截长补短。","开图识苦心，听我歌款款。"]},{"t":"次韵黄如英听管生弹琴","f":"七言古诗","c":["逸人最爱冯虚阁，手弄丝桐自酬酢。","清安身世甘寂淡，富贵交亲供谀噱。","天空境静初按谱，掩抑悲凄更丰约。","淙淙岩背堕春泉，历历林梢下秋箨。","缓猱急引大可怜，含徵流商调相错。","初闻古意三叠高，旋见失势千丈落。","勇如壮士提戈戟，静似佳人洗丹垩。","吴山积雪开四窗，夜静金炉火犹烁。","是时相对拥青绫，顿使烦襟坐来铄。","中郎此意妙莫传，炊爨之馀尚堪凿。","看君幽兴正得意，我和险诗聊善谑。","须臾鼓罢阳春曲，门外青山映寥廓。"]},{"t":"楝塘","f":"七言古诗","c":["甬东水树清深处，楝花风动黄梅雨。","乔木由来世泽家，清溪合有高人主。","主人本是种德人，种成玉树高嶙峋。","青骢白豸风霜古，紫诰金泥雨露新。","苦县遥宗元姓李，今代闻孙还柱史。","弹压争知重有山，门庭不愧清于水。","绣斧银章使节归，摘花酿酒映斑衣。","明堂正要求梁栋，坠子成林大十围。"]},{"t":"和答张子醇索砚","f":"七言古诗","c":["容台大夫古列仙，谪向人间年复年。","当时正坐风骚客，今日犹为笔砚怜。","吴东片石青山里，箬裹藤封四千里。","力微任重致不多，空对知音惭未已。","看君笔阵何堂堂，真堪作史蔡中郎。","自须剪赠西湖水，化作虹霓万丈长。"]},{"t":"边城谣","f":"古风","c":["金木难，丑之年，大同六月风尘连。","将军死绥战士哭，束刍斗米当十千。","司徒受命出饷边，纶巾羽扇何翩翩。","指挥捆载赴急援，上山下山鱼贯联。","营中望见气十倍，抆涕裹血张两弮。","君不见丞相昔日下三川，木牛流马何其便。","司徒之功相后先，司徒之功相后先，请观渭上田。"]},{"t":"卧龙谣","f":"古风","c":["龙卧不行天，龙吟梁甫篇。","借龙何处所，行雨遍三川。","三川山势常含雨，北风不断东风驶。","赤龙上天掉龙尾，更遣流星促龙起。","定军山中龙骨藏，龙光夜夜拂咸阳。"]},{"t":"石桥谣","f":"古风","c":["一挥千黄金，不如一石梁。","江水险不测，人命薄于霜。","南州十月水涯降，临流不渡愁褰裳。","家住江水北，市在江水阳。","朝渡给薪米，暮渡携酒浆。","有时浪急石齿齿，对面千里空断肠。","东邻周封君，有子登玉堂。","一朝发私帑，波面流虹光。","方车结驷若坦道，石可泐，德难忘。"]},{"t":"春山辞","f":"楚辞体","c":["登长坂，望故都，辞帝阍兮南骛，渡河梁兮春波。","时一去兮难再，怨芳岁兮蹉跎。","赴山灵兮夙约，返初服兮苧罗。","林深兮春暮，草靡兮云和。","猿避席兮空谷，树开障兮崇阿。","左兰兮右芷，牵芙蓉兮鞶萝。","聊徜徉兮寤叹，澹容与兮啸歌。","望佳人兮不可即，眇千里兮伤如何。"]},{"t":"风泉竹石图","f":"楚辞体","c":["启玄圃兮缬群芳，淡容与兮翱翔。","望帝子兮极浦，思美人兮潇湘。","幽篁兮怪石泉，激风兮鸣珰。","神舒兮境寂，开药房兮兰堂。","冠切云兮瑶佩，飧沆瀣兮夜未央。","抱贞节兮自媚，日夏烈兮秋霜。","羌秀色兮可揽，邈江山兮苍苍。","游夫君兮太清，跨虎豹兮骑凤凰。"]},{"t":"沛水行","f":"七言古诗","c":["沛水东决如沸汤，家家水痕强半墙。","麦苗不收枣树烂，鸡犬缚尽无糟糠。","河上丈夫七尺身，插标牵女立水滨。","自言丰年娶得妇，结发甫能勾十春。","隔年生女如获宝，阿翁提携阿㜑抱。","两岁三岁学步行，邻里尽誇皮肉好。","今秋粮限不过年，县官点夫夜拽船。","可怜此女八岁馀，决劵只卖四百钱。","钱财入手容易尽，但愿分投避饥馑。","借问上船何处州，异日经过烦附信。","答言家住越州城，绿树青山好托生。","桑树养蚕常着帛，湖田种稻早炊粳。","听罢那禁双泪流，相逢只合死前休。","闻道越中多赋敛，父北儿南两地愁。"]},{"t":"悲开河行","f":"古风","c":["丈夫乍可道路死，挥泪听我开河篇。","开河五月暑有毒，亢暵百日河无泉。","枯蓬赤乌汗如雨，长夜白鸟雄似鹯。","游子去家三千里，况复病体累十年。","秖知出门多历览，谁料来日当大难。","木皮束棺灵寄寺，县吏检尸巫布筵。","忆昔当时别家日，父母挽留妻子牵。","自言省弟到上国，自谓赋命天无偏。","地岂长沙人赋鵩，道如陋巷鬓凋蝉。","弟不及见亲已远，奈此半路连弃捐。","重泉杳杳不复旦，游魂黯黯何由还。","相逢亲旧烦附信，南到会稽北到燕。","堂上老亲嗔恶梦，闺中少妇焚纸钱。","长安空悲听雨约，旅馆那得共被眠。","哭夫哭兄兼哭子，呼神呼地复呼天。","一死辛酸尚堪忍，两地呜咽真可怜。","君不见封侯无成向沙漠，马革裹尸犹是贤。"]},{"t":"重廿五行","f":"七言古诗","c":["前月今日风若掣，今月今日雨不绝。","颓垣败壁补未完，注栋倾盆势尤烈。","对床不辨儿女啼，悬天但恐星河决。","遥看密泻同织丝，复有大片如飞雪。","夜来沾洒愁图书，似闻挥霍鸣金铁。","昨听父老指顾言，目数群龙迸空裂。","海中沙县全城翻，邑里谯楼半腰折。","皇天高照正森严，圣主中兴自超轶。","岂伊玄化复偶然，无乃苍生自诒孽。","拥衾转辗苦待明，四野茫茫混鱼鳖。","禾头生耳须浪传，灶底产蛙幸虚设。","不然东南财赋区，宁免宵旰劳符节。","小臣幽忧才一家，终岁饥寒讵堪说。","仰天端拜意独深，捧日何能计应拙。","挽回光霁敢望多，今夕明朝事终别。"]},{"t":"金陵行","f":"五言古诗","c":["钟山郁嵯峨，冉冉朝出云。","昔日秦始皇，于此埋黄金。","埋金空复尔，千载悲叹深。","石头绕其右，长江亘其阴。","我祖造帝业，此地遂发灵。","双观切云霄，宫殿何森森。","下有高楼台，甲第贲丹青。","缙绅罗其中，白马扬金铃。","山川此都会，登眺亦峥嵘。","送君金陵去，歌我金陵行。"]},{"t":"江南行","f":"五言古诗","c":["仆本江南士，请歌江南篇。","江南佳且丽，沃野多良田。","道旁采桑女，湖中木兰船。","礼让季札后，文学言偃前。","昆山产良玉，自古盛才贤。","东通沧海波，西接阖城烟。","既饶鱼稻利，复当大有年。","登眺何郁郁，井市互纠缠。","商贾竞启关，逋流愿受廛。","使君楚邦彦，敷治若烹鲜。","新从天上来，端坐理徽弦。","齐民本同性，嗜好贵有先。","谷中自虚旷，岂曰声难传。","酌酒听我歌，我歌慎勿谖。"]},{"t":"伤哉行","f":"七言古诗","c":["伤哉薤露日欲午，昨日草堂辞故主。","黄梁已熟梦初回，百岁相将一柸土。","北邙山下纸钱风，杜鹃声中寒食雨。","留得功名上墓碑，行人立马泪如缕。","椒浆满地不胜愁，日落玄猿为起舞。","流传义事死不泯，会有馀休大门户。"]},{"t":"蜀山行","f":"古风","c":["蜀山何苍苍，蜀江何汤汤。","江山相望郁不改，中有怀贤泪几行。","泪行洒向嘉州道，嘉州高士忽已老。","高士坟前四尺碑，北风细雨摇白草。","至今人传高士德，侍母能吞病回食。","读书千卷老不忘，白首犹能数行墨。","有文孙曾振其武，巍科达官相次取。","千秋万岁安家祠，瓜瓞绵绵称始祖。"]},{"t":"骏马行","f":"古风","c":["殷子有奇骨，昂藏若骏马。","康庄在远道，伏枥甘土苴。","长安一朝别我去，再三挽留不能住。","潞河新有下滩船，到家正及朱炎暮。","君家本在齐鲁墟，枫林瑟瑟临前除。","小楼画槛荫林樾，中有先世千卷书。","北堂慈母发垂领，倚门望儿悲短景。","小弟今年十四五，弄笔时时学驰骋。","上奉母颜下课弟，日有馀功拟丛桂。","病骨偏宜秋气凉，药囊閒却参苓剂。","登高回睇望泰山，恍见仙人时往还。","翩翩白鹤不可借，流光日夜凋朱颜。","朱颜一往那再复，惟有功名留汗竹。","志士偏增日暮悲，佳人易感穷途哭。","忆昔虚堂坐论文，辞锋往往倾先秦。","谈时屈指数汉魏，叹息六代何无人。","殷子奇气鲜有匹，人间八宝光耀日。","吴郡徐卿吾畏友，每每到君赏高逸。","君不见九方皋，胡能按谱索马毛。","愿子加餐善自爱，天闲十二终当豢尔曹。"]},{"t":"画松行","f":"古风","c":["毕偃去已远，马夏新有声。","携将秦大夫，从事褚先生。","幽篁压枝兔丝飏，雪后冰前俨相向。","浅红腻紫多好颜，端合低头丈人行。","蛰龙一夜闻雷起，况复笙篁风满耳。","县斋昼静帘影重，聊伴诗书当行李。","君不见前年营建采山林，竹头木屑俱千金。","天南别有擎空树，回岩叠嶂深更深。","岂不中梁栋，地僻诚难寻。","由来才大难为用，始觉良工真苦心。"]},{"t":"东家行","f":"七言古诗","c":["东家有女嫁西家，不羞白璧倚蒹葭。","结发初疑连理树，牵情复比并头花。","并头连理愿千秋，夫婿今年轻薄游。","斗鸡远过夷门市，系马时从白下楼。","斗鸡系马聊应尔，可怜年华付流水。","月离三五弓下弦，春当九十花成子。","千叠关山音信稀，传言绝塞寄征衣。","身骑大宛乌龙去，手取将军金印归。","乌龙金印两难成，边境萧条不可行。","黄沙万里双睛暗，白雪千山五月明。","风月空闺难独守，团扇絺衣岂堪久。","箜篌弦上公渡河，羌笛声中折杨柳。","杨柳秋来满故园，良人何日返东门。","黄金绕身久离别，不如贫贱暂温存。"]},{"t":"西州门行","f":"古风","c":["怅望西州路，经年感旧恩。","尝因石头醉，不觉至州门。","至州门，应恸哭，舆疾归来尘满目。","羯儿江上兵八千，鼋子车中年十六。","苍生满地终奈何，一枕白鸡春梦足。","中原心，东山志。","两难凭，俱不遂，几人能有羊昙泪。"]},{"t":"分金行","f":"五言律诗","c":["古人重结交，何必千万人。","一一苟知己，安得各许身。","嗟哉管鲍交，迹远心逾亲。","后来相齐功，宁令负分金。"]},{"t":"猛虎行","f":"古风","c":["天生尔物何雄发，咆哮一声振林樾。","伥魂离离腥风动，山下行人竖毛发。","乳子曾闻昔扰驯，食牛谁料今搪突。","太山啼妇那忍闻，血肉纵横叠枯骨。","君不见东家近日射生手，弯弓百步能穿柳。"]},{"t":"射虎行","f":"古风","c":["海壖饶稻粱，日夕满牛羊。","忽传虎南下，远见目炬光。","腥风猎猎振林木，前村惊走后村哭。","南衙仙尉滇南才，白马彫弓美如玉。","太平寺西日卓午，一箭杀虎如杀鼠。","长官迎劳吏欢呼，负嵎长啸今何处。","君不见南山白额长桥蛟，眼中此尉人中豪。"]},{"t":"拟饮马长城窟行","f":"五言古诗","c":["密密墙头柳，凄凄野中露。","徘徊念远人，即目不成睹。","别离谁不然，相思逐流年。","日短愿夜长，梦中得相怜。","食荼知味苦，登高知路长。","耿耿怀隐忧，双轮绕柔肠。","客来异乡县，遗我一匹绢。","双手认封题，中有夫婿书。","上言紫貂弊，下言近瘦肥。","持刀欲裁衣，仍将比残机。"]},{"t":"邃庵","f":"古风","c":["时惟文明，笃生哲人。","若大厦斯搆，巨木既抡。","江汉濯灵，于国之南。","来游来观，有兹邃庵。","于穆邃庵，奠长安之里。","先民有言，人远室迩。","仞墙既辟，朗牖载启。","迈心昭旷，崇志玄始。","承明既下，遵此深闳。","耽耽渠渠，以造尔后生。","孰曰一室，而匪八荒。","君子善居，旁达煌煌。","凡此煌煌，惟邃之功。","故岳深则蓄，川汇攸同。","诞求明德，兹庵是出。","出则外攘，入则内谧。","庸是基程，光我王室。","帝用勤止，佥曰允谐。","三事是寄，以陟崇阶。","对扬休命，执德不回。","秉国之钧，邃兹弘开。","孰求勿获，胡致匪才。","以延我基绪，于皇遐哉。"]},{"t":"修竹篇三章","f":"古风","c":["瞻彼修竹，薄言眷之。","依依庭除，托植在兹。","我悦我亲，以况其仪。","竹之苞矣，以慰我思。","瞻彼修竹，其色如玉。","眷言顾之，岂曰空谷。","出则尔恭，入则尔复。","君子之居，清风穆穆。","瞻彼修竹，凤凰于飞。","岁聿云莫，泥泥有辉。","崇是正直，以保中虚。","君子万年，神明所依。"]},{"t":"园中芭蕉产甘露金色若莲花而大几盈尺欣赏一首","f":"五言古诗","c":["园古草木茂，气和休祥集。","老堪寄一廛，当此三江入。","绿蕉隐轻雾，紫葩垂巨实。","骈房类马齿，厚味过蜂蜜。","蟠桃经千岁，优罗竟谁挹。","缥缈仙人掌，馨香鹦鹉粒。","珍奇徒饱闻，何如手可拾。","文园素中消，起痾冀一吸。","太华玉井莲，菡萏黄金湿。","孤标自无群，惆怅临风立。","食芹想明主，欲起为什袭。","倚槛良有情，搴芳偶无术。","把酒一赏之，拊膺百愁失。","还闻制颓龄，大药傥可及。","欲草贞符篇，缅惭春秋笔。"]},{"t":"听雨","f":"五言古诗","c":["白发日夜长，青草缘阶生。","江村荷时雨，潮田惬耦耕。","稍稍辨远树，依依见孤城。","鱼鸟亦何意，上下如有情。","抚已得良晤，与物本同生。","遭逢百年间，重阴几开晴。"]},{"t":"俨山西偏凿方塘而未及泉四面洼空若壁适春潮暴涨悬溜而下若珠玑万斛水晶帘一段迸空垂舞喷射照耀夺人目睛而冲撞漰湃顷焉出声又若张乐洞庭之上信天下之奇观也作诗纪之","f":"五言古诗","c":["九天落银河，一部喧水乐。","自昔饫奇闻，于兹破尘浊。","东风吹海门，潮头拥蛟鳄。","漫坡已铺练，溜崖遂悬瀑。","雅音发铿鍧，天籁韵宫角。","横开水晶帘，乱飐珍珠雹。","回风拂沤沫，落日漾瀺灂。","排波摧冰霜，荡空惊鹳鹤。","虽惭达人观，缅希百川学。","无私理则然，盈科仰先觉。","嗟予方寡陋，昔贤何渺邈。","垂老卜此居，偶尔期浣濯。","林木日已繁，茅衡向堪斲。","相要素心人，文史事商搉。"]},{"t":"庆寿寺西廊斋居赠沈仁甫","f":"五言古诗","c":["山陵届良吉，群寮秉精诚。","梵宫庭宇静，愿托尘土形。","华镫照木榻，四面凄以清。","璧月度云汉，珠斗当女城。","值我同心友，相依叙平生。","弱龄结高谊，白首有定盟。","君为涧中水，我如随风萍。","萍飘入涧水，荡漾永合并。"]},{"t":"送王存约赴惠州","f":"五言古诗","c":["远别当长歌，歌短调转苦。","鄙生寡谐合，屈指那可数。","夫君重意气，交谊薄太古。","岂惟到尔汝，未暇辨宾主。","同怀奉圣明，何心慕缨组。","契阔万里途，恨无冲风羽。","客宵仰云天，明星灿三五。"]},{"t":"清河晓发","f":"五言律诗","c":["清霜肃晴野，秣马乘暗发。","长逵会凄风，疏林薄残月。","三五东方星，横斜北斗没。","似闻度前陂，苦寒伤马骨。"]},{"t":"游虎丘憩剑池上作","f":"五言古诗","c":["盘石广且平，万木郁以苍。","中有高楼台，翼翼何煌煌。","黄金涂殿柱，五色错中堂。","问是谁所居，缁衣礼空桑。","感此金石固，变迁不可量。","始因伯业显，中更晋诸王。","况以血肉躯，焉得久乐康。","促膝临涧水，涧水清且光。","澄碧照我衣，可辨黑白黄。","俯身濯长缨，素手激清凉。","适意易为别，怅怅不能忘。"]},{"t":"西堙晓发","f":"五言古诗","c":["日出山雾黄，五月气犹肃。","溟濛十里馀，辕马伤局缩。","岂不惮驰驱，所欣恣余目。","沈沈树隐岑，稍稍黍抽陆。","仰观云中岫，俯视涧底谷。","境深工出奇，地古尚馀朴。","驾言问民风，十稔九无熟。","岩嵌时突烟，委复閟土屋。","行行重嗟咨，明光竟遗覆。","予本登才贤，幽探事陶育。","抚此晋阳区，孱绵愧食肉。"]},{"t":"送王宪副廷吉赴蜀","f":"五言古诗","c":["出郭已可爱，何况郊外游。","十里历大陆，偶此值杪秋。","黍稌毕刈穫，萧条见高丘。","密云酿微雨，轻尘敛前驺。","送客远行迈，道路阻且修。","临岐一觞酒，去去不可留。","丈夫怀明德，仳别难自由。"]},{"t":"杂兴","f":"五言古诗","c":["江河赴东流，日月西驰速。","天运有乘除，人事工报复。","如何首阳薇，一去无后禄。","子云最和同，符命手自录。","婉婉舒我言，往往覆人国。","亦知重身图，谁家非骨肉。","伊余六尺躯，宁用千钟粟。","祸福止一时，安能辨直曲。","浩歌归去来，田中有茅屋。"]},{"t":"晨起南牖纳凉","f":"五言古诗","c":["庭柯含远风，时暑散烦襟。","岂乏华屋爽，适我良所钦。","颇爱陶彭泽，五斗北窗阴。","南薰来前楹，何必怀千金。","野居自云乐，俯仰遂素心。","素心亦何有，息影眷山林。","岁月忽已迈，江湖一以深。","手持一编书，中有太古音。","诵言消永夏，是非遗昨今。"]},{"t":"坐月效古","f":"五言古诗","c":["肃肃迨秋夕，明明月流光。","众星灿若珠，三五正纵横。","居人不能寐，客子怀故乡。","大化无停运，弦望倏相当。","鸿雁多哀思，庭柯变青黄。","时往老将至，悲来夜何长。","咏彼蒹葭诗，怅望宛中央。"]},{"t":"俨山精舍晚意","f":"五言古诗","c":["林深暮烟紫，海近秋月白。","稍稍神虑淡，悠悠寺喧隔。","乾坤等逆旅，谁非远行客。","遣此百忧端，栖我一亩宅。","楚狂虽忘世，湘累竟何益。","寄情混渔樵，托契友金石。"]},{"t":"新秋别三首送唐士回 其一","f":"五言古诗","c":["悠悠都门道，执手从此辞。","明时各致身，那复计别离。","君已寄民社，我愧空文词。","相视各不语，秣马当风嘶。","马嘶识故道，落叶恋故枝。","仰视云汉间，牛女将秋期。"]},{"t":"新秋别三首送唐士回 其二","f":"五言古诗","c":["潞水日滔滔，豆花复离离。","新凉动长河，楼船正南驰。","相望日已远，何以慰相思。","愿多东来风，吹雁过京师。","楼头夜初永，起坐薄罗帏。","团圆向人月，鉴我怀中私。"]},{"t":"新秋别三首送唐士回 其三","f":"五言古诗","c":["与子三岁间，一岁一聚首。","人生少百岁，能共几尊酒。","子年三十馀，我已二十九。","后时聚散期，日月能俟否。","同心多仳离，良会不可久。","奈此参与商，任运付何有。"]},{"t":"迟严介溪太史","f":"五言古诗","c":["远至卜灯穗，近约嗔路遥。","娟娟十载别，盈盈中夜潮。","僻地安足赏，佳人不待招。","榆柳含新妍，泉石共孤标。","虽惭陈子榻，乃有颜生瓢。","开径屡延伫，永冀念久要。"]},{"t":"我有平生人二章 其一","f":"五言古诗","c":["我有平生人，故被云锦裳。","灼灼桃李颜，娟娟饶清扬。","婉婉吐丽辞，纤纤素手长。","后宫选名姝，三千一身当。","远从二妃游，历览周八荒。","膏车驾言迈，使我涕泗滂。","念君不能已，讴吟遣巫阳。"]},{"t":"我有平生人二章 其二","f":"五言古诗","c":["我有平生人，善鼓朱弦琴。","清商发高弹，泠泠太古音。","万人罗列听，叹息一何深。","玉衡指孟夏，朱明自南侵。","曲中正悠扬，弦绝调不任。","鸾胶是何年，长令负此心。","岂不增悲辛，古意日已淫。"]},{"t":"连理词","f":"五言古诗","c":["春草碧高阡，春晴寒日烟。","下有双白璧，上有芳树连。","连理复连根，根深叶何鲜。","大枝高一尺，苍苍欲擎天。","孙枝复秀发，直起拂云穿。","树色耀白日，璧光掩重泉。"]},{"t":"出土城即事","f":"五言古诗","c":["粼粼原隰远，迟迟丽景晴。","始欣出尘想，遂畅同物情。","夭桃出颓垣，曲涧萦旧京。","民俗远渐朴，山照去犹明。","天关古无对，边尘今自清。","抚时感雨露，缘礼报生成。","因公遂攸往，倡言纪兹行。"]},{"t":"发昌平","f":"五言律诗","c":["山城丽淑景，沙堤度轻舆。","身从云中归，疑有云生裾。","离离列巘崿，蔼蔼越里墟。","时有桃李花，无言临涧隅。"]},{"t":"杂诗","f":"五言古诗","c":["苦乏山林资，来此朝市游。","日月不相待，华发变清秋。","晞心中道获，懔怀末路忧。","浮阴隐层城，轻冰结洪流。","孤语冀冥契，同逝匪良谋。","缅惭南征鸿，岂曰道里悠。"]},{"t":"游润州城南诸山","f":"五言古诗","c":["日斜始取路，春服遂游行。","街回复巷转，西望见岒岭。","道旁车轮推，呦呦何嘤嘤。","平涛灌时蔬，健妇日把耕。","意惬勚不辞，奋步直前征。","荆榛钩我衣，烟霏拂我缨。","忽焉凌绝顶，俯视江与城。","一气漫浩浩，清飙四傍生。","藉草聊小憩，为乐不可名。","暮景渐微茫，欲下仍含情。"]},{"t":"晨发柯村","f":"五言古诗","c":["蔼蔼山川曲，朝曦散秋光。","草露尚未晞，岭树变微霜。","白云满长谷，此中多深藏。","遵养共时晦，灭景不可望。","扰扰倦行役，拙诚难可将。"]},{"t":"上峻坂临崖","f":"五言古诗","c":["少陵有佳句，再拜扶病翁。","掖予登峻坂，此事将无同。","好奇已成癖，履险始有工。","流泉喷玉雪，危石摇青红。","下临千仞渊，上摩九万风。","秋阳正皓皓，极目双飞鸿。"]},{"t":"率童仆出田","f":"五言古诗","c":["旭日照桑坞，乳鸠拂林坳。","农务日就理，驾言赴东皋。","东皋有佳适，云是江海交。","弥望眇孤帆，凌空俯危巢。","伯禹功未泯，季札风犹高。","戢戢出士女，田田及土膏。","鹿门有遗响，子云徒解嘲。","违已讵非病，喟予伤系匏。"]},{"t":"理园","f":"五言古诗","c":["庭下石齿齿，水际花冥冥。","宿痾霁暑雨，时还枕孤亭。","百虑静以遣，世纷老旋经。","所存复馀几，兀然顾兹形。","呼童理荒秽，森爽出众青。","宣父叹后凋，湘累眷芳馨。","孰云草木姿，奄忽随飘零。","持此遂久要，庶以娱暮龄。"]},{"t":"秋怀","f":"五言古诗","c":["仰观流大火，圆魄复西驰。","未睹凌霜叶，先见陨风枝。","罗帏閟清景，瑶瑟流哀思。","掩抑不成调，清商汎朱丝。","恐惊高楼妇，荡子阻归期。"]},{"t":"赠别安鸿渐给舍四首 其一","f":"五言古诗","c":["西驰万里道，送子不及远。","万里非所嗟，觐子恐岁晚。","青青蚕丛山，历历太行坂。","素冠集流尘，客子中夜饭。","驱车当周行，相顾各缱绻。"]},{"t":"赠别安鸿渐给舍四首 其二","f":"五言古诗","c":["缱绻夫如何，欲语不出口。","冥冥云中禽，菀菀道傍柳。","炎暑方载途，客行日弥久。","山川气候更，风雨昏旦有。","毋为人所先，宁为人所后。"]},{"t":"赠别安鸿渐给舍四首 其三","f":"五言古诗","c":["青城多异境，蛾眉隐新月。","巴江从中来，纡曲如一发。","秋气劲楩楠，春阳长薇蕨。","地高鱼鸟閒，天近星斗没。","行归及桑梓，山川共辉发。"]},{"t":"赠别安鸿渐给舍四首 其四","f":"五言古诗","c":["君还江水源，我去江水委。","江中多鲤鱼，尺素来万里。","遥涉岷汉流，复泳沅湘沚。","海门何浩荡，但恐风波起。","江干候鲤鱼，秋高水瀰瀰。"]},{"t":"俨山堂迟友","f":"五言古诗","c":["淡烟酿朝冥，细雨含秋姿。","独立更延伫，怅望迟所思。","丽容本绝代，被服何陆离。","一为经时别，悲喜极感持。","徽音寄篇翰，往往追四诗。","知己自旷遇，佳会贵及时。","大业日云远，非子谁与期。"]},{"t":"移居寄子容","f":"五言古诗","c":["予本四方人，慷慨赴天路。","幸托金兰交，再蒙盐车顾。","端怀素居忧，岂乏同袍赋。","侧身向长安，凝望几朝暮。","浮阴结苑墙，年华落宫树。","是非金玉姿，安能磐石固。","时欲往从之，驽马不能步。","相思在相知，因风寄情愫。"]},{"t":"送徐进士昌谷湖南纂修","f":"五言古诗","c":["丈夫及壮辰，足迹遍川谷。","送子湖南去，佳胜付遐瞩。","渺渺洞庭波，盘盘衡阳麓。","朝鲙武昌鱼，暮听潇湘竹。","嗟此赤壁灰，悲彼长沙鵩。","双旌动秋色，俯仰如新沐。","境内三千里，候吏丰馆谷。","山水富奇闻，归借南游录。"]},{"t":"发西店驿","f":"五言古诗","c":["海峤不可即，林峦互盘萦。","依依度阡陌，靡靡事前征。","仆夫秖趋骛，昏晓各有程。","岂不爱岁月，娱此山水清。","少小四海志，老大竟何成。","伏辕伤局促，履境戒高盈。","南中气候早，三月竞深耕。","林烟起菑畬，园风动茅衡。","物华遂敷畅，旅怀倦将迎。","喧寂会所适，感叹重含情。"]},{"t":"赠别徐昌谷二首 其一","f":"五言古诗","c":["北风吹我衣，送子山之隅。","一瞻再三顾，别离在斯须。","知遇良独难，工瑟徒好竽。","感念管鲍私，安得不区区。","昔为比翼鸟，今如失水鱼。","一日为三秋，怅望增欷歔。"]},{"t":"赠别徐昌谷二首 其二","f":"五言古诗","c":["北风被原野，送子古郭下。","仆夫远前途，执辔柔如组。","屏营复踌躇，气结不得语。","许身忌太炫，荣名毋多取。","珠明蜃人心，玉缜良工苦。","寄言同心人，蜂虿多风雨。"]},{"t":"夜宿烂柯山农家","f":"五言古诗","c":["夜扣田家门，空庭列松炬。","导之上小楼，一室有雅趣。","木榻久已尘，颇胜栖草露。","鸡豚栖下方，警戒烦再顾。","虽无穷途哭，必有神物护。","老农拙言辞，起拜具礼度。","感此深山深，土风俨淳素。"]},{"t":"武卿山中晚行","f":"五言律诗","c":["水流青山中，人行白云处。","落日下西崦，馀光拂高树。","此行何所有，一眺空海宇。","惭乏山林姿，来此成宾主。"]},{"t":"閒居拟陶","f":"五言古诗","c":["林居罕人事，渐与农圃亲。","时还读我书，梦寐见古人。","桃源亦何有，传说失其真。","蔼蔼风日妍，郁郁草树春。","傥免病为累，吾亦爱江滨。"]},{"t":"寓彰德仓司小憩颇有花竹之观","f":"五言古诗","c":["愧乏潇洒趣，享此山林居。","时花当春发，乔木向日舒。","好风汎崇光，有鸟鸣前除。","坐久起顾影，悠然思遂初。","去住各有适，得丧两无馀。"]},{"t":"雨后分种秋葵","f":"五言古诗","c":["早葵花已繁，晚葵始萌滋。","迎阳与应肃，物性各有宜。","吾欲备四气，代谢任所之。","往者固已尔，来者当自知。","人生会有适，迟速何足疑。","但愿风日妍，临秋挹高姿。","眷此尺寸间，寻丈以为期。","殷勤付畦叟，爱养贵及时。"]},{"t":"登翠华岩上洞","f":"五言古诗","c":["穷高畅远瞩，跻胜酬良缘。","京尘动千尺，往来成岁年。","偶上翠华洞，閒寻旧镵镌。","无烦辨人代，惟知出风烟。","长安近捧日，韦曲低去天。","惟皇朝万国，声教被八埏。","振策一以眺，高云下渊泉。","德辉九苞凤，形势百足蚿。"]},{"t":"新晴病起独登台观耕","f":"五言古诗","c":["东曦散早凉，沃土依水曲。","宿雨一以霁，微风满畴绿。","农人欣及时，物情遂所欲。","稼穑良独难，勤惰各有属。","夙疴幸暂舒，登台恣遐瞩。","馌饷偕尔邻，指挥顾我仆。","新苗含露滋，把爱等苍玉。","稍稍已成行，累累尚盈束。","苟遂丰稔期，宁知泥涂辱。","倦游拙理生，藉此一廛足。"]},{"t":"斋居","f":"五言古诗","c":["园林变夏木，弱躯犹春衣。","岂乏四方志，瘏马不能车。","偃息沧江涘，水竹既清虚。","悟悦有夙契，冥诠资简书。","翔禽怀佳音，时雨鸣前除。","境适谢力遣，迢遥遂忘予。"]},{"t":"风琴","f":"五言古诗","c":["陶令无弦趣，未忘矫俗心。","退之听颖师，哀怨一何深。","伊余两瑶琴，因风调至音。","乍如落松涛，复同骊龙吟。","掩抑竟何有，断续难自禁。","悦耳贵一适，传指劳千金。","乃知宇宙间，喧寂寄所任。","火化本无迹，至理不可寻。","以余疏慵姿，置之风水林。"]},{"t":"碧云寺观泉","f":"五言古诗","c":["堂辞白玉前，寺到碧峰下。","石幢插渚波，贝叶翻般若。","循除决清泉，此境极潇洒。","琤琮金佩传，宛转玉绳泻。","缅怀川上心，临流叹不舍。","曾闻貂珰雄，挥金事游冶。","高台相掩映，松篁杂梧槚。","似识舟壑安，宁知蕉鹿假。","止观等殷鉴，洗酌泛周斝。"]},{"t":"临清车行","f":"五言古诗","c":["南人不识车，北人不识舟。","二者更相苦，役役不能休。","吾生本丈夫，安能绝行游。","生长东吴郡，偕计来皇州。","岁暮风日烈，行行阻且修。","黄尘翳白日，四牡騑梁辀。","未明候晨鸡，残更进薄羞。","坚冰交狐豕，寒畴下羊牛。","疏林希突烟，迥野多荒丘。","触目集野意，抚时萦羁愁。","岂不爱遗体，高居讵良谋。","遑遑念饥溺，遐思禹稷俦。"]},{"t":"秋怀","f":"五言古诗","c":["斗杓西指申，兴言怀幽诗。","玄蝉泣高柳，玉露零泥泥。","急景如受驱，少壮诚几时。","丈夫怀苦心，飘泊将奚为。","悦彼庭前树，芳花缀繁枝。","莫俟凉风欺，果实独后期。"]},{"t":"题画","f":"五言古诗","c":["关河冻初合，云物岁已晚。","纡辔鸡鸣树，怅望羊肠阪。","徘徊不能度，风高马毛短。"]},{"t":"陈光禄惟顺迎暾书舍四首 其一 龙泉","f":"五言古诗","c":["瀑布下匡庐，倚天垂玉柱。","潇潇六月寒，坐对白龙舞。","幽人送目馀，新添夜来雨。"]},{"t":"陈光禄惟顺迎暾书舍四首 其二 寺钟","f":"五言古诗","c":["蒲牢吼萧寺，明星出东方。","动息各有会，随风远飘飏。","唤起巫山梦，缥缈赋高堂。"]},{"t":"陈光禄惟顺迎暾书舍四首 其三 渔歌","f":"五言古诗","c":["爱听江湖调，沧浪第一声。","桃花新水浪，摇动楚王城。","得鱼沽酒处，风雨更多情。"]},{"t":"陈光禄惟顺迎暾书舍四首 其四 樵语","f":"五言古诗","c":["风暖鸟声喧，隔坞闻人语。","盘云拾堕樵，晨昏自来去。","深山多虎狼，同心邀伴侣。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其一 山市晴岚","f":"五言古诗","c":["山以远市珍，山中复成市。","轻云结浮岚，东风泻清泚。","不辨往来人，微喧隔林起。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其二 渔村落照","f":"五言古诗","c":["风波本无定，渔家爱夕阳。","丝纶摇飏处，多在瀼西傍。","清歌一曲竟，天水共微茫。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其三 烟寺晓钟","f":"五言古诗","c":["清晓坐闻钟，知是何朝寺。","微霜动商飙，秋随雁行至。","联翩去乡人，岂无怀乡意。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其四 江天暮雪","f":"五言古诗","c":["雪片大于手，江空岁复寒。","幽人高卧处，偏得画图看。","为问梁王简，何如楚客冠。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其五 潇湘夜雨","f":"五言古诗","c":["扁舟潇湘上，夜听潇湘雨。","回风度明珰，丛篁各成坞。","欲起寄相思，美人隔南浦。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其六 洞庭秋月","f":"五言古诗","c":["月光随处好，何况洞庭秋。","风露三千里，金波上下流。","此时闻铁笛，天际一登楼。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其七 远浦归帆","f":"五言古诗","c":["孤帆自天际，出没见秋毫。","归心同逝水，飞度挟风涛。","临流一怅望，空觉此生劳。"]},{"t":"予家旧藏潇湘图聊因旧题各成短咏八首 其八 平沙落雁","f":"五言古诗","c":["雁阵惊寒早，平沙衬水圆。","同怀稻粱意，南下尽翩翩。","谁念关山远，犹有尺书传。"]},{"t":"玉华杂咏七首 其一 玉华山","f":"五言古诗","c":["海风吹海雨，飞过玉华山。","山中人不见，窈窕翠微间。","得月乘鸾度，开云放鹤还。"]},{"t":"玉华杂咏七首 其二 白云窝","f":"五言古诗","c":["云来如有情，云归本无迹。","归去群山青，来时林树白。","窝中卧云人，偶值爱云客。"]},{"t":"玉华杂咏七首 其三 万柳塘","f":"五言古诗","c":["千条万条黄，垂柳复垂杨。","连云难辨色，荫月不留光。","幸不当岐路，别离那复伤。"]},{"t":"玉华杂咏七首 其四 望湖楼","f":"五言古诗","c":["登楼望澄湖，楼高湖面小。","金波月里秋，青草雨中晓。","心閒境逾静，悠然见鱼鸟。"]},{"t":"玉华杂咏七首 其五 韩山","f":"五言古诗","c":["一发韩江水，韩山相对起。","扁舟乘海潮，回首渺千里。","上流春雨多，夷犹弄清泚。"]},{"t":"玉华杂咏七首 其六 越王走马埒","f":"五言古诗","c":["燕台骨已朽，渥洼种未生。","何年走马埒，尚带越王名。","榕叶斜阳外，坐看海云轻。"]},{"t":"玉华杂咏七首 其七 鹤舟","f":"五言古诗","c":["买得青田种，相携共一舟。","碧箫吹夜月，飞度百花洲。","借问华亭唳，何如赤壁游。"]},{"t":"过安山几间有高达夫集偶拈东平路作一首戏效其体","f":"五言古诗","c":["飞鹢指金台，扬帆出钜野。","细柳萦长堤，新蒲弱堪把。","烦襟散遥岑，好风送朱夏。"]},{"t":"云山图赠严介溪西还","f":"七言古诗","c":["美人别我还楚封，遥望云山如画中。","忆昔燕市初相逢，年少意气双飞鸿。","朅来射策披心胸，五云旭日蓬莱宫。","玉堂对榻闻晓钟，南郊献赋追扬雄。","旁人忽忽称儒宗，文彩往往惊相公。","过从莫限风雪冲，卜居长安家屡通。","眼见天日升潜龙，石渠夜照藜火红。","退食联步时从容，移书论道相磨砻。","岂徒握手期协恭，自信肝胆摩苍穹。","今我日月催衰慵，近有白发临青铜。","世事浮云无定踪，况子缞绖俨在躬。","十年契谊萝施松，一旦掺袂成西东。","人言此图千万重，我意试比应难穷。"]},{"t":"中山图次韵俞国昌都谏送许补之侍御谪定州","f":"七言古诗","c":["中山风物美且都，无乃贤达避世区。","芝山许子今钜儒，虬髯逸论如大苏。","只手欲作回天图，七月诏狱朱颜敷。","我生有癖惰且迂，辱子契谊时与俱。","两都三试要不殊，空怜警夜雁有奴。","寂寞府中栖树乌，剸割修复见昆吾。","聊试儿童夹道呼，中山山中劝种榆。"]},{"t":"月夜与高进之沈德桢诸友过簳山次壁间韵","f":"七言古诗","c":["棹歌欲停山月吐，月影照人清可数。","疑心已断壁间蛇，壮气犹惊草中虎。","清溪曲曲淡不流，此月重来犹故我。"]},{"t":"秋思","f":"七言律诗","c":["空庭萧索帘栊雨，秋色漫漫四山里。","閒花不语伤朱颜，落叶无声风未起。","依稀三五少年游，凤凰台畔临吴楚。","家书自怪满纸题，犹剩胸中数行语。"]},{"t":"何舍人馆中对雪","f":"五言律诗","c":["燕地春犹浅，高城雪更明。","相逢为客处，同有望乡情。","栈阁因风积，楼台入夜清。","不知梁苑赋，何似蔡州城。"]},{"t":"过卢沟桥","f":"五言律诗","c":["野适意自惬，逢春更可怜。","弄黄初试柳，破碧已分泉。","马足腾晴雾，鸡声隔午烟。","翠华巡幸日，驰道直如弦。"]},{"t":"孝庙挽词","f":"五言律诗","c":["帝座宵沈彩，皇祇昼啸风。","人怀三代治，天忌万年功。","衮冕丹青里，山河涕泗中。","圣恩如可报，精卫海涛东。"]},{"t":"下陵","f":"五言律诗","c":["片月青山外，遥灯绿树中。","马蹄知熟路，人语杂回风。","台殿参差出，冠裳彷佛同。","穹碑犹入望，挥涕忆神功。"]},{"t":"对月","f":"五言律诗","c":["连夜月色好，此宵看满轮。","金波惆怅里，碧海别离新。","冰雪南征雁，关山北望人。","琴书照清影，舟楫对通津。"]},{"t":"假寐","f":"五言律诗","c":["假寐依洄洑，篝灯伴水云。","晚潮随月上，归雁带霜闻。","地古三江合，星移五夜分。","冥行吾岂敢，露宿畏离群。"]},{"t":"三日出大明门","f":"五言律诗","c":["日华丽高阁，风光媚轻尘。","喧喧车马动，蔼蔼岁年新。","花柳回芳甸，关山念远人。","履端逢泰运，大飨卜明禋。"]},{"t":"赋得玉河烟柳","f":"五言律诗","c":["御堤新水上，细柳织轻烟。","隐映金銮外，低回玉甃前。","晓容横一抹，春色试三眠。","地接天门近，常沾雨露偏。"]},{"t":"得刘子书","f":"五言律诗","c":["念子不能寐，中宵鸣素琴。","近闻衡岳去，遥望楚江深。","入梦多岐路，缄书有好音。","隔窗风雨横，愁绝故人心。"]},{"t":"寄李献吉","f":"五言律诗","c":["客到梁园者，仍烦致起居。","夜来新有梦，春去久无书。","绿野深花径，黄河抱草庐。","迢迢千里道，目短鬓萧疏。"]},{"t":"和张玉溪山行","f":"五言律诗","c":["一径出林坰，四山开画屏。","霜钟度远寺，雪柳带长汀。","路转城闉出，云深石洞冥。","千年埋玉处，龙气昼常扃。"]},{"t":"华盖殿外候驾雪中有怀崔后渠严介溪上陵","f":"五言律诗","c":["此去西陵好，花骢并辔行。","桥山瞻王气，礼殿肃精诚。","吏供宵饭，归鞭促晓程。","立残金殿雪，忆尔到昌平。"]},{"t":"分水祠漫成","f":"五言律诗","c":["江头十日坐，无日不吁嗟。","绿暗连天柳，红明委地花。","衔泥新燕子，傍水旧人家。","南望无终极，青天又一涯。"]},{"t":"谷亭经旧寓","f":"五言律诗","c":["土屋曾为客，朱炎夜见星。","枣林连驿路，麦饭趁鱼腥。","万里看双鬓，三年抱一经。","经行重俯仰，枫树晚冥冥。"]},{"t":"过清河烟雾不见山","f":"五言律诗","c":["春气浓如酒，沈沈醉远山。","爱飞孤鸟没，随意片云閒。","兴为寻芳发，尘怜扑面还。","石桥流水漫，立马听潺湲。"]},{"t":"徐州洪次韵","f":"五言律诗","c":["表里山河胜，东泉复上流。","斜阳明石佛，古堞绕徐州。","溪影尤宜月，潮声不待秋。","去来风雨横，奇绝冠兹游。"]},{"t":"月下抵彭城","f":"五言律诗","c":["险中不觉险，家近转思家。","世路元无尽，人生故有涯。","乡音传白苧，秋事付黄花。","今夜彭城驿，清尊对月华。"]},{"t":"宝应晚泊","f":"五言律诗","c":["天接湖光迥，云开塔影圆。","老渔明宿火，客子傍归船。","晚市风声静，秋沙月色偏。","绝怜净如练，閒拟谢公篇。"]},{"t":"渡江","f":"五言律诗","c":["几日江南路，灵旗发画船。","江流馀旧日，山色入新年。","风细蛟龙卧，云开虎豹眠。","夕阳京口闸，吟兴酒尊前。"]},{"t":"过丹阳","f":"五言律诗","c":["平明辞铁瓮，日暮过丹阳。","远道初知客，方言忽近乡。","苔封联艇绿，泥涴小车黄。","柳暗河桥下，平分麦秀凉。"]},{"t":"游金山次唐韵","f":"五言律诗","c":["过水金山寺，真怜地脉分。","潮声生绝壁，江影堕孤云。","凉吹先秋到，长歌入夜闻。","登临殊不极，斜日伴微醺。"]},{"t":"嘉定登圆通寺佛阁次王节推韵","f":"五言律诗","c":["酷暑宜高阁，时花上槛红。","水沈销活火，冰簟受南风。","鸟背层霄外，龙腥古钵中。","晚凉频徙倚，村郭失西东。"]},{"t":"黄纯玉之再游龙华也予不及再陪怅然次韵","f":"五言律诗","c":["浦口桥西寺，水深尘事稀。","重来黄叔度，尚忆陆探微。","霜后惊红树，天南望紫微。","还将五色手，归补衮龙衣。"]},{"t":"游昭庆寺","f":"五言律诗","c":["秋风昭庆寺，初日满回廊。","地古松能偃，山深橘未霜。","移舟还傍麓，著屐试登堂。","高阁凌云表，凭阑意自长。"]},{"t":"坐月喜易钦之见过","f":"五言律诗","c":["方庭兀坐久，漏水静来闻。","雉堞孤云补，旗竿片月分。","乡心基远梦，凉意感微醺。","赖有同心者，敲门慰藉勤。"]},{"t":"题竹送张钟美待御按云南","f":"五言律诗","c":["临岐欲有赠，赠此比琅玕。","南国多炎暑，因君见岁寒。","风雷山岳动，潇洒画图看。","白雪真难压，青云亦可干。"]},{"t":"晚过元明新居","f":"五言律诗","c":["岁暮天涯客，相依愿好邻。","楼台残夜月，梅柳隔年春。","契谊怜知己，驰驱愧此身。","浮云终日事，偏感异乡人。"]},{"t":"苦雨","f":"五言律诗","c":["长安十日雨，雨中孤客愁。","泥深妨著屐，乡远怕登楼。","水气偏欺日，云阴每妒秋。","不知畿甸里，禾黍尚堪收。"]},{"t":"月下与张碧溪汎舟","f":"五言律诗","c":["微月堕止水，空明漾浅沙。","放舟沿柳岸，看竹过邻家。","林静一枝鸟，溪喧两部蛙。","不应张博望，别自有仙槎。"]},{"t":"赠沈举人铨","f":"五言律诗","c":["岁晚风江阔，天空朔雁孤。","君行自冰雪，吾意且江湖。","骥北千金价，鹏南万里图。","文章关国运，把酒对青蒲。"]},{"t":"俨山春晓二首 其一","f":"五言律诗","c":["濛濛连夜雨，曲曲带溪山。","隔水分喧寂，经旬断往还。","天连沧海近，人比白鸥閒。","多藉东风力，吹春到闭关。"]},{"t":"俨山春晓二首 其二","f":"五言律诗","c":["初有江山胜，况逢花柳春。","晓云含宿雨，暖吹约轻尘。","树里看孤棹，烟中辨四邻。","几年京国梦，唤醒爱閒身。"]},{"t":"寄孙思和","f":"五言律诗","c":["竟负回舟约，虚烦下榻留。","惟馀三亩宅，遥望七峰楼。","天接星文动，江涵雁影流。","烟花正无数，老眼几时休。"]},{"t":"雨中行史泾","f":"五言律诗","c":["江路西南永，端阳亦不晴。","草堂松粉润，花坞藓痕平。","桥古行人迹，田低过水声。","兹游自奇绝，云树望中生。"]},{"t":"六日雨二首 其一","f":"五言律诗","c":["郊居世尘少，农月雨声多。","暝色连葭菼，繁阴动薜萝。","歌谣终帝力，沾润即恩波。","漠漠江天外，时时白鸟过。"]},{"t":"六日雨二首 其二","f":"五言律诗","c":["长閒缘性懒，爱雨为年丰。","入夜声逾急，因风势转雄。","灯前欹病枕，江上忆渔翁。","亦有沧洲兴，相期泛水东。"]},{"t":"南浦阻风","f":"五言律诗","c":["西风催逝水，一片布帆轻。","渺渺江鸥去，离离锦树明。","兴高偏有恨，秋老最关情。","咫尺溪南路，天留访戴行。"]},{"t":"留布金寺","f":"五言律诗","c":["宿宿俱投寺，行行莫问津。","麦波摇落日，花雨恋残春。","水国攻农事，禅房清世尘。","乡心与野意，从此往来频。"]},{"t":"秋斋夜听雨二首 其一","f":"五言律诗","c":["鹳鹊林栖尽，秋窗细雨来。","野云天共远，凉气夜交催。","檐溜断仍滴，灯花落更开。","幽人心赏足，孤咏寄高怀。"]},{"t":"秋斋夜听雨二首 其二","f":"五言律诗","c":["南亩苦刈稻，秋风兼送寒。","老农舂旧谷，红女捣残纨。","暗响随黄叶，疏香消紫兰。","物华知节改，加意几回看。"]},{"t":"宿碧云寺","f":"五言律诗","c":["西崦碧云寺，天空近太微。","堂虚寒吹入，檐宿暮云归。","听履仙卿集，留僧锡杖飞。","偶因方外胜，殊觉世情非。"]},{"t":"次韵严介溪上陵","f":"五言律诗","c":["帝遣修陵祀，秋来得并行。","雨声连日夜，山色洗幽并。","远道防残暑，斋心冀晚晴。","敬皇弓剑地，挥泪想西征。"]},{"t":"酌别何舍人兼问讯空同子","f":"五言律诗","c":["年少谁如子，他乡怯病身。","春风满归路，几日罢征轮。","尘合青山远，河开碧树新。","故园如见月，应念未归人。"]},{"t":"赠别王瑩中二首 其一","f":"五言律诗","c":["孤舟连夜发，客子念还家。","远道多秋卷，高城急暮笳。","一身笼外鸟，万虑壁间蛇。","春色淮南路，江蓠绕白沙。"]},{"t":"赠别王瑩中二首 其二","f":"五言律诗","c":["爱尔不能住，高楼空暮思。","浮云连日脚，流水绕天涯。","未有孙阳遇，虚烦楚客辞。","故园江上好，风咏况相宜。"]},{"t":"五坞山房为卢师陈赋","f":"五言律诗","c":["不是黄金地，毋烦白石歌。","春风湖上路，夜月镜中波。","插案图书在，缘阶兰桂多。","遥知梅雪后，杖屦待经过。"]},{"t":"晚自西堤携楫儿散步","f":"五言律诗","c":["夕阳江水外，曲曲带沙堤。","生意随汀草，閒心付杖藜。","渔舟天上下，人语瀼东西。","稚子偏怜我，相携过竹溪。"]},{"t":"赴储芋西少参中途过陈氏庄避雨","f":"五言律诗","c":["合下陈蕃榻，真成访戴行。","燕泥妨马力，花雨弄春晴。","十里缘江路，中年故国情。","不须团盖拥，风澹正云轻。"]},{"t":"人日雪二首 其一","f":"五言律诗","c":["院深勤扫地，帘静爱闻香。","堕壑随风力，穿云逗日光。","山城阁道迥，松径石衣长。","欲试煎茶水，丁宁近竹房。"]},{"t":"人日雪二首 其二","f":"五言律诗","c":["人日岁常阴，今年雪更深。","天空山竞出，春早柳难禁。","四海三农望，孤城独客心。","故园江上路，梅坞有谁寻。"]},{"t":"看云","f":"五言律诗","c":["筠簟瑩冰纹，开帘卧看云。","随风还作阵，映水复成文。","出岫连绵起，奇峰次第分。","更能呈五色，持此献明君。"]},{"t":"人日","f":"五言律诗","c":["春日复人日，乡心乱客心。","东山游不到，西岭雪常阴。","城郭林泉绕，风云殿阁深。","梅花临水发，抛事且须寻。"]},{"t":"月下行舟","f":"五言律诗","c":["水曲风帆渺，云开月殿圆。","金波千片动，珠斗半空悬。","树影连山合，歌声入夜妍。","舵楼高似屋，归兴坐来偏。"]},{"t":"兰溪道中","f":"五言律诗","c":["朝日晖江路，平林映远山。","宿云收不尽，高鸟与俱还。","秋草弄幽色，寒松有好颜。","时时上高濑，隐几听潺湲。"]},{"t":"教岩暮发","f":"五言律诗","c":["向夕秋山紫，西风吹白云。","纳凉移榻屡，待月引杯勤。","岭树参差出，渔歌次第闻。","去留俱有适，吏隐欲中分。"]},{"t":"宿建昌县公馆听雨和周玉岩都宪","f":"五言律诗","c":["五月溪山路，水深云更深。","溪梁连近麓，帆影掠长林。","巨浸愁农事，重阴伤客心。","翻将经济意，时向簿书寻。"]},{"t":"鄱阳湖","f":"五言律诗","c":["家居沧海曲，观水入云天。","斜日番君庙，西风邬子船。","草封高岸没，波合断山连。","起击中流楫，秋光满大川。"]},{"t":"望云居","f":"五言律诗","c":["道远山初近，天长晚更晴。","水从星汉落，舟在画图行。","击楫吴郎计，乘槎汉使情。","难将物外意，空博世间名。"]},{"t":"万载冒雨晓发途中次韵 其一","f":"五言律诗","c":["逢迎南至日，上尽雨中山。","人过龙行处，云生马度间。","征旗残画捲，弛担隋樵还。","阮籍何心者，予方索笑颜。"]},{"t":"万载冒雨晓发途中次韵 其二","f":"五言律诗","c":["晓行随落月，细雨暗前山。","天地阴晴里，风云变态间。","远装初觉重，湿鸟并知还。","捲幔峰峦接，丹青有好颜。"]},{"t":"龙窝驿","f":"五言律诗","c":["远道悲游子，春光满驿亭。","幽花背岩发，芳草上洲青。","帆影连银海，山形列翠屏。","何如张博望，光动女牛星。"]},{"t":"自荥泽渡河","f":"五言律诗","c":["清晓轻尘湿，长河新水通。","一宵花信雨，两岸麦秋风。","禹迹微茫外，鸿沟指顾中。","七年三问渡，南北更西东。"]},{"t":"初从木罂渡水欣然忘危步入山庵小憩","f":"五言律诗","c":["病骨难为路，春容半带阴。","木罂初渡水，山寺不藏林。","脱险初经险，违心却负心。","楚云天共远，聊复一登临。"]},{"t":"过赵州","f":"五言律诗","c":["当代朝天路，犹馀望汉台。","地分三晋古，客过万山来。","霁雪留残照，轻车动早雷。","望穷天北极，紫气绕蓬莱。"]},{"t":"自下邳晨渡","f":"五言律诗","c":["残月曙犹上，断冰寒更流。","风回青雀舫，尘满皂貂裘。","勋业奁中镜，英雄水上楼。","行人连日夜，陌上重回头。"]},{"t":"汶上","f":"五言律诗","c":["汶上栖贤地，风尘愧此行。","天寒日力短，道远旅魂惊。","不醉任城酒，空怀贺监情。","浮云亦何意，常为碧山横。"]},{"t":"西望太行诸山","f":"五言律诗","c":["白日如送客，青山解迎人。","半空横叠嶂，万里一孤臣。","涧积过年雪，风回隔岁春。","并州虽暂住，难比故乡亲。"]},{"t":"石铁村乘月行","f":"五言律诗","c":["片月新秋里，行人山路中。","晚凉微带露，宿雨尚含风。","星炬参差列，肩舆窅窱通。","去程迷远近，时复问西东。"]},{"t":"阳武道中","f":"五言律诗","c":["冬日如春暖，河冰断复流。","尘中藏去马，天际出危楼。","周道真如砥，行人那可留。","风霜双短鬓，失计为身谋。"]},{"t":"井陉道中雪甚","f":"五言律诗","c":["井陉天下险，何况雪中过。","绝壁看云嶂，危桥下玉坡。","奔腾千驷马，森矗万人戈。","信有淮阴令，衔枚夜渡河。"]},{"t":"井陉西上故关","f":"五言律诗","c":["雪艳腾腾长，天容黯黯低。","千重无路入，一望使人迷。","日午凭鸡唱，云生傍马蹄。","山川分赵魏，关路隔东西。"]},{"t":"过北关","f":"五言律诗","c":["旧雨侵泥滑，连朝得晓晴。","土窑留树荫，山路逐泉声。","近塞风先劲，中秋月乍生。","几家田石坂，辛苦望收成。"]},{"t":"定襄雨中","f":"五言律诗","c":["细雨重门寂，新凉病骨清。","河山襄子国，关塞代王城。","独夜闻鸡早，高云过鸟轻。","断桥题豫让，身后尚留名。"]},{"t":"泾阳道中晓行","f":"五言律诗","c":["古树捎残月，孤灯映远村。","闻鸡怜旷野，驱马上高原。","恋主心逾切，安身事不烦。","东风吹晓梦，只许绕柴门。"]},{"t":"寄题郭复斋太守别署二首 其一","f":"五言律诗","c":["城上楼台迥，山中日月开。","眼空人独坐，吏散客频来。","泉石秋先到，诗篇手自裁。","隔溪花发处，时有鹤飞回。"]},{"t":"寄题郭复斋太守别署二首 其二","f":"五言律诗","c":["山水东南郡，经营复此中。","渚花娇欲语，海鹤舞成童。","曲径重重月，回阑面面风。","蓬莱元不远，城外弱流东。"]},{"t":"送朱守忠兼怀山阴旧游","f":"五言律诗","c":["我昔登南镇，山阴一水东。","禹功思玉帛，秦刻卧鱼虫。","古有神仙宅，今传王谢风。","独怀词赋悔，白发老杨雄。"]},{"t":"大浪滩","f":"五言律诗","c":["江水清不澈，秋容雨复晴。","捲帘闻瀑坐，欹枕看山行。","密筱缘溪转，长松径壑平。","人家翠微里，时有白云生。"]},{"t":"玉山西下换小舟乘月","f":"五言律诗","c":["怀玉溪山路，依稀记昔年。","秋风南国客，明月下泷船。","苦爱沧浪曲，谁歌白石篇。","甘棠是何物，千古使人怜。"]},{"t":"书龟峰石壁上","f":"五言律诗","c":["四眺山俱好，入山游兴长。","群峰更卧起，万木半青黄。","轻鸟巢孤壁，流泉过叠廊。","幽期探未极，翻忆巨灵藏。"]},{"t":"宿龟峰","f":"五言律诗","c":["一宿龟峰寺，登临愿不虚。","岩花僧定后，山果客来初。","峭壁时亏蔽，孤云递卷舒。","愧无康乐手，疑有子长书。"]},{"t":"中秋对月二首 其一","f":"五言律诗","c":["今夜中秋月，长安向北城。","高梧云意薄，小草露华清。","气候关寒暑，天心忌满盈。","孤亭虚四壁，着意傍人明。"]},{"t":"中秋对月二首 其二","f":"五言律诗","c":["对酒不成醉，秋光倍可怜。","照人偏白发，为客况青毡。","几处关山里，终宵鼓角边。","未知尘世上，能看几回圆。"]},{"t":"至潼关","f":"五言律诗","c":["潼关天作险，此地复楼台。","一径云中度，三川日下来。","东迁周左计，先入汉雄材。","自有蓬桑志，西南万里开。"]},{"t":"峡江道中暮色","f":"五言律诗","c":["晓山南国丽，中月复冬深。","轻露还蒸麓，幽花尚满林。","北风千叠浪，西崦半帆阴。","何似湘江路，常悬魏阙心。"]},{"t":"雪中王嵩野过公馆小酌次韵","f":"五言律诗","c":["西台梁苑客，南国楚郊山。","共爱六花舞，如登万玉间。","平原千骑出，远浦一蓑还。","萍水萍乡路，相看得破颜。"]},{"t":"宿邯郸","f":"五言律诗","c":["兼程趋百里，虚馆宿邯郸。","世事浑如梦，春宵尚带寒。","古台平雉堞，残月隔雕阑。","无端是兴废，人共璧俱完。"]},{"t":"十日早朝寒甚","f":"五言律诗","c":["寒重春犹勒，风回雪未消。","旂常悬日月，殿阁迥云霄。","卿相恭寅协，君王视早朝。","天颜殊有喜，胪唱飏箫韶。"]},{"t":"应制撰颖殇王挽歌四首 其一","f":"五言律诗","c":["潜德悲天整，馀哀眷帝衷。","素车明落日，丹旐飏凄风。","聚散云无迹，彭殇数偶同。","人间留不得，龙种自龙宫。"]},{"t":"应制撰颖殇王挽歌四首 其二","f":"五言律诗","c":["玉树难为实，璇源本自清。","未胜桐叶剪，先助薤歌声。","祖祭公卿集，皇恩父子情。","堂封千古地，佳气五云平。"]},{"t":"应制撰颖殇王挽歌四首 其三","f":"五言律诗","c":["瑶圃秋先到，珠林露易晞。","千官歌执绋，万乘泪沾衣。","正气苍冥阔，佳城紫翠围。","多应是神物，华表鹤重归。"]},{"t":"应制撰颖殇王挽歌四首 其四","f":"五言律诗","c":["皇胤分天派，仙才降帝居。","如何埋玉日，方及晬盘馀。","不见东平礼，空传北海书。","英灵同大造，消息任盈虚。"]},{"t":"新乡道中","f":"五言律诗","c":["望国还乡路，南人北客心。","鬓毛霜欲满，时序夏初临。","宿雨风尘净，遥山紫翠深。","苏门精舍近，怅望负幽寻。"]},{"t":"晓发新乡","f":"五言律诗","c":["落月犹在屋，大星欲浮空。","旅门人戒晓，官道树含风。","隐隐共山湿，迢迢卫水东。","黄河旧行处，指点为谁穷。"]},{"t":"淇县道中雨泞","f":"五言律诗","c":["雨深泥滑滑，一步九跻攀。","世路分南北，人情念往还。","湿云萦细柳，龙气隐高山。","想像歌淇澳，何如蜀道间。"]},{"t":"泛黄河","f":"五言律诗","c":["淼淼望不极，连天送浊流。","浮沈经塞外，淘洗向中州。","鸥弄千帆雨，沙明两岸秋。","灵槎频讯问，乘兴欲遨游。"]},{"t":"赴介溪赏雪","f":"五言律诗","c":["怀乡仍岁杪，喜雪况登楼。","天地俱生色，江湖足胜游。","十年依凤阙，此日更狐裘。","未有阳春调，能为郢客酬。"]},{"t":"次介溪看牲韵","f":"五言律诗","c":["辇路金沙涌，郊坛翠甓开。","定须骑鹤到，唯许视牲来。","列炬银花发，严更玉漏催。","上卿仙骨胜，侵晓入蓬莱。"]},{"t":"送杨子浚大理得告归岭南","f":"五言律诗","c":["爱尔不可别，欲留其奈何。","池塘春草变，山鸟杜鹃多。","采药仙人侣，缄梅驿使过。","于公好门第，四海望阳和。"]},{"t":"次韵曹承之留别二首 其一","f":"五言律诗","c":["旧京千古重，许国一身轻。","驿路梅初发，都门雪正晴。","新除分画省，惜别赋春明。","多少临岐客，于君独有情。"]},{"t":"次韵曹承之留别二首 其二","f":"五言律诗","c":["南至三千里，东风一棹轻。","石头城外晓，桃叶渡傍晴。","客思奚囊重，乡心昼绣明。","六朝佳丽地，登眺若为情。"]},{"t":"送张希贤令泗会","f":"五言律诗","c":["万里古端州，分符作胜游。","云山通庾岭，风土接罗浮。","县静仙凫远，楼高瘴雨收。","未能逢故旧，回雁有高秋。"]},{"t":"次韵送李都阃","f":"五言律诗","c":["山颠与水涯，时见野人家。","远湖拖白练，新竹长青蛇。","涧露浮云石，林藏著雨花。","神仙无别径，此地有烟霞。"]},{"t":"邀甬川少宰过报国寺送吕泾野致仕","f":"五言律诗","c":["赤日都门道，青山故国情。","风前邀客过，寺里送君行。","有梦凭清晓，何心计去程。","秦川一水隔，天远九重城。"]},{"t":"舟发","f":"五言律诗","c":["风水本无定，有时能送行。","西郊不作雨，北望独含情。","习静怜穿榻，闻歌爱濯缨。","十年怀旧业，六月遂南征。"]},{"t":"潞河发舟两日夜始抵和合驿","f":"五言律诗","c":["快路日千里，畏途肠九回。","古难当蜀道，今日下燕台。","柳色连村暗，波光映日开。","北山如有待，猿鹤未应猜。"]},{"t":"放任城南闸","f":"五言律诗","c":["风水自顺逆，物情生爱憎。","任城天设险，湖泊气多蒸。","相业商岩雨，君恩玉井冰。","阮途多少意，长啸愧孙登。"]},{"t":"十四日放徐州洪逢周一之","f":"五言律诗","c":["脱险方惊险，思君喜见君。","高山共流水，覆雨更翻云。","初过留侯国，行经亚父坟。","当年谁作计，楚汉欲中分。"]},{"t":"直河晚泊","f":"五言律诗","c":["落日青山好，舟行复见山。","楚天穷眺望，河水正潺湲。","沙岸人争渡，柴扉夜不关。","向来戎马地，此夕且开颜。"]},{"t":"河涨","f":"五言律诗","c":["轻尘高弄日，新涨急翻江。","客子难为夜，乡心不可降。","村沽聊取醉，野调自成腔。","冥遣怀篇翰，垂帘短过窗。"]},{"t":"舟中晚景偶理琴","f":"五言律诗","c":["密叶隐日脚，微风蹙水纹。","客心随路远，人语隔溪闻。","过雨苏秋谷，征旂飏晚云。","匣琴多古意，移调奏南薰。"]},{"t":"晴发","f":"五言律诗","c":["气爽钟声远，天空鸟影微。","樯头分曙色，席背引朝晖。","水乱添新涨，沙明合旧矶。","田家沾足否，天遣远人归。"]},{"t":"山庄","f":"五言律诗","c":["细雨移花果，来禽帖重题。","山林元有骨，桃李自成蹊。","林旷传乾鹊，村深报午鸡。","暖泉如可浴，呼杖小桥西。"]},{"t":"方竹","f":"五言律诗","c":["仙人九节杖，谁琢玉成方。","倚石孤棱瘦，捎云列戟长。","莫将三弄笛，雅制独眠床。","多少圆机客，轮蹄满道傍。"]},{"t":"雪后","f":"五言律诗","c":["风雪初开野，江潮已到门。","水深三亩竹，春蚤一墀萱。","无事偏宜懒，初心苦畏喧。","不应吴市里，自有辟疆园。"]},{"t":"长至侍班","f":"七言律诗","c":["白玉阑干动晓容，凤笙吹律应黄钟。","侍臣蹑履趋金殿，天子垂衣覆衮龙。","云里雪花依仗落，炉间香气入帘浓。","却看下界罗星斗，身在钧天第几重。"]},{"t":"南郊驾出","f":"七言律诗","c":["南郊清禁锁乾文，时倚斋居望瑞云。","帝辇欲来香满路，宫门乍启晓初分。","芝房桂栋圜丘殿，虎旅龙骧太乙军。","昔日杨雄空丽藻，唯将羽猎奏明君。"]},{"t":"驾入","f":"七言律诗","c":["龙旂日射九关开，凤辇风高万乘来。","皇国山川自迥互，碧空云物尚徘徊。","依微花柳迎春仗，次第王侯献寿杯。","汉畤唐封俱鄙陋，虞书周典共昭回。"]},{"t":"东山草堂一首送东山刘先生致仕","f":"七言律诗","c":["堂成十载昼扃扉，不负山灵将相归。","物外渔樵相问答，阶前猿鹤有光辉。","偏宜夜月凉先到，可忍春云湿未飞。","想得夜阑还有梦，龙纹时动箧中衣。"]},{"t":"赋得新莺","f":"七言律诗","c":["花里新莺高复低，遍身金缕养初齐。","自来幽谷偏求友，惯领东风试学啼。","何处王孙停柳外，十年征戍忆辽西。","上林乔木知多少，他日一枝应借栖。"]},{"t":"秋声","f":"七言律诗","c":["高阁烦襟生远兴，忽闻凉籁动罗帏。","随风已去传鸣柝，傍月还来助捣衣。","疑有波涛从地起，独怜乌鹊正南飞。","长安此夜悲秋客，细数流年感是非。"]},{"t":"秋兴二首 其一","f":"七言律诗","c":["细雨兼风若有情，树边楼里伴秋清。","候虫灯火黄昏永，客子衣裳白苧轻。","魂梦几番偏故国，襟期何处慰平生。","壁间更与悲团扇，卧听梧桐落叶声。"]},{"t":"秋兴二首 其二","f":"七言律诗","c":["怅望西山宿雨晴，新凉高阁梦魂清。","秋于景物三分变，老觉功名一念轻。","日课就荒诗草少，月支无补俸钱赢。","长安岁岁逢摇落，宋玉情多鬓易星。"]},{"t":"秋日慧昭寺访旧迷道","f":"七言律诗","c":["不是桃源路亦迷，客心随马自东西。","萧疏榆柳如前岁，依约楼台记隔溪。","入寺绪风秋较早，照窗斜日鸟偏啼。","凭谁指点还归去，头白山僧有杖藜。"]},{"t":"秋日会通河送客","f":"七言律诗","c":["京国三年思故国，黄花时节又登台。","清江水冷鱼龙伏，落日天空鸿雁来。","忽漫逢人浑似梦，常因送客暂开怀。","鲈鱼莼菜江东地，不为莼鲈也合回。"]},{"t":"与徐昌国登鸡鸣山","f":"七言律诗","c":["临风萧散撤荆扉，缓步相携上翠微。","试日丙丁看塔影，赌松宽窄解腰围。","路侵璧水分鸣铎，石近僧床挂衲衣。","满目楼台形胜里，当年辛苦忆龙飞。"]},{"t":"送林见素都宪抚江西","f":"七言律诗","c":["阊阖天开袖疏来，先皇深意独怜材。","江摇旌旆云霞绕，诏剪丝纶日月回。","千里藩垣聊试手，百年海岳几生才。","故山闻说饶猿鹤，满地苍生半草莱。"]},{"t":"送刘直夫归省还江西","f":"七言律诗","c":["群联共爱挹兰芳，南浦魂销一举觞。","君独有亲甘去国，我宁无梦绕高堂。","天连鸟背迷寒雨，江引渔梁出晓霜。","珍重天涯易回首，官桥春日柳条长。"]},{"t":"双挽","f":"七言律诗","c":["萧萧松柏北邙道，连理凋残风日清。","地下有灵龙合剑，人间无主鹤归城。","山西短日迷椿影，机上残灯照雨声。","四尺碑头字如掌，行人读遍汝南评。"]},{"t":"元宵","f":"七言律诗","c":["满街灯火杂游尘，消受风光五日春。","微雨澹云城上月，纸灯茅店客中身。","家遥隔岁书随雁，山近当窗鬼笑人。","佳节不殊心赏异，梅花新水独相亲。"]},{"t":"破晓出水西门往江口途中作","f":"七言律诗","c":["城西买马滑冲泥，总为风光候指挥。","拍案寒潮惊晓枕，过江残雪上春衣。","梅花野寺初闻磬，杨柳村居半掩扉。","曙色渐分人渐远，五云双阙拥朝晖。"]},{"t":"子殇后二首 其一","f":"七言律诗","c":["消瘦腰支减练裙，异乡音信可堪闻。","青春满面殇儿泪，白骨三迁幼女坟。","萍水飘零风颤雪，文章消息雨收云。","业缘尚有迂痴在，爱惜图书未敢焚。"]},{"t":"子殇后二首 其二","f":"七言律诗","c":["磨蚁旋旋意绪同，伤春随处怯东风。","三年未了隆中卧，一旦谁收稷下功。","满径药苗因病减，隔窗蕉叶为书空。","细寻旧事轮纤指，云水今朝是几重。"]},{"t":"夜宿龙江驿","f":"七言律诗","c":["风尘随分三年住，灯火江村一夜留。","入市女郎能买酒，怀家游子怯登楼。","烟中舟楫来京口，云里钟铃出石头。","水净更阑不成寐，隔船乡思起吴讴。"]},{"t":"入京口闸","f":"七言律诗","c":["沙城扰扰人归市，喜色津津客过关。","船外寒潮随白鸟，树间花气绕青山。","梦魂风雨今宵减，乡国门墙五日还。","百里波涛幸无恙，满卮村酒慰慈颜。"]},{"t":"入晋陵西门往东门晚泊","f":"七言律诗","c":["百年雨露长繁华，烟柳长堤入市斜。","石岸楼船载箫鼓，朱阑帘幕护莺花。","软泥驿路人调马，细水溪桥女浣沙。","待泊黄昏更东下，满城灯火万人家。"]},{"t":"春暮还旧隐花木半存怃然拈笔有作","f":"七言律诗","c":["淡花疏竹旧帘栊，墙晕苔痕碧土浓。","春燕定巢应识主，夜蛾随幌独怜侬。","池塘课仆添栽藕，杯豆留人半采葑。","僻绝吾庐偏不厌，枕书日日卧高舂。"]},{"t":"夏日幽居即事","f":"七言律诗","c":["手汲清泉和碧烟，细临晋帖满吴笺。","南风送暑催三伏，西日下山留半圆。","丹柰雨肥禽着意，画梁泥足燕高眠。","方床高结跏趺坐，我与幽居信有缘。"]},{"t":"书扇寄王天锡乃兄天则","f":"七言律诗","c":["梅花岁岁凭君折，折尽梅花第几枝。","树杪暮云看去远，江湖游鲤到来迟。","诗今点窜成千首，路已经过熟九疑。","坐对惠连谈往事，夜来应梦草生池。"]},{"t":"挽周处士","f":"七言律诗","c":["生前不识处士面，身后空成处士吟。","小雨荷香池馆静，暖风花信草堂深。","青山昨夜悲埋玉，流水何年到赏音。","四尺碑头数行墨，罨溪松柏自萧森。"]},{"t":"寄王瑩中","f":"七言律诗","c":["定山风景近何如，江月江潮绕故庐。","龙洞旧游春服就，太玄新著夜窗虚。","满川花柳三杯里，隔岸楼台六代馀。","我独长安经岁晚，南来目断数行书。"]},{"t":"落花","f":"七言律诗","c":["蝶粉蜂黄冷浣溪，衰颜无主画楼西。","情缘偏恋鸳鸯水，勋业多留燕子泥。","荏苒芳尘湘魄化，飘摇红雨蜀魂迷。","池塘倍觉朝来胜，新绿成阴护鸟啼。"]},{"t":"馆中书事","f":"七言律诗","c":["疏慵旧业大江东，十载雕虫愧未工。","岂有才名惊行辈，徒劳中贵达宸聪。","少年贾谊吾安敢，今日相如事偶同。","自笑子虚无赋草，亲将迂策献重瞳。"]},{"t":"冯侍御野雉坪","f":"七言律诗","c":["芜莽频年杂采樵，山灵留此托高标。","纡回负郭瓜田近，平远如村石径遥。","日暖林端飞雉子，雨晴涧尾送鱼苗。","功成廊庙悬车处，应有芳名配午桥。"]},{"t":"张家湾志哀","f":"七言律诗","c":["五年此地往来过，人事悲欢奈尔何。","涕泪偏从寒夜堕，月华空自海门多。","天边衰柳连村郭，囊里残书废蓼莪。","沙际一灯人语寂，北风流水共悲歌。"]},{"t":"长女卒后复携家渡江","f":"七言律诗","c":["趋朝入市总无缘，江上新开二顷田。","水阁茅堂元自得，酒怀诗兴故依然。","夕阳度岭人吹笛，秋水临门客系船。","尚有旧书三百轴，海云江月共年年。"]},{"t":"送熊元交使越","f":"七言律诗","c":["山水苍苍古越州，菱花荷叶共维舟。","二高峰顶三更日，七里滩声五月秋。","灵雨自随征旆去，綵云常傍使星流。","江南江北还相望，两地各登高处楼。"]},{"t":"送顾与成使浙江","f":"七言律诗","c":["江南此去经年别，更欲殷勤不可攀。","细雨出城春淡泊，断冰辞岸水潺湲。","风花碧落莺迁谷，灯火黄昏吏报关。","归计越中须作早，石渠诸老待君还。"]},{"t":"邵氏园亭","f":"七言律诗","c":["主人池馆玉桥东，尽日轻尘不度风。","黄鸟爱啼墙曲里，绿云常护日方中。","茶分阳羡家园好，地接长安客况同。","何似更当良燕夜，月痕花影淡帘栊。"]},{"t":"雪夜听沈仁甫谈乡事","f":"七言律诗","c":["乡事连床话未休，春寒寂寂送春愁。","素衣怜子客千里，书烛摇人风满楼。","燕地雪花偏入暮，故园杨柳几经秋。","多情若问吴淞水，犹绕侬家日夜流。"]},{"t":"秋丁国学分祀","f":"七言律诗","c":["瑶坛夜气属秋清，礼殿衣冠肃上丁。","风度箫韶闻九奏，露垂银汉转三星。","青松团盖飘香篆，白玉围阑映舞翎。","圣道弥高垂万古，皇恩罔极授群经。"]},{"t":"题石淙二首 其一","f":"七言律诗","c":["入云袅袅石泉流，回首青山忆旧游。","天柱雪消银瀑下，海门日照紫烟浮。","即看鸟背三台路，疑有军声万里秋。","此地到江龙窟近，化为霖雨满神州。"]},{"t":"题石淙二首 其二","f":"七言律诗","c":["滇水湘山故有情，石淙又纪胜游名。","坐来风雨闻韶濩，挽作天河洗甲兵。","晓出五云随日捧，寒流千折到江清。","暗通气脉金山寺，更表东南铁瓮城。"]},{"t":"长陵","f":"七言律诗","c":["文皇功业冠吾朝，极目长陵北斗高。","龙虎千重常隐雾，松楸万壑骤闻涛。","礼成寝殿严三献，版署曾孙飨太牢。","浅薄小臣叨法从，夜分端拜拥青袍。"]},{"t":"景陵","f":"七言律诗","c":["景陵东奠接蓬瀛，长忆宣皇致太平。","弓剑閟严龙气合，楼台环琐斗杓横。","地高海岳依依见，天阔风云冉冉生。","万岁千年隆礼典，群官偏许夜深行。"]},{"t":"刘蕡祠二首 其一","f":"七言律诗","c":["谏议千年自有祠，唐朝宫阙黍离离。","多情瘦马冲寒到，无数青山落照迟。","往事空传台下骏，灵风常满庙前旗。","冰霜入夜频搔首，欲奠芳椒侑楚词。"]},{"t":"刘蕡祠二首 其二","f":"七言律诗","c":["门带冰堤一径随，丹青寥落见风仪。","当年去国呈秋卷，同辈看花满丽词。","言论纵危终爱主，英雄空好不逢时。","客来系马祠前树，独坐寒山有所思。"]},{"t":"书扇赠何子元武选","f":"七言律诗","c":["春风吹堕洞庭舟，春日来从鹦鹉洲。","万国风尘随独客，五更烟月下中流。","天边城阙身重到，笛里关山鬓已秋。","坐忆五年江海别，楚云吴树各登楼。"]},{"t":"赤水村登土冈同何子元武选张子醇仪制赋得春字","f":"七言律诗","c":["林馆来迟已暮春，追攀且得共高人。","贪山更送云中目，避日时移树里身。","台殿近瞻龙气绕，笙歌聊代鸟声频。","城西亦是风云地，不遣登临负此辰。"]},{"t":"赤水村与方道士","f":"七言律诗","c":["赤水村西风日晴，紫琳宫里凤箫声。","经冬翠竹摇仙佩，万里青山绕帝京。","休沐偶过花院静，盘飧兼爱药苗清。","主人已得长生诀，我辈空怀遗世情。"]},{"t":"思归饮钦之馆","f":"七言律诗","c":["乡心迢递郁难开，且醉佳人旧酒杯。","千里雁书回隔岁，五湖云树锁高台。","遥闻河北兵还满，坐看长安月又来。","容取腐儒江海上，仗君终作济时才。"]},{"t":"病起见庭萱有作","f":"七言律诗","c":["堂背花开空复情，客衣偏感岁年更。","满庭绿荫飞新燕，无数乡心啼乱莺。","病后强题眠食健，镜中常为鬓毛惊。","黄金台上频回首，惭愧当时买骏名。"]},{"t":"郑家口晚眺","f":"七言律诗","c":["落日旷野飞沙平，微吟捲席登岸行。","垂杨绿暗夕露下，细草碧铺晴月明。","空阔试穷远望目，飘零每动思家情。","明发一舟何处所，江湖随到问鸥盟。"]},{"t":"戏马台晚眺","f":"七言律诗","c":["王气萧条伯业收，彭城依旧砀山秋。","山连青郡兼齐绕，水合黄河入海流。","漠漠云边低度鸟，疏疏树杪送行舟。","凌空台阁宜春望，尚及西风半日游。"]},{"t":"对月","f":"七言律诗","c":["深院黄昏清露多，月明初上女墙过。","行边几度圆如此，高处不胜寒奈何。","宿鸟频翻动绿树，钓船遥忆开金波。","山城漏永坐来久，牛女今宵正隔河。"]},{"t":"淮阴祠","f":"七言律诗","c":["是非千载总成空，满地凄凉在眼中。","落叶数声秋雨暗，女墙寒影夕阳红。","旌旗南国悲游辇，圭璧东陲想故宫。","书剑扁舟乘夜发，拥炉閒坐读周公。"]},{"t":"虎丘","f":"七言律诗","c":["江乡萧飒不禁秋，古刹名山占此丘。","云护龙池迷雁塔，雨平虎迹上渔舟。","声传清梵疏钟出，衣妥红莲极浦流。","千古宛然浑在眼，越王台畔女墙头。"]},{"t":"晚行浦中","f":"七言律诗","c":["秋江东北风吹棹，夜色西南月度河。","客子生涯随路酒，渔郎消息隔烟歌。","雁行千里缄题到，牛背前村短笛过。","船外暗香来不断，芙蓉知傍水云多。"]},{"t":"苦热","f":"七言律诗","c":["朝来病骨不胜衣，望断淮南一雁飞。","故国青山三亩宅，何年白屋两重扉。","况堪旅舍多殇殡，安忍家书远报归。","长日畏途犹苦热，江天閒杀白鸥矶。"]},{"t":"严陵","f":"七言律诗","c":["严江秋色碧于空，严陵祠堂江水东。","山云不断欲作雨，岩树半欹常背风。","行人度岭忽高下，返照入壁时青红。","棹歌互逐渔歌起，相送楼船上峡中。"]},{"t":"将游龟峰寄汪抑之器之二太史","f":"七言律诗","c":["爱此秋高风日清，纡回常作探山行。","俯看飞鸟有时下，怅望美人无限情。","沙净水根偏见石，树含谷口少闻莺。","好峰只隔斜阳外，拟借新居卧月明。"]},{"t":"谒张东海先生墓","f":"七言律诗","c":["东海先生天下士，近从骥子读遗文。","风霜满壑松杉古，日月双悬晓夜分。","书带尚萦阶下草，练裙疑化岭头云。","廿年正有高山仰，形胜东南更出群。"]},{"t":"下凤山南麓闻曹定翁先生夜过山居至已西还瞻行花竹间奉怀一首","f":"七言律诗","c":["遥传拄杖过山居，度壑穿云更短渠。","入院秖馀霜后菊，护窗唯有读残书。","聊镵翠竹留题字，独上青松望小车。","咫尺怀人情万里，江流为觅一双鱼。"]},{"t":"骢马一首寄同年沈御史子公","f":"七言律诗","c":["长安骢马铁连钱，新赐黄金铸作鞭。","千里共看皮骨好，五花应入画图圆。","昭王筑罢燕台下，桓典骑来御苑边。","已见过都频历块，最怜神骏斗春妍。"]},{"t":"甲戌二月十三日大雪厚数寸晚得月书事","f":"七言律诗","c":["琼瑶满地月华明，寒勒东风过海城。","午夜梦魂清化蝶，蚤春心赏负流莺。","半空台殿疑无影，几处江湖尚有情。","泽国年年候农事，恐惊风雨报西成。"]},{"t":"雪霁与朱子文陈起静访李百朋舟次先寄","f":"七言律诗","c":["雪消沙岸暗潮通，南浦仙舟二妙同。","柳褪冻痕黄欲绽，雁拖夕照晚犹风。","几年乡梦三更后，十里波光一棹中。","复有月明同下榻，山阴却笑兴偏穷。"]},{"t":"甲戌四月八日再游龙华有述","f":"七言律诗","c":["六日龙华两度游，陆行骑马水行舟。","风云塔院松将暝，烟火村家麦已秋。","病到静馀初减药，望穷天际更登楼。","桑榆苦爱清江曲，常愧山僧半日留。"]},{"t":"春兴和张碧溪韵","f":"七言律诗","c":["天上归来白玉京，茅堂依旧带江城。","安身已办乌皮几，晚食初尝玉糁羹。","何用门前栽五柳，秖须石上结三生。","东风又送催花雨，起向花间次第行。"]},{"t":"赠别碧溪次韵","f":"七言律诗","c":["江上忽闻歌濯缨，好风如护客南行。","黄金总为收书尽，白发长因觅句生。","乡里定誇能老健，交游谁复更多情。","不须惆怅江湖晚，造物从来本忌名。"]},{"t":"江上载疾送严介溪太史","f":"七言律诗","c":["风风雨雨度江来，此岁登临第一回。","五月葛衣犹未著，几群鸥鸟莫相猜。","催农已尽黄梅节，送客须传绿蚁杯。","南去舵楼波浪阔，望君真是济川才。"]},{"t":"送黄竹泉兄弟南还","f":"七言律诗","c":["雪后遥山紫翠重，宦情归兴二难同。","天边楼阙身曾上，冀北风云眼独空。","到日春回紫荆树，去途诗和鹡鸰风。","悬知别后相思处，江北江南夜月中。"]},{"t":"除夜僦居对雪","f":"七言律诗","c":["谁遣天花白满筵，破除残腊入新年。","江山万里春犹浅，烟火千家夜未眠。","马援归来空有累，扬雄老去始知玄。","浮生踪迹元无定，泥上飞鸿亦偶然。"]},{"t":"雪后游广恩寺赠同游张仪部","f":"七言律诗","c":["落日未落西城西，孤亭曲径绕冰堤。","丹青合殿烟初暝，紫翠千峰雪后低。","万里旌旗闻战伐，一年风物送攀跻。","同来苦爱张平子，袖有琅玕锦绣题。"]},{"t":"绿雨楼漫兴","f":"七言律诗","c":["暑雨初晴树色偏，昼长风景满楼前。","天边白鸟兼云没，帘外青虫映日悬。","古鼎香烟时袅袅，小池墨水复涓涓。","纶巾羽扇閒居服，独对南薰理太玄。"]},{"t":"禁中观雨","f":"七言律诗","c":["天连仙掌曙光分，龙气遥瞻五色文。","山势浮依金殿转，檐声清报玉堂闻。","似知佳节催农事，愿比甘霖奉圣君。","昔日侍臣怜宋玉，空将丽藻赋行云。"]},{"t":"下陵","f":"七言律诗","c":["仙阶瑶砌雨如膏，大飨初成月正高。","夜静溪声传水乐，山空天籁奏松涛。","参差灯烛趋群从，次第官僚备列曹。","更许乘骢向归路，一宵清境不知劳。"]},{"t":"月下有怀王存约都谏倪本端祠部二首 其一","f":"七言律诗","c":["岁晚相思雪满庭，也知祠部亦冰厅。","心期许我俱头白，云路何人独眼青。","落尽灯花收夜局，寄来诗草带春星。","长安客舍多如许，每过门时马自停。"]},{"t":"月下有怀王存约都谏倪本端祠部二首 其二","f":"七言律诗","c":["雪后楼台斗月明，怀人咫尺最关情。","心无机事如君少，时有诗篇过我评。","琪树夜寒巢鹤怨，紫箫声远彩鸾轻。","想应正草回銮疏，倚遍阑干卧未成。"]},{"t":"登翠微恭望长陵有述","f":"七言律诗","c":["春深王气蔼重重，身到中天望转浓。","近接星辰看拱极，遥从江汉识朝宗。","风回乔木千章合，时有祥云五色封。","一自鼎湖仙去后，万年弓剑閟真龙。"]},{"t":"八日雪中自海子东过朝天宫习仪","f":"七言律诗","c":["今日自誇银海过，古来空羡雪溪游。","连天紫气迷金殿，绕郭青山尽白头。","高处寒多浑可奈，望中人远不胜愁。","一年长至须成庆，重试鸡人拜冕旒。"]},{"t":"展牲还","f":"七言律诗","c":["月照斋心万虑空，严寒时送北山风。","冰蹄入夜天关紫，宵御分行烛影红。","世事浮云千态出，故人破冻一尊同。","江南苦忆归耕地，三匝茅堂一亩宫。"]},{"t":"廿四日再出视牲","f":"七言律诗","c":["落日朱衣五色纹，天南清閟锁祥云。","重来正及春初动，归去遥怜夜已分。","十里瑶坛当地脉，万年郊祀应乾文。","风云喜为传消息，翠辇黄麾度汉汾。"]},{"t":"郊坛还赠同行余德重副郎","f":"七言律诗","c":["贝阙珠宫上帝居，月华夜气斗清虚。","西来步出天门迥，东望春随斗柄初。","粉署仙郎时并马，禁城银钥尚留鱼。","御街风色香尘细，吟过南郊十里馀。"]},{"t":"初与郊祀分献风云雷雨坛","f":"七言律诗","c":["露冕垂绅午夜长，瑶坛灏气正苍苍。","灵飙不度松声细，端拜初来曙色凉。","愿有风雷悟明主，敢将云雨赋襄王。","圜丘礼乐今皇盛，万骑千庐簇女墙。"]},{"t":"候祭","f":"七言律诗","c":["神道如弦春月寒，女城西畔第三坛。","楼台始信中天起，星斗翻从下界看。","五色龙蛇摇羽盖，九重烟雾蔼椒兰。","君王合在清斋殿，共听钟声夜向阑。"]},{"t":"孤闷中有怀途次儿女","f":"七言律诗","c":["细雨斜风隔市尘，重门深巷怕逢人。","春随久病难为客，老觉虚名苦累身。","何处桃花流水漫，一宵魂梦鬓毛新。","天涯儿女痴心在，寄语家贫未是贫。"]},{"t":"秋怀","f":"七言律诗","c":["曲径孤亭尽日幽，砧声又动一年秋。","诗因才减频留草，老为情多易得愁。","天上风云金鼓迥，江南鸿雁稻粱稠。","阴晴却恐随朝暮，半月乡书十度修。"]},{"t":"秋病","f":"七言律诗","c":["病里逢秋愁转多，隔窗风雨满庭柯。","寒衣欲授催砧杵，乡梦初成绕薜萝。","天上楼台真是好，人间岐路竟如何。","山东兵气看云变，何日王师奏凯歌。"]},{"t":"奉和石斋少师对菊","f":"七言律诗","c":["封后文书紫阁閒，对花身在五云间。","松筠岁晚偏知己，桃李春归空厚颜。","自许托根依凤阙，谁从落帽宴龙山。","多情未忍轻归去，莫待金莲辍送还。"]},{"t":"哭桴儿六首 其一","f":"七言律诗","c":["生儿辛苦拟传家，摇落秋风感岁华。","过客虚烦奇跨灶，行窗留取乱涂鸦。","旅魂欲返疑无路，泪眼频挥似有花。","强起凭高望南国，断云流水远天涯。"]},{"t":"哭桴儿六首 其二","f":"七言律诗","c":["经行无处不伤神，新剪罗衫四尺匀。","病母五更能送药，阼阶三揖解迎宾。","浑疑死别还生别，莫问前身与后身。","我已白头聊哭汝，高堂更有白头人。"]},{"t":"哭桴儿六首 其三","f":"七言律诗","c":["半生苦爱说忘情，翻觉情多遣未成。","梦后青灯风不定，搔来白发镜偏明。","家书自写疑还信，世路谁凭住与行。","悲怨短长吾岂敢，空令身外有虚名。"]},{"t":"哭桴儿六首 其四","f":"七言律诗","c":["琴书办得为消忧，独抱琴书可自由。","归计未能随北雁，年华无奈逐东流。","废来诗草谁收拾，验后医方自检求。","宾客不通门巷寂，几番寒日下西楼。"]},{"t":"哭桴儿六首 其五","f":"七言律诗","c":["更阑爱听短歌声，倦倚藤床趁画屏。","几处远书还诧友，最怜同学尚寻兄。","鬓从此地双蓬短，人过中年万念轻。","后夜客居聊复尔，泪痕偏映月华明。"]},{"t":"哭桴儿六首 其六","f":"七言律诗","c":["客舍并州背苑墙，独缫愁绪鬓丝苍。","三千里外抛中产，四十年馀哭下殇。","院静风帘随日动，城高霜角共更长。","可能会得探环事，来续衰翁未断肠。"]},{"t":"五七哭桴次吴朝言御史韵二首 其一","f":"七言律诗","c":["坐依尘榻起循墙，一月情怀两鬓苍。","生死最怜俱作客，岁华翻恨未成殇。","何愁异日居人后，空想他时共我长。","见说食荼肠易苦，极知荼苦不如肠。"]},{"t":"次韵温菊庄大参","f":"七言律诗","c":["浣花溪上草堂閒，多在青松白石间。","不与风云重入梦，每逢山水一开颜。","慕陶兴寄霜前菊，和杜诗成雨后山。","闻道年来倍强健，溪藤高拄看云还。"]},{"t":"寄怀","f":"七言律诗","c":["独上沧江百尺台，夕阳无数鸟飞回。","寒暄气候随时变，翻覆人情秖自猜。","白发有期和我长，黄花着意为谁开。","壁间团扇寻常事，空说班娘最有才。"]},{"t":"元年除夕试笔二首 其一","f":"七言律诗","c":["岁寒冉冉夜将除，景物依依绕故庐。","大禹三江俱到海，春王五始合教书。","山中日月从閒积，天上风云入望馀。","何用青铜看勋业，自应愁鬓已萧疏。"]},{"t":"元年除夕试笔二首 其二","f":"七言律诗","c":["蜡炬含风夜不寒，得从儿女簇杯盘。","粗知万里归犹暮，老觉多情遣更难。","期与青春酬寸草，羞将白发付弹冠。","百年尘世同官历，今夕明朝取次看。"]},{"t":"二日阴","f":"七言律诗","c":["江天不断海云生，谁遣阴晴总未成。","苔片渐随閒径积，梅花欲傍小桥横。","占年法向山农问，种树书从老圃评。","幽兴最关新节候，莫教风雨妒春明。"]},{"t":"次韵王钦佩寄秦元甫","f":"七言律诗","c":["赋就停云第几篇，江湖渺渺转堪怜。","更随骥尾知何地，同抱龙髯忆往年。","惆怅又逢三月暮，梦魂多在五更前。","金陵城里山如画，城外谁营二顷田。"]},{"t":"山居和答邹山人","f":"七言律诗","c":["城上楼台隔暮霞，敢誇泉石自成家。","空烦妙句追风雅，自许閒人领物华。","岸柳岁深高拥日，潮田水落半侵沙。","倚阑正见三江口，剪取吴淞共试茶。"]},{"t":"寒食展墓","f":"七言律诗","c":["细雨东风晓未晴，养花天气近清明。","人间桃李俱生色，望里松楸独系情。","龙剑上腾星汉阔，奎章遥映锦云横。","伤春不道春如许，芳草年年满路生。"]},{"t":"初夏四首 其一","f":"七言律诗","c":["桔槔声里送春归，乳燕迁莺接队飞。","入砚柳花还碍笔，扑帘槐雨欲沾衣。","月茶初碾金文饼，团扇新裁白练机。","小阁正宜清润候，昼长消得往来稀。"]},{"t":"初夏四首 其二","f":"七言律诗","c":["银塘新水鸭头纹，载酒浮花动午薰。","老圃养成三径竹，野人耕破一溪云。","廉纤雨脚晴不断，怯恰莺啼远更闻。","为惜琴书妨溽暑，自锄苔砌辨香芸。"]},{"t":"初夏四首 其三","f":"七言律诗","c":["穹林迢递绿生烟，漠漠澄空映水田。","唤雨唤晴鸠不住，能高能下燕频穿。","春晖东去元无恙，风力南来渐有权。","起坐江楼自清晓，游鱼吹浪碧荷圆。"]},{"t":"初夏四首 其四","f":"七言律诗","c":["绿阴庭院昼初长，药碾丹炉按古方。","病后精神浑爱惜，閒来文字费商量。","自携藜榻安风背，新作茅堂向水阳。","子鲚正肥斑竹笋，欲将身世老江乡。"]},{"t":"夏日山居三首 其一","f":"七言律诗","c":["柳烟槐雨带斜阳，极浦遥山入渺茫。","溪水通潮鱼作队，梅风催夏稻成行。","奇书到手添交直，往事惊心免校量。","缥缈有声来别院，小儿新课甫田章。"]},{"t":"夏日山居三首 其二","f":"七言律诗","c":["小卜山居背郭开，江流面面绕亭台。","树犹若此谁堪待，少不如人老渐来。","一曲缓歌闻白苧，满天凉雨过黄梅。","野情转觉閒方称，愿与君王乞草莱。"]},{"t":"夏日山居三首 其三","f":"七言律诗","c":["绿阴树树水田田，坐爱牛羊散远天。","风送潮声来别浦，云收雨脚过平川。","几村茅屋青山外，无数渔舟白鸟边。","不信桃源是何处，每将文字万人传。"]},{"t":"初秋夜","f":"七言律诗","c":["随身枕簟绮窗虚，映水楼台晚浴初。","梦里已无投笔事，閒来如有绝交书。","看低北斗知宵永，惊早西风是病馀。","家在吴淞江上住，底须天际忆鲈鱼。"]},{"t":"秋兴三首 其一","f":"七言律诗","c":["茂苑长洲东复东，江天淼淼夜含风。","谁家吹笛关山里，几处征衣捣练中。","雁字未成云又合，鱼书欲寄路难通。","不知宋玉才多少，只赋悲秋已自工。"]},{"t":"秋兴三首 其二","f":"七言律诗","c":["摇落年光急暮笳，得开怀处是还家。","新凉门巷堪罗雀，旧业园田学种瓜。","南浦风波看白鸟，东篱消息探黄花。","疏慵莫道浑无事，袖手犹能领物华。"]},{"t":"秋兴三首 其三","f":"七言律诗","c":["半空凉籁撼千军，满地秋光锦绣纹。","近水芙蓉先带露，故园杨柳欲欺云。","凭高万里从今见，行乐三秋自古闻。","堪叹扬雄甘寂寞，一生空老太玄文。"]},{"t":"秋怀十二首 其一","f":"七言律诗","c":["景物逢秋老更成，峡猿何必断肠声。","习家池上歌如沸，庾亮楼头月正明。","万里山川催木叶，五更钟鼓动江城。","当年与赐金茎露，梦断空瞻白玉京。"]},{"t":"秋怀十二首 其二","f":"七言律诗","c":["天阔风高秋意多，青山如削水层波。","知归玄鸟遥怜汝，向晚黄花独奈何。","故国笙歌遗玉树，前朝荆棘有铜驼。","兴亡亦是浮云事，古往今来鬓自皤。"]},{"t":"秋怀十二首 其四","f":"七言律诗","c":["青灯挑雨不成眠，爱听芭蕉夜似年。","去日苦多无计款，浮生如寄定谁贤。","成功白发冯唐老，好事青山谢客偏。","他日向平粗毕愿，懒云秋水护沙田。"]},{"t":"秋怀十二首 其六","f":"七言律诗","c":["閒阶积雨长莓苔，药裹诗签手自裁。","潦水正须愁八月，浮云常与望三台。","长沙卑暑偏饶病，岭表风波是有才。","茅屋若为容我老，文章一洗旧悲哀。"]},{"t":"秋怀十二首 其九","f":"七言律诗","c":["潮声江上唤登临，日日东流故故深。","十尺莼丝风荡飏，一天鱼信雨侵淫。","鸱夷去后犹堪恨，禹迹南来不可寻。","一曲吴娃双画桨，蛟龙堆里昼阴阴。"]},{"t":"秋怀十二首 其十","f":"七言律诗","c":["总为秋光满葛巾，未应偏怪白头新。","明珠本自能疑我，沙鸟何心却避人。","一片云轻终过眼，百年论定不随身。","草堂旧在三江上，听水听风知几巡。"]},{"t":"秋怀十二首 其十一","f":"七言律诗","c":["团扇情多咏未休，井梧何事强知秋。","霜华先上双蓬鬓，壮气空馀独倚楼。","谁复常何工荐士，徒闻李广不封侯。","千寻铁锁如堪借，借与人间锁断愁。"]},{"t":"秋怀十二首 其十二","f":"七言律诗","c":["病回门巷昼长扃，留滞周南改岁星。","满目秋容频看镜，十年旧带屡移钉。","高梧急雨闻金井，柞火新凉照素屏。","深夜不眠缘底事，自携铅椠校丹经。"]},{"t":"自八月二日至六日皆大潮成巨浸颇得奇观","f":"七言律诗","c":["爱看秋水坐斜曛，汗漫东来昔未闻。","风送潮头喷积雪，波连天际贴层云。","高声疑有蛟龙怒，远影空迷鹳鹤群。","安得此心无一事，南华经里老遗文。"]},{"t":"元宵","f":"七言律诗","c":["横笛短箫催暮筵，星桥火树共参天。","人于年谷占先兆，老向烟花正有缘。","霄汉无声风力定，山河留影月华圆。","他乡频岁冰霜里，故国今宵殿阁边。"]},{"t":"渡江","f":"七言律诗","c":["桂楫兰桡江水生，前麾小队渡江行。","人生几度东风面，花信一番春雨晴。","初日出林光欲动，丰泥逐马滞犹轻。","少年游钓难忘处，莫怪丘园太有情。"]},{"t":"次韵王子升侍御登姑苏玉峰二首 其一","f":"七言律诗","c":["牙旗分队捲芳埃，独上姑苏百尺台。","南斗下临东海近，青山多在白云隈。","谩劳此地兴亡恨，共仰中朝将相才。","合是长城应万里，野人林壑卧苍苔。"]},{"t":"次韵王子升侍御登姑苏玉峰二首 其二","f":"七言律诗","c":["目极长亭更短亭，观风使者节初停。","潮头东去和云白，山势西来绕郭青。","艳冶莺花春入望，太平门户昼长扃。","阖闾最爱干将剑，化鹤归来尚姓丁。"]},{"t":"旧墓","f":"七言律诗","c":["夕阳一片好山光，啼鸟啼猿总断肠。","有客已成风木恨，何人为废蓼莪章。","年年芳草催寒食，隐隐青山似洛阳。","流水桥东频立马，一杯时复奠椒浆。"]},{"t":"七月四日与姚时望放舟过南浦","f":"七言律诗","c":["早秋烟水带云山，江上扁舟信往还。","潮力渐随青草短，野心元共白鸥閒。","爱谈旧事消残暑，赖有青尊破老悭。","四十年前钓游地，归来双鬓已成斑。"]},{"t":"五日夜坐见新月","f":"七言律诗","c":["中庭秋影又经年，节序惊传巧夕前。","一井西风梧叶信，满溪凉露稻花天。","多情宋玉偏工赋，晓事扬雄晚尚玄。","江上小堂蕉石里，不妨灯火抱书眠。"]},{"t":"元日渡江二首 其一","f":"七言律诗","c":["残日楼台媚远天，清寒先觉鬓毛偏。","多情桑梓依江郭，过眼烟花改岁年。","龙气常占云五色，蓬山只隔路三千。","东风似解知人意，吹向梅边复柳边。"]},{"t":"元日渡江二首 其二","f":"七言律诗","c":["潮回沙际识春回，远见帆樯映雪开。","向晚中流空日月，倚天隔岸有楼台。","波涛东下元相逐，鸥鹭群飞莫浪猜。","一望海云俱不极，令人遥忆济川才。"]},{"t":"怀江东山居","f":"七言律诗","c":["知非知命复知还，不负青青屋后山。","无数好花临水净，几群娇鸟弄春蛮。","子云辞赋终成悔，摩诘图书早占閒。","爱杀江楼无一事，重帘长护白云间。"]},{"t":"元宵风雨","f":"七言律诗","c":["风雨无端妒早春，上元灯火寂游尘。","此身天地谁非幻，何物阴晴解弄人。","台殿下方空怅望，星娥高处自精神。","强扶残病酬佳节，绛蜡银屏照座新。"]},{"t":"十八夜雨","f":"七言律诗","c":["细雨斜风转寂寥，闹春灯火第三宵。","姮娥爱影收鸾镜，歌吹生寒湿凤箫。","此夜金吾还不禁，多情银烛更高烧。","阴晴本自关天意，恩怨人间总未消。"]},{"t":"雨中楼居","f":"七言律诗","c":["惜春心绪雨连宵，作阵飏空势转骄。","晚向梅花愁烂熳，早从桑土念飘摇。","行人泥滑三汊路，渔子潮平独树桥。","别有好怀高阁里，捲帘香雾倚云霄。"]},{"t":"出西郊书感","f":"七言律诗","c":["花香草色遍天涯，团盖风多旭日迟。","负郭人家田陌陌，送春心绪柳丝丝。","未应华发偏怜我，试问流年苦为谁。","路绕溪回无限好，何人不起钓游思。"]},{"t":"七夕与客夜坐","f":"七言律诗","c":["花外阑干雨乍稀，早秋风候报罗帏。","亿千万劫俱遭遍，四十九年都是非。","白石清泉初已遂，高山流水愿多违。","谁云白发三千丈，信手梳来不过衣。"]},{"t":"和徐鹤溪宜兴道中喜雨韵","f":"七言律诗","c":["溪上山青更水青，楼船摇动棹歌声。","先尝阳羡龙团细，不慕扬州鹤背轻。","铁瓮潮声还寂寞，铜棺秋色倍分明。","仙郎才调元如锦，白雪新篇击楫成。"]},{"t":"簳山晓发经行福泉过青龙","f":"七言律诗","c":["画船春尽水云和，晓梦中间十里过。","山色拥螺澄海雾，溪流如带绾江波。","逢人每问三三径，对酒遥闻款款歌。","最爱凌空凭雁塔，何妨此地著渔蓑。"]},{"t":"青龙南寺与时望辈步过北寺观三亭桥冒雨乘肩舆还","f":"七言律诗","c":["漠漠溪田半草莱，曾闻此地起楼台。","黄金歌舞有时尽，赤县轩墀何日开。","高阁俯阑惊鹳鹊，古碑看字剔莓苔。","软舆十里乘春雨，花柳情多喜客来。"]},{"t":"咏鹤","f":"七言律诗","c":["翩翩一鹤下云中，正倚高楼落日东。","忆得羽毛如昨梦，不教心力破长空。","呼童护足防秋雨，看汝梳翎飏晚风。","赤壁青田是何处，忘机聊与海鸥同。"]},{"t":"王昭君","f":"古风","c":["却抱琵琶别汉宫，长城万里戍楼空。","一身远嫁从明主，半面新妆付画工。","云外不殊青琐月，塞前初?黑山风。","异乡景物新相识，无限悲欢晓角中。"]},{"t":"题南庄号","f":"七言律诗","c":["背倚青山面水田，草堂修竹向阳天。","夜深南斗当窗见，雨后薰风掠燕翩。","牧笛农歌俱负郭，西成东作总丰年。","主人爱打蒲团坐，一卷庄生秋水篇。"]},{"t":"题松泉号","f":"七言律诗","c":["藤杖芒鞋白叠巾，松泉随处是知音。","半空素练悬秋色，十里青山荡午阴。","坐爱团圞当偃盖，卧听呜咽替弹琴。","道人缘业休相问，声色中间未了心。"]},{"t":"题渔乐图","f":"七言律诗","c":["平沙坦路有风涛，便欲移家傍此曹。","鼓棹鸣榔自成趣，卖鱼沽酒不辞劳。","拖蓝槛水春云腻，破白船窗夜月高。","收网一灯山下泊，绿蓑衣底读离骚。"]},{"t":"赠别郑廉","f":"七言律诗","c":["新作相逢别更新，雨中心绪病中身。","空劳魂梦游千里，又负莺花过一春。","江上水深芳草合，尊前人远尺书频。","归舟若度严陵濑，此夜灯花定有神。"]},{"t":"八月十六夜渡江","f":"七言律诗","c":["天上金波影未阑，人间已作隔宵看。","千家香雾笼银兔，一派天风吹紫鸾。","夜色分秋当二八，桂华作意让团圞。","不知高处还谁忌，倚遍幽人十二阑。"]},{"t":"嘉靖乙酉八月晦曰予卧疴山堂木槿一株白花千叶移植盆中与表弟顾世安文学姚时望孙则夫把酒赏之为赋近体一首","f":"七言律诗","c":["曾闻郑女咏同车，更爱丰标淡有华。","欲傍苔莓横野渡，似将铅粉斗朝霞。","品题从此添高价，物色仍烦筑短沙。","漫道春来李能白，秋风一种玉无瑕。"]},{"t":"时望渡江去与世安坐对叠韵","f":"七言律诗","c":["冰肌素质雪翻车，摇动秋光岁有华。","映水盈盈弄云日，隔溪澹澹锁烟霞。","野人酷爱编青鄣，老圃先教拥白沙。","闻道琼花最奇绝，扬州望幸却微瑕。"]},{"t":"九月朔晨起盆中再著数花适钱国辅自松城至为余作俨山玉舜图邑中数客继集而世安具扁舟西去矣即席再叠","f":"七言律诗","c":["月下风前宜小车，令传白帝敛繁华。","漫挥词手填青玉，欲酹花神浇紫霞。","佳节正逢黄菊信，高情分占白鸥沙。","相如自保完归去，赵璧从来本不瑕。"]},{"t":"时望一和得五首再叠一首为答","f":"七言律诗","c":["羡汝胸中书五车，登高还共赋瑶华。","几家篱落多秋意，一树冰霜带暮霞。","不是托根通阆苑，即疑传种自流沙。","最怜未识东风面，一见东风定有瑕。"]},{"t":"再叠答诸贤和章","f":"七言律诗","c":["日日诗筒走传车，山中草树有光华。","花神让雪三分白，文气成龙五色霞。","肺病夜窗和玉露，美人秋水隔江沙。","无由报得风骚手，白玉明珠总未瑕。"]},{"t":"秋日鹤溪明府过山居见和玉舜七首再叠三首为答 其一","f":"七言律诗","c":["门外频劳长者车，山中风物过繁华。","未成雪卧袁高士，已见仙才蔡少霞。","一任登临留胜槩，虚烦拂拭到泥沙。","欲将花比河阳县，花似潘郎恨有瑕。"]},{"t":"秋日鹤溪明府过山居见和玉舜七首再叠三首为答 其二","f":"七言律诗","c":["羊裘曾起赴安车，恨杀当年宠丽华。","木槿篱间好风露，芙蓉江上共烟霞。","移将一树浑如玉，老去閒居却枕沙。","陶令閒情空有赋，从来白璧忌微瑕。"]},{"t":"秋日鹤溪明府过山居见和玉舜七首再叠三首为答 其三","f":"七言律诗","c":["缘江路僻不容车，开过芙蕖又舜华。","澹泊看花宜待月，风云映水尽为霞。","正堪结社三江口，何似封侯万里沙。","试把一杯重酹汝，不须自献玉无瑕。"]},{"t":"西津沈方伯屡和至十八首未已再叠二首为答 其一","f":"七言律诗","c":["班输妙具九攻车，何似休文句最华。","晓日芙蓉出溪水，暮云杨柳隔江霞。","曾闻南国甘棠咏，须筑长安宰相沙。","劫火自惊山石烈，不知白璧本无瑕。"]},{"t":"西津沈方伯屡和至十八首未已再叠二首为答 其二","f":"七言律诗","c":["每向花前望小车，诗成一一叹才华。","须烦妙手题黄绢，绝胜当筵赋落霞。","一任江天狎鸥鸟，十年边塞长风沙。","晏婴犹惜封书社，卫国何劳怨子瑕。"]},{"t":"陈仲鲁玉舜诸作予读之悲其志焉再叠一首慰之","f":"七言律诗","c":["凌波仙子下云车，想见铢衣湿露华。","万种閒情偏隔水，一天佳气半成霞。","绪风寒勒花间蝶，落日晴衔江上沙。","办得素心终不改，有人抵死保无瑕。"]},{"t":"再叠得七首 其一","f":"七言律诗","c":["伐檀江上未成车，独立西风殿岁华。","谁复赏心同素月，自怜春殿隔红霞。","前身合住琼花观，托迹遥连杜若沙。","不是风云终少气，翻缘玉石共无瑕。"]},{"t":"再叠得七首 其二","f":"七言律诗","c":["疑是星精谪五车，不随红紫领韶华。","疏篱野水谁成伴，淡雨微云欲变霞。","为客缁衣惊岁月，倩人团扇掩风沙。","閒情脉脉秋江上，玉面啼痕错认瑕。"]},{"t":"再叠得七首 其三","f":"七言律诗","c":["颜如秾李不同车，千古诗人咏德华。","凉信预教秋作伴，孤芳无藉锦为霞。","梦回岁月梨花院，望断西风白鹭沙。","携向玉阑干畔种，青蝇不放点成瑕。"]},{"t":"再叠得七首 其四","f":"七言律诗","c":["风雨无端懒税车，坐当秋水阅南华。","花开一树临重九，人倚高城望少霞。","颜色不随游女艳，心情常近狎鸥沙。","绝怜何用频携酒，沾醉姿容玉带瑕。"]},{"t":"再叠得七首 其五","f":"七言律诗","c":["绕檐铁马骤鸣车，花有清阴月有华。","江上水天同一色，望中台殿隔西霞。","风随秋远闻香露，潮识溪寒阁浅沙。","无计可留摇落尽，共梅开处斗无瑕。"]},{"t":"再叠得七首 其六","f":"七言律诗","c":["水云深处挽羊车，寻乐寻芳湿露华。","花径五风还十雨，江天孤鹜伴飞霞。","霜前已露全身白，风外遥怜半面沙。","爱杀临流晴照影，青铜如拭净无瑕。"]},{"t":"再叠得七首 其七","f":"七言律诗","c":["看花每枉故人车，花亦迎人带露华。","是处倚阑怜夜月，几回携酒泛春霞。","银瓶手插新添水，玉树情亲细碾沙。","欲寄报章重阁笔，墨痕翻惜茧光瑕。"]},{"t":"晚饮张虞卿舍西江泛月还舟","f":"七言律诗","c":["南邻归去夜如何，鼓吹无风棹有歌。","两岸碧波潮力定，一身清露月明多。","天空星斗中流动，家近舟航一水过。","千古胜游谁得似，前须太白后东坡。"]},{"t":"九日","f":"七言律诗","c":["满目云山气转豪，一年佳节又登高。","天连泽国西风远，书寄秋怀北雁劳。","三径素盟频问菊，六经遗事且题糕。","授衣时叙偏惊眼，箧里犹馀旧赐袍。"]},{"t":"九月望初寒独坐","f":"七言律诗","c":["风回野渡水云空，犹是江南九月中。","病后岁寒偏觉早，眼前心赏更谁同。","萧萧竹院诗初就，曲曲山居画未工。","赖有夕阳西浦上，殷勤留送半窗红。"]},{"t":"十月朔与客汎舟游静安寺","f":"七言律诗","c":["芦子东西野渡边，前朝宫殿赤乌年。","夕阳逗林钟磬响，涌泉堕地珠玑圆。","萧然冠服岂傲吏，偶尔宾从如登仙。","三江禹迹不可问，一舸鸱夷非昔贤。"]},{"t":"十一月朔江门观涨","f":"七言律诗","c":["渺渺烟波连海门，长风吹浪昼为昏。","矶头锦树随船出，天上银河倒地喧。","便欲乘槎贯牛斗，却愁断梗失山村。","新寒十月登楼望，岸草汀花半不存。"]},{"t":"七宝镇拟访黄天章宪副寒甚不果","f":"七言律诗","c":["乘兴何妨似剡溪，故人只隔市桥西。","心情聊复同云水，踪迹真怜在雪泥。","白下馆前时系马，黄金台下共闻鸡。","扁舟定有重来约，来上春风细柳堤。"]},{"t":"游东石山园","f":"七言律诗","c":["度壑穿岩窅窱通，好山多在夕阳东。","望穷碧海龙宫近，踏破苍苔鸟篆工。","花坞四时常带雨，洞门终日细含风。","仙踪法界如堪拟，不是蓬壶即华嵩。"]},{"t":"乙酉岁除","f":"七言律诗","c":["细雨催春岁又除，县城灯火接郊墟。","百年到我强过半，万事于人总不如。","弊齿病深抛酒盏，安心法在卜山居。","东风若问新消息，多上蒲团少著书。"]},{"t":"丙戌元宵","f":"七言律诗","c":["上元灯火斗婵娟，满月轻风夜可怜。","人踏六鳌看海市，天连万炬候星躔。","楼台影里疑无地，歌吹声中合有缘。","管取一春多乐事，试从今夕卜丰年。"]},{"t":"次韵杨伯立春兴","f":"七言律诗","c":["江南地僻昼如年，春与閒人别有缘。","满径落花风阵阵，一犁新雨水田田。","池塘草长诗成梦，帘幕寒轻酒擅权。","四壁已空诸业尽，囊中刚剩买山钱。"]},{"t":"春雪","f":"七言律诗","c":["少年端策觐君王，记得春阴赋玉堂。","今日闭门风雪里，五更孤枕梦魂长。","薄田已就资生计，省事初营却老方。","尚有图书抛未得，教儿多种翠芸香。"]},{"t":"三月三日","f":"七言律诗","c":["一年一度春最好，三月三日烟雨中。","花外小车停过客，山阴褉事想遗风。","高楼正绕长江去，旧垒新看乳燕通。","桃李成蹊总相似，行人莫问午桥东。"]},{"t":"清明出行阡丘","f":"七言律诗","c":["病来廿日始胜冠，花柳清明满画阑。","二月光阴半晴雨，百年尘世几悲欢。","王孙芳草连天碧，燕子东风作阵寒。","万事山头一抔土，麒麟留得后人看。"]},{"t":"清明后一朝见桃花有感","f":"七言律诗","c":["玄都观里到应迟，前度刘郎鬓已丝。","燕语莺啼有何意，石桥流水至今疑。","一枝带雨比颜色，千树蒸霞劳梦思。","莫遣渔郎重问路，此中元少外人知。"]},{"t":"和郁潮州","f":"古风","c":["欲从东海望蓬莱，试上江头百尺台。","春色送将?独醉，好怀留取为君开。","诗成满砌翻红药，客去閒门长绿苔。","寄语桃花休折尽，刘郎应是不重来。"]},{"t":"五十生朝自寿","f":"七言律诗","c":["年行五十鬓犹青，浪许前身是岁星。","三刖尚存和氏璧，一区初筑子云亭。","人间好景中秋月，世上浮名五夜萤。","偏爱江山围故国，欲将非是问苍冥。"]},{"t":"十四日晚渡","f":"七言律诗","c":["团圆宝月漾空明，东去疑从不夜城。","风送潮头回别浦，水兼凉气弄新晴。","鹊填银汉桥初就，雁布瑶空阵乍成。","一棹中流双击楫，隔江时度紫箫声。"]},{"t":"饯顾东江宗伯于礼塔汇留题","f":"七言律诗","c":["千年地胜湖山绕，十月江寒树叶稀。","人向别时身是客，舟从行处岸如飞。","旧家池馆谁还念，落日风帆我自归。","天北天南俱逆旅，莫将去住与心违。"]},{"t":"山中岁暮得旨召还翰林兼许春坊供职志感一首","f":"七言律诗","c":["玉堂金马是重来，新诏青坊许并开。","岂有涓埃报明主，虚烦声价筑高台。","千年礼乐还周典，一代宸奎陋汉才。","直北长安天咫尺，红云无数绕三台。"]},{"t":"平望阻风期友人不值","f":"七言律诗","c":["渺渺碧波连白云，期君不见重思君。","妒花信急春如许，折柳情多日又曛。","山色水光馀此地，酒怀诗兴忆离群。","阳侯若借东风便，灯火楼船坐论文。"]},{"t":"嘉禾道中","f":"七言律诗","c":["画旗摇曳午风多，金鼓声繁水漫波。","春色二分看正好，国恩千载报如何。","江天路接心逾远，花柳村深气尚和。","童冠相随单袷具，康衢时听隔林歌。"]},{"t":"陈东祠堂","f":"七言律诗","c":["邮签初下云阳驿，国士有怀陈少阳。","人世自应馀感慨，东风元不管兴亡。","谁无一死宁须晚，事到千年更有光。","当日上书多辍报，至今遗恨说汪黄。"]},{"t":"维扬怀古","f":"七言律诗","c":["辇道芜烟江水流，游魂不载旧龙舟。","花开綵树春光永，火煖沈香瑞气浮。","绝域衣冠朝万国，拂云宫阙递千秋。","可怜惟有东征役，星散旌旗战骨裒。"]},{"t":"三月晦登羊山望下邳","f":"七言律诗","c":["一年春色此登临，入望遥山紫翠深。","二水帆樯风猎猎，半空楼阁昼阴阴。","何当开凿留形胜，不尽烟花自古今。","直北风云最高处，极天关塞筑黄金。"]},{"t":"东昌怀古","f":"七言律诗","c":["旌旗箫鼓画船过，风送长河渺渺波。","水报邮签朱夏晚，岸萦官柳绿云和。","聊城不下遗书在，泰岱乾封往事多。","七十二君空有箓，莫因秦汉问如何。"]},{"t":"端午自天津发舟入潞河与夏公谨给事晚坐","f":"七言律诗","c":["云际高城万国通，端阳佳节旅行中。","蒹葭碧映潮头月，杨柳阴依水面风。","天近北辰龙有气，地偏东海望无穷。","蒲尊箬黍依然在，楚调吴歌一笑同。"]},{"t":"七月七日以公事出城同林介立游广恩寺","f":"七言律诗","c":["年年七夕是秋期，残暑犹存感岁时。","未对天边新月偃，先贪林下午阴迟。","城鸦殿鹊红云绕，宿鸟鸣蝉碧树移。","两月都门尘扑面，偶同心赏一题诗。"]},{"t":"与顾未斋游西山过海子桥有作","f":"七言律诗","c":["新水平畴逐马蹄，白鸥黄鸟瀼东西。","风云天上身仍健，鸡犬淮南路欲迷。","倒影楼台含旭日，送春蒲柳拍长堤。","美人期我城阴曲，已有风花入品题。"]},{"t":"和未斋韵寄徽州郑珏山人","f":"七言律诗","c":["别后风烟去几重，思君多在鹤归松。","椷中尺素双双鲤，门外黄山六六峰。","花发春深行对酒，地偏日晚坐闻钟。","遥知十亩栖贤宅，却比丹青韵更浓。"]},{"t":"十七夜待月","f":"七言律诗","c":["紫阁黄扉切九霄，中秋待月第三宵。","天高易识龙文动，海近偏怜蜃气消。","十幅秋光障云母，一帘凉影弄冰绡。","欲凭弦管吹云散，忽有云间起凤箫。"]},{"t":"再出郊坛视牲王正十日早于华盖殿复命","f":"七言律诗","c":["九天风物丽春阳，来自南郊夜未央。","龙驭遥传香袅袅，鹓行时送佩锵锵。","步依玉砌雕阑绕，立近珠帘绣带长。","华盖极天悬法象，此身真到白云乡。"]},{"t":"赋得禁中早春","f":"七言律诗","c":["重重台殿护雕阑，欲动春声莺尚寒。","旗影渐随风力软，冻痕初映日华乾。","云依紫盖和香度，龙抱黄金带雨盘。","世道正同阳道长，午门朝下杂千官。"]},{"t":"南郊雪后斋宫候朝","f":"七言律诗","c":["雪片烟绡积渐和，紫坛瑶殿接星河。","风行法驾尘飔尽，云护真龙雨意多。","万乘旌旗环御跸，千官綵绣湿恩波。","扬雄老献河东赋，何似明堂九德歌。"]},{"t":"礼成下坛时天宇朗霁","f":"七言律诗","c":["星桥阁道倚层霄，一径天关紫翠遥。","合殿椒兰含瑞气，九重烟雾锁春宵。","万年天子调元化，四海诸侯奉大朝。","天意直教明主识，风云尽捲雪全消。"]},{"t":"重登子陵客星亭望钓台二首 其一","f":"七言律诗","c":["万古江山复此亭，天边自有少微星。","人生俯仰成今昔，客里悲欢付醉醒。","谁为汉家延国祚，欲从严濑问山灵。","浮云逝水秋风阔，极目遥空环翠屏。"]},{"t":"重登子陵客星亭望钓台二首 其二","f":"七言律诗","c":["烟霞冉冉去还迷，紫翠重重高复低。","双柱插天擎日月，一溪流水隔东西。","骚人道路频回首，客子光阴觅旧题。","怅望高风千仞外，敢将容易事攀跻。"]},{"t":"兰溪易舟愈小而北望愈远","f":"七言律诗","c":["山峰叠叠水潭潭，欲断还开去始谙。","净照波光深见石，远分秋色半成岚。","梦魂总不离天上，身世虚怜是斗南。","买得溪船如一叶，茶烟频飏酒微酣。"]},{"t":"自怀玉驿复行舟","f":"七言律诗","c":["行尽山程复水程，水南山径更须行。","攀高渐识浮云薄，度险频惊怪石轻。","到处一身真逆旅，传来满耳总虚名。","阴晴未定秋将半，忽听松声是雨声。"]},{"t":"鹅湖晓发","f":"七言律诗","c":["稻田迤逦水潺湲，不待黄粱已度关。","去路每看青嶂合，穿林时揽白云还。","秋风午日炎凉里，牧笛樵歌楚粤间。","惆怅平生最奇绝，未应向晚过千山。"]},{"t":"游武夷二首 其一","f":"七言律诗","c":["武夷宫前九曲溪，好峰多在夕阳西。","仙人飞度无行径，过客跻攀有杖藜。","草树阴阴连碧落，风烟袅袅引丹梯。","相传亦是秦人隐，何必桃源路始迷。"]},{"t":"游武夷二首 其二","f":"七言律诗","c":["日日溪头风日清，棹歌声里镜中行。","千岩万壑不知处，芳草幽花苦问名。","照影碧潭怜我老，分秋华月向谁明。","山川如画人如玉，望阙怀乡无限情。"]},{"t":"九月朔饯别过水南","f":"七言律诗","c":["年年席上看图画，秋日人从画里行。","夹道古松飞盖迥，漫滩奇石綵船轻。","依山别馆云封户，入市流泉竹绕城。","回首夕阳无限好，紫青如绣五云明。"]},{"t":"十月十日雨","f":"七言律诗","c":["南州雨意万山深，毒雾蛮烟半月阴。","细草公庭秋淅淅，隔花宫漏夜沈沈。","溪流破白添新涨，云岫拖青失旧林。","静倚客窗听不厌，乾坤随处望为霖。"]},{"t":"雨中发玉山","f":"七言律诗","c":["岁晚烟云酿薄寒，好山正向雨中看。","断桥流水横渔艇，要路丰泥没马鞍。","初向玉山迎敕使，远从闽岭望长安。","北来南去年光里，却恐卢生梦未阑。"]},{"t":"过草萍","f":"七言律诗","c":["山作重围天共低，一滩分水浙东西。","云边野菜挑冬笋，客里行厨趁午鸡。","鹤背还沾瀑布雨，马蹄偏恋锦障泥。","胜游若许开晴照，为借仙人一杖藜。"]},{"t":"桐江","f":"七言律诗","c":["北风瑟瑟滩悠悠，行尽桐江兴转幽。","水西半天堕红日，溪南诸峰偶白头。","严陵自是高隐地，钱塘从古帝王州。","海云不断三山近，时有青红起蜃楼。"]},{"t":"春日有怀王天宇嘉定","f":"七言律诗","c":["美人秖隔淞江水，不待秋风首重回。","今日吴公居第一，少年贾傅最多才。","遥怜细雨催春到，忽忆桃花对酒开。","病骨几时堪束带，紫扉青琐共金台。"]},{"t":"清明前一日过毗陵","f":"七言律诗","c":["老去逢春春更妍，杏花开烂柳含烟。","风旂金鼓频过寺，石岸楼台远接天。","潮信有期通大海，赏心如昨换流年。","禁烟时节江南路，画里山川行画船。"]},{"t":"庚寅三月三日渡江","f":"七言律诗","c":["明岁行年五十五，今晨渡江三月三。","鸥盟鹭渚他无恙，鹏海龙沙我所谙。","北固山前帆欲满，东风阵里酒微酣。","楼船箫鼓旌旗绕，黄纸功名老尚堪。"]},{"t":"宿州道中","f":"七言律诗","c":["水郭山村不计程，淮阳春晚更多情。","灵风常傍征旂绕，宿雨新添野潦明。","麦叶青青初覆雉，柳条落落未藏莺。","风雩亦是寻常事，陌上沙头尽日行。"]},{"t":"憩驿亭昼梦","f":"七言律诗","c":["蕉鹿何心得失间，如何连夜梦家山。","药栏定为游人遍，水阁唯应送客关。","春日欲晴常带雨，客途虽好不如还。","少年最爱河东问，抽笔浑惭鬓已斑。"]},{"t":"睢阳礼月","f":"七言律诗","c":["金鼓声繁夜向阑，叩天无计路漫漫。","埋将桂树三千丈，失却姮娥十二阑。","后羿弯弧空躩铄，玉川流涕正汍澜。","由来天上成亏事，付与人间仔细看。"]},{"t":"行经隋堤有感","f":"七言律诗","c":["端委犹堪致太平，龙舟锦缆竟何成。","空馀细水缘堤曲，别有垂杨带晚晴。","社燕归来如有恨，閒花开遍不知名。","行人谁管兴亡事，但说扬州接汴京。"]},{"t":"自清华西行村落间殊胜平畴流水果园竹径骤作乡思","f":"七言律诗","c":["燕麦青青柿叶肥，江南回首正依依。","千竿新竹消苍雪，一带遥山深翠微。","閒任野禽啼樾坞，细分流水绕柴扉。","那知身是乘骢客，疑向花前跨鹤归。"]},{"t":"净果寺晚眺","f":"七言律诗","c":["权店驿前山晚晴，天留高赏待西征。","北来形胜重关紫，春去莺花几树明。","风物未缘怀故土，文章终恐是虚名。","纡从一径过僧寺，红药翻阶忆五城。"]},{"t":"晓发权店行两山间流泉耕牧渐触见闻","f":"七言律诗","c":["山花红映石泉流，初见牛羊散古丘。","秦晋河山俱重镇，唐虞风土此中州。","彫残极目知生计，慷慨何能与国谋。","头白官僚半文字，东风又上皂貂裘。"]},{"t":"四月晦日盂县试诸生","f":"七言律诗","c":["围棘森森翠幄重，清和时候日高舂。","鱼龙队里波涛阔，桃李阴中雨露浓。","未为骊黄妨骏马，先从拱把养长松。","风传笔阵春蚕细，绕郭青山锁万峰。"]},{"t":"自盂县度石梯岭","f":"七言律诗","c":["绝塞风多四望宽，始知天上不胜寒。","依稀步入羊群化，次第行随鸟背盘。","扑面榆钱迎栈阁，染衣山黛落征鞍。","关门去雁无消息，满纸书成欲寄难。"]},{"t":"忻州试院雨中阅卷","f":"七言律诗","c":["江南五月黄梅雨，带雨滋花向晋阳。","映空游丝湿欲堕，赴壑细渠流未长。","重檐淅淅杂午漏，画寝冉冉凝清香。","须女为霖佐明主，莫将小技赋襄王。"]},{"t":"五月十八日代州筹边堂同陈宪副汝正大阅诸生因赠汝正","f":"七言律诗","c":["白马翩翩綵鹤开，牙旗行帐绕层台。","一时得共关山胜，他日须收将相才。","凤阁龙楼俱咫尺，瘴烟蛮雨乍归来。","君侯亦是三湘客，莫漫凌云赋楚哀。"]},{"t":"繁峙率文武诸生较射","f":"七言律诗","c":["沙融草浅绕青山，冠序童年各就班。","参合地承鱼丽阵，崔嵬天险雁门关。","遥闻白羽鸣风调，时向乌号抱月弯。","金马云台俱不薄，文章功业古人间。"]},{"t":"南峪雨后取道上五台","f":"七言律诗","c":["六月萧然似晚秋，登高重整木绵裘。","即看满涧泉初出，知是前岩雨乍收。","碧嶂旋随孤鸟没，白云常傍古松留。","幽芳一路无人采，何处三山更十洲。"]},{"t":"入五台","f":"七言律诗","c":["山水情多不自由，白头终作五台游。","万重云树高低出，千里滹沱背面流。","绝顶只疑天北极，朝阳初见海东头。","共传此是清凉地，为洗烦心尽日留。"]},{"t":"游五台","f":"七言律诗","c":["五云常覆五台端，天近清都特地寒。","涧道千年冰未化，林梢一夜雨初乾。","黄河紫塞依依见，碧殿朱楼面面看。","万壑千岩青未了，更从高处望长安。"]},{"t":"宿显通寺","f":"七言律诗","c":["一榻空斋卧白云，青灯微雨夜初分。","无缘十日惭凡骨，有梦三台绕圣君。","别院鸡催山月吐，回廊鱼咽涧风闻。","青山亦是人间世，自觉悠然隔世纷。"]},{"t":"竹林寺避雨","f":"七言律诗","c":["十里肩舆石磴深，禅房潇洒乱峰阴。","岩花笑里饶佳色，山鸟倦馀怀好音。","下界风雷喧众壑，上方钟鼓出长林。","苍生正有为霖望，惭愧西来冒雨心。"]},{"t":"竹林拟宿","f":"七言律诗","c":["未为长歌行路难，青山最爱雨中看。","图书暂许淹尘榻，蔬蕨先教具午餐。","碧树洗空千涧出，白云封满万松寒。","天留再宿清凉境，明日溪南十八盘。"]},{"t":"清凉石","f":"七言律诗","c":["炙手熏心事已多，晓凉来抚石盘陀。","不争可受千人坐，无事应须百遍过。","初日射林光历乱，懒云将雨湿嵯峨。","夜深或有骑牛到，堪和南山扣角歌。"]},{"t":"七月十一日雨后东巡过鸣谦驿","f":"七言律诗","c":["客居何似隐居閒，城里不如城外山。","涧水独澄吟骨瘦，秋风又上鬓毛斑。","黄花信早高低路，白雁霜前紫翠关。","爱杀无心云一片，随风飞去复飞还。"]},{"t":"廿日发晋定","f":"七言律诗","c":["秋风七月度榆关，秋色千岩雨后閒。","不向此中添白发，只疑无地着青山。","补天人远留遗事，背水功成合早还。","多少高怀付长啸，兴亡元自落人间。"]},{"t":"九月将望始对菊","f":"七言律诗","c":["遥怜佳节过重阳，叠叠青山近短墙。","忽见黄花和我瘦，不知白日为谁忙。","买栽自叹居无地，欲插先怜鬓有霜。","携向小斋风露背，捲帘邀日伴秋光。"]},{"t":"分司院前植蓼雨后着花嫣然感秋怀土","f":"七言律诗","c":["我家本住江湖上，独客远怜山谷中。","忽见庭花红带雨，恍疑浦树碧含风。","此身去住浑无赖，随地寒暄自不同。","试问桑榆能几许，长途南北又西东。"]},{"t":"十二月重渡江东归用前三字韵","f":"七言律诗","c":["江头十二月十二，忆昨开帆三月三。","山川南北俱经遍，气候寒暄已饱谙。","月色下澄江更远，潮声惊破梦初酣。","君恩难报亲庐近，国事乡心总未堪。"]},{"t":"辛夘三月三日再叠前韵三首 其一","f":"七言律诗","c":["百年过半五十五，一春最好三月三。","茂林修竹事可续，随柳傍花予素谙。","暖爱游蜂衙正放，晴看行蚁战方酣。","士师何止三宜黜，中散虚传七不堪。"]},{"t":"辛夘三月三日再叠前韵三首 其二","f":"七言律诗","c":["陶令閒居爱重九，故园今日是重三。","一觞一咏风犹在，江外江头路总谙。","地僻仙家无岁历，花开国色带朝酣。","黄鹂紫燕浑相识，旧垒新枝事事堪。"]},{"t":"辛夘三月三日再叠前韵三首 其三","f":"七言律诗","c":["江天十日晴无一，花市残时月过三。","卖困送穷方不验，品茶斗草事多谙。","新资恰有诗千首，旧恨惟凭酒半酣。","不是广平心似铁，粉匀香沁更谁堪。"]},{"t":"八月九日月夜泊舟凤凰桥","f":"七言律诗","c":["凤凰山下凤凰桥，与客移舟自海潮。","中半秋光明月小，参差山势碧波遥。","四时得意真行乐，一榻高眠慰久要。","为问向阳多少地，种梧栽竹老清朝。"]},{"t":"过北簳观旧题自西岭步归","f":"七言律诗","c":["南山初下北山湄，惭愧山灵旧有移。","看种松篁如昨日，来惊霜露已多时。","漫游最好逢僧寺，阅世无过与客棋。","两腋天风送归袖，野花开遍棘成篱。"]},{"t":"舟去速遂罢入寺从塔院西畔泛青龙故江","f":"七言律诗","c":["落日遥牵锦缆齐，青龙江水故通西。","采蓝斸药多成市，飏网投竿尽绕堤。","一曲吴歌犹欸乃，千年禹迹半萋迷。","胜游回首惊秋鬓，怕向纱笼觅旧题。"]},{"t":"登凤凰山绝顶","f":"七言律诗","c":["南山佳气郁嵯峨，特地扁舟百里过。","缓步暗扶筋力倦，高登偏觉海天多。","闺中素练衣初具，天上风云气向和。","却立许时惭大手，磨崖欲写中兴歌。"]},{"t":"晨登厍公山","f":"七言律诗","c":["丹凤衔书下九霄，分明形胜见山椒。","先秋古树苍黄出，映日高峰紫翠摇。","税地浇花人未老，买船载酒路非遥。","经行更爱清溪曲，若个淮南苦见招。"]},{"t":"宿布金寺","f":"七言律诗","c":["五年荏苒重过寺，一夜空明独倚楼。","水亦何缘俱到海，心如无碍总忘鸥。","细寻往事和头白，多感新凉与病瘳。","安用远公要靖节，暂随蝴蝶化庄周。"]},{"t":"将抵关桥迎涨泊舟北岸待月","f":"七言律诗","c":["簇簇江云妒月明，悠悠沙岸海潮生。","渔归别浦风无力，人语孤村夜有声。","颇费推移为去住，尚劳恩怨是阴晴。","兹游逐水留三宿，别近翻多恋别情。"]},{"t":"连夜月色甚佳浦上尤胜西渡有作","f":"七言律诗","c":["昨宵对月思东渡，今夕月明西渡江。","红灯照渔隐数点，白鸟傍人惊一双。","恍疑混沌太古色，忽闻欸乃俚人腔。","一天星斗浸上下，时有波影摇船窗。"]},{"t":"渡江","f":"七言律诗","c":["本有江南水竹情，谬持华藻谒承明。","四年五向金焦渡，万里重为晋冀行。","臣罪每蒙明主贳，吏文先为故人惊。","风前又听沧浪起，两鬓霜寒一棹轻。"]},{"t":"维扬哭蔡石冈侍郎","f":"七言律诗","c":["鱼鸟犹疑水上军，河州重到不堪闻。","才名满世谁当忌，膏馥宜人秪自焚。","已向盖棺须论定，聊从破箧觅遗文。","西门总是伤心地，泪迸羊昙湿暮云。"]},{"t":"怀寄乔白岩太宰","f":"七言律诗","c":["吴山楚水谢行舟，望入榆关路转悠。","聊向岁寒占纬候，旋看春色动林丘。","相逢先问尚书履，愿见浑胜万户侯。","忆昨过江劳物色，是谁同载上扬州。"]},{"t":"宿迁晓发","f":"七言律诗","c":["重裘絮帽北行装，地炕煤炉候晓光。","十里鸡声常带月，五更蝶梦半还乡。","关河远近俱萧索，岐路东西各渺茫。","不怕孤危缘历惯，太行山脊更羊肠。"]},{"t":"雪后登平潭驿楼","f":"七言律诗","c":["面面峰峦一水通，危楼正倚夕阳东。","自将短发明残雪，閒看孤云送断鸿。","北斗地高天更远，巴人心苦调逾工。","南冠岁晚催归客，合让元龙卧此中。"]},{"t":"除日平潭道中","f":"七言律诗","c":["阳和蔼蔼度郊墟，凤历拈来岁又除。","万事可齐终有尽，一生能几苦求馀。","茅茨人静鸡声早，关塞天高雁影疏。","欲寄封书东海上，药阑花坞近何如。"]},{"t":"吕左丞书院","f":"七言律诗","c":["穹林古寺有残僧，指点前朝吕左丞。","石洞岁深苔黯黯，砺墙春早雪层层。","旧藏万卷龙常护，欲寄双椷雁可凭。","星斗夜阑云雾里，州人遥见读书灯。"]},{"t":"孙杰太守高岭书院","f":"七言律诗","c":["石梯随步与云升，又是青山第几层。","望到只疑天更近，兴来唯有斗堪凭。","岭头日月开昏晓，洞口诗书感废兴。","一自文翁归蜀后，手扶风教有谁能。"]},{"t":"孙太守兄弟陪游郤家瀑","f":"七言律诗","c":["水帘瀑布见应多，叠嶂层峦奈此何。","春向雪中翻玉乳，人从天上挽银河。","久蒙郤姓宜攀桂，未必王家胜浴鹅。","好事主人金玉侣，远携名酒沸清歌。"]},{"t":"南里杨用之宪副朝回遂归共游城南嘉山","f":"七言律诗","c":["二月二日榆关春，流杯犹在迹俱陈。","溪风扑面知新候，野老传名爱古人。","山外有山青不断，客中逢客意偏亲。","桑田沧海寻常事，共惜尊前万里身。"]},{"t":"嘉山次韵郤文渊知州","f":"七言律诗","c":["寻山问水约同行，嫩柳初匀花欲明。","正及人间修褉节，更堪林外踏歌声。","病严酒戒三分量，清爱茶烟一缕萦。","韦杜去天元尺五，不辞归路暮云平。"]},{"t":"次韵再答郤文渊","f":"七言律诗","c":["久客宁忘地主贤，每劳移步出花前。","川围风日春难老，山抱楼台月又圆。","燕子暖泥低掠水，王孙芳草远连天。","行藏未定频看镜，独羡君归及壮年。"]},{"t":"送王宾峰赴陕西太仆少卿","f":"七言律诗","c":["初从白豸换金绯，遥拜彤墀达紫微。","外省中台无别署，求才买骏本同机。","秦关百二沙场迥，渭苑三千塞草肥。","龙种不缘常在野，云车留取待骖騑。"]},{"t":"赠高如斋少参巡云中","f":"七言律诗","c":["北门锁钥紫薇厅，新转官阶旧典刑。","鼓角令严边月晓，旌旗春暖塞云青。","台悬骏骨千金重，身作长城万里宁。","会见极天歌帝力，聊将风力扫王庭。"]},{"t":"柏井","f":"七言律诗","c":["东下重关紫翠深，好山如戟送归心。","瑶空日月双行蚁，夏木园林一变禽。","旗画半销岚气湿，边烽高结阵云阴。","前身或是乘槎客，碧汉银河取次寻。"]},{"t":"度井陉","f":"七言律诗","c":["石溪磊磊水环堤，唤起鸡声更马蹄。","三晋山川分左右，一陉尘土逐高低。","樾阴逗日连村动，麦秀含风掠地齐。","近北韶华终觉晚，尚携春服事攀跻。"]},{"t":"题两江号","f":"七言律诗","c":["长江西来双白龙，接天波浪春溶溶。","群鸥弄影舞欲下，独鹤转翅鸣相从。","雨后莺花看不尽，烟中舟楫望犹重。","主人不是鸱夷子，一曲沧浪十二峰。"]},{"t":"五月廿七日雨后过山居观屏间所留橘实更丰肥而色回葱茜诘旦南邻致白菊一本三花灿然皆异也赋诗纪之","f":"七言律诗","c":["菊花开早橘收迟，硕果幽芳又一时。","未用千头当万户，只愁无酒负新诗。","薰风五月黄金颗，畏日南邻白雪篱。","欲起三家问书法，春秋何例合修辞。"]},{"t":"雨后","f":"七言律诗","c":["雨送微凉月向圆，江楼独倚早秋天。","梧桐自解知时令，牛女何心识岁年。","近水夜云常结绮，含风海气半为烟。","倦来欲展南窗卧，宋玉悲哀是偶然。"]},{"t":"和张赞卿喜雪","f":"七言律诗","c":["雪满琳居小洞天，阳春一曲为谁传。","云低百尺阑干外，寒在半空楼阁边。","柳絮梨花俱不俗，瑶台玉署本通仙。","洞庭新水东风里，会送江湖万斛船。"]},{"t":"癸巳春日崔东洲蒋东晓陆体斋诸同寅作湖山之行","f":"七言律诗","c":["早春风日未全和，十里湖堤小队过。","歌舞楼台聊复尔，兴亡今日竟如何。","三竿日影山中寺，千树梅花水上坡。","面面紫青看不厌，好峰偏向夕阳多。"]},{"t":"寄郑思斋侍御罢官","f":"七言律诗","c":["百年何处无风雨，试问行人归未归。","画里山川看亦险，人间岐路事多违。","海门有影龙方战，桑土何心鸟倦飞。","最好中流千尺浪，不曾摇折钓鱼矶。"]},{"t":"德清溪南山水","f":"七言律诗","c":["连朝积雨喜新晴，渡水登山取次行。","南斗星辰奠吴越，东风烟浪接蓬瀛。","半生酒盏元无分，二月花枝太有情。","回首好山千万叠，青云长傍涧松明。"]},{"t":"嵊县早发沿涉新昌道中","f":"七言律诗","c":["沙明水浅映疏星，十里春寒护短亭。","地僻稀闻行客早，日高初见远山青。","羊肠鸟背寻常事，问竹看花次第经。","一任午风吹不断，薄罗衣袂近苍溟。"]},{"t":"经天姥","f":"七言律诗","c":["天姥峰头云日开，欲临东海望蓬莱。","不辞谢客登山屐，远愧孙郎作赋才。","秀色南来连五岭，星文高处接三台。","何人更有凌空手，为筑黄金万里台。"]},{"t":"天台东入宁海","f":"七言律诗","c":["侵晨起踏天台路，雨意微蒸海上霞。","严卫共传天使节，靘深疑到地仙家。","千盘云外羊肠坂，几树山头谢豹花。","欲问当年刘阮事，人间红日又西斜。"]},{"t":"宁海北归","f":"七言律诗","c":["海城风物送归程，一段春游画不成。","山色有无分近远，岭云浓淡识阴晴。","青浮岛屿鲸波立，绿暗松杉鸟道横。","欲采柔芳寄相忆，好花开遍不知名。"]},{"t":"桐江舟行沿月","f":"七言律诗","c":["锦帆明月舵楼风，逝水澄鲜复映空。","万里鹤归迷近远，一溪人语隔西东。","广寒金粟秋香动，碧落银槎海气通。","漫向桐江论往事，客星元是钓鱼翁。"]},{"t":"瑞虹","f":"七言律诗","c":["江湖住傍青山好，舟楫来惊白浪多。","两岸菰蒲回鹳鹤，中流风雨长蛟鼍。","书随驿使心先寄，秋逐年光鬓已皤。","一曲沧浪多少意，况堪重听楚声歌。"]},{"t":"白鹿洞游眺","f":"七言律诗","c":["亭台高下恣登临，泉石松篁处处寻。","一径莓苔无俗辙，四时弦诵有清音。","人逢胜境功名薄，山到斜阳紫翠深。","五老不随云雨变，卜邻初见古人心。"]},{"t":"伏日自南康郡城登观澜阁","f":"七言律诗","c":["匡庐彭蠡气争雄，一段閒云万顷风。","五老地高俱拱北，九江天远总朝东。","秋期先逐乡心到，眼界聊随野望空。","更向青霄问明月，画阑人在水晶宫。"]},{"t":"十二月朔雪夜宿宣风馆次壁间韵","f":"七言律诗","c":["岁晚溪流冻有痕，岭头云日瘴犹浑。","向来萍实千年事，一去梅花第几村。","高鸟过林惊积雪，长亭催客易黄昏。","深惭未遂还吴计，独谱离骚招楚魂。"]},{"t":"二月廿二日冒雨发天长断桥乱水经涉甚险","f":"七言律诗","c":["软舆笼雨破春寒，烟水江淮路百盘。","桥断正怜羸马度，云深疑有老龙蟠。","行边白发和愁长，望里青山带湿看。","为问阴晴成底事，鹪鹩终羡一枝安。"]},{"t":"虹县晓发","f":"七言律诗","c":["拂曙星河拥使旌，隋堤花柳报清明。","人家烟火寒犹禁，客子衣裳暖渐轻。","夹岸露华添细水，浮空春色抱孤城。","东风满地皆芳草，一为多情尽日行。"]},{"t":"南陵王望云楼","f":"七言律诗","c":["五色云中本帝州，梁园更起望云楼。","太行西去天逾近，华表归来鹤暂留。","贝阙珠宫元渺渺，白衣苍狗自悠悠。","凭将一掬思亲泪，洒向朱阑最上头。"]},{"t":"洛阳书怀","f":"七言律诗","c":["河山天地此中州，千古风云拥上游。","王气不消天正远，元功犹在水常流。","几时荆棘铜驼巷，何处隋唐五凤楼。","六十头颅身万里，香山洛社愧前修。"]},{"t":"登华山至青坪","f":"七言律诗","c":["群玉峰头铁锁寒，周秦遗事共漫漫。","山从拔地五千仞，路向穿云十八盘。","上界楼台悬日月，下方风雨长波澜。","乾坤不博蒙头睡，一借神仙蜕骨看。"]},{"t":"栈道寄康德涵修撰","f":"七言律诗","c":["当年馆阁重离群，渭北过逢正暮云。","髯鬓共惊俱长大，寒暄无处不慇勤。","人皆欲杀偏怜我，老更何求敢负君。","一上陈仓云路永，蜀川歌调况堪闻。"]},{"t":"利路纪雨","f":"七言律诗","c":["欹枕无眠万里心，济时须仗傅岩霖。","三更忽送千山雨，五月难逢半日阴。","禾黍垄头新水涨，芭蕉声里大江深。","起来欲着蓑衣舞，细听窗前断续音。"]},{"t":"八月一日出郊秋色佳甚","f":"七言律诗","c":["远山流水晓云和，松有盘陀竹有坡。","两月簿书堆积满，千重岩壑梦魂多。","莼丝渐逐秋心长，雁信凭将旅恨过。","一出郊关风景别，桃源未敢问如何。"]},{"t":"十月六日晚登大安门楼望雪山","f":"七言律诗","c":["岁晚天空旭日晴，雪山当面始分明。","登临到我元无约，风景于人似有情。","楼阁欲从千里见，云烟谁借一朝清。","不知地位高多少，瑶树琪花近五城。"]},{"t":"诘朝侵晓再出西城门","f":"七言律诗","c":["曙色喧阗满市楼，穿云十里度林丘。","汉家事业三分国，禹贡山川九等州。","村落人烟风不散，园田生计岁应收。","茂林修竹浑如许，安得兰亭擅昔游。"]},{"t":"微雨出城赴南泉宪长草堂之招偶述","f":"七言律诗","c":["冲云重作草堂游，庭树青黄湿未收。","子美有灵终恋蜀，孔明无计为安刘。","何须往事千年恨，自爱长江万里流。","老去诸缘看渐尽，每逢知己胜封侯。"]},{"t":"仲冬望东郊送邹和峰侍御","f":"七言律诗","c":["冉冉山云压树低，村村茅屋带沙溪。","征旗满路风初劲，尊酒长亭日又西。","柏府独传乌夜曲，花骢偏恋锦障泥。","隔林好鸟知人意，更向离筵尽力啼。"]},{"t":"至后四日偕郑少参谒孔明祠","f":"七言律诗","c":["丞相祠堂特地过，仲冬风日更柔和。","时随运去终应尔，事与心违独柰何。","庭树不凋栖燕雀，江流有恨泣蛟鼍。","唐碑汉署青山下，过客留题积渐多。"]},{"t":"过万里桥","f":"七言律诗","c":["愁闻万里桥南路，回首关河万里多。","入望煖云山破白，长年腊月水层波。","石阑且逐行行度，蜀道时听款款歌。","此去应知东到海，欲凭双鲤问如何。"]},{"t":"谒诸葛庙","f":"七言律诗","c":["武侯祠庙已千年，过客何心尽可怜。","百里营留鸣鼓后，两函表上出师前。","江流不转馀滩石，峡锁犹闻哭杜鹃。","自信英雄终有气，风云常护旧山川。"]},{"t":"送客过昭觉寺","f":"七言律诗","c":["霜日江云杳霭间，聊凭酒力驻颓颜。","一冬天气常嫌热，几度郊行暂借閒。","世上无情惟白发，人间有福是青山。","山僧更住青山里，翻罢楞严独闭关。"]},{"t":"暇日谒潜溪宋先生祠","f":"七言律诗","c":["华国文章报国身，青山万叠未归人。","高皇最爱才无敌，学士应誇酒有神。","不向东方恋桑梓，至今南斗避星辰。","扬雄杜甫俱邻傍，落日祠堂采涧蘋。"]},{"t":"少宰学士温托斋赴召成都邵守作三诗送之予览其辞甚丽和韵一首","f":"七言律诗","c":["玉堂金马退朝回，常忆班行一字开。","东阁共推萧相入，西川独数子云才。","瞻云已识亲帏近，捧日频劳御札催。","六月扶摇真一息，十年魂梦绕三台。"]},{"t":"将过新都秋晓同卫?川东行","f":"七言律诗","c":["昭觉钟声隔幔闻，笋舆十里度秋云。","山家岁计占农事，客子年光付吏文。","岐路软红随马去，远山晴翠过江分。","联珠倚玉多佳致，此日同行赖有君。"]},{"t":"锦江","f":"七言律诗","c":["浪花如织远黏天，濯锦溪边胜可怜。","五色文章初日里，一川绮縠午风前。","东流到海通蓬岛，南浦逢春送酒船。","若问乘槎霄汉事，支机抱得已多年。"]},{"t":"冬日同?川过范浣溪","f":"七言律诗","c":["曲径疏篱路欲迷，草堂岁晚浣花溪。","槐柯倒影醒残梦，竹汗留青满旧题。","暇日偶从南郭隐，好山多在小窗西。","高人未用逃名迹，江上天空北斗低。"]},{"t":"发新津风日甚佳有述","f":"七言律诗","c":["江山偏觉此行多，爱听巴音入棹歌。","锦树微茫连岸脚，画船掀舞出盘涡。","山云欲起常迎日，水鸟惊飞不离波。","为客十年劳胜赏，朝天万里又经过。"]},{"t":"与余方池草池兄弟游三岩","f":"七言律诗","c":["山下三岩逐二难，春风初试杏花寒。","人情倦去方惊老，江面东来渐觉宽。","一代交游论出处，百年身世杂悲欢。","浮云本是山中事，欲为苍生起谢安。"]},{"t":"留题凌云","f":"七言律诗","c":["凌云殿阁倚江开，三面江流抱石台。","远浪贴天成绮縠，旧题多日长莓苔。","下临风雨空三蜀，高处星辰接上台。","一为赏心留胜槩，还看秀色产奇才。"]},{"t":"兑阳书楼","f":"七言律诗","c":["面山花竹背山楼，合着元龙最上头。","云气阴晴常不定，江声回合正东流。","九关清梦通霄汉，八月仙槎贯斗牛。","欲赋兑阳形胜里，山川元是汉嘉州。"]},{"t":"二月五日发长寿","f":"七言律诗","c":["只只楼船面面山，矶头石齿斗弯环。","滩声忽送蛟龙窟，云气常封虎豹关。","南去杂花浑烂熳，西来晴雪正潺湲。","棹歌风起旌旗动，时有渔歌互往还。"]},{"t":"春雨游岑公祠","f":"七言律诗","c":["石门泉窦境尤奇，紫晕苍痕雨更宜。","信有神仙住人世，何妨游宦向天涯。","盘崖一线通银汉，滴乳千年长玉芝。","流水高山俱望眼，柳条花萼系春思。"]},{"t":"廿六日雪后赴金太常南郊观礼有述","f":"七言律诗","c":["三级围环八柱擎，碧青浮动日华明。","万年礼乐归真主，一代彝章见大成。","天压周庐元咫尺，雪消驰道转澄清。","微臣将事依龙衮，试向瑶台最上行。"]},{"t":"仲冬晦过海印寺有述","f":"七言律诗","c":["万岁山阴海子桥，十年重到笑劳劳。","旧时风景依稀在，岁晚冰霜积渐高。","钟鼓连天涵日月，楼台倒影蘸波涛。","千重王气盘龙虎，常有红云覆赭袍。"]},{"t":"立春后一日午门宴罢有述","f":"七言律诗","c":["金殿彤楼白玉台，芳春风日暖初回。","千官簇拥雕盘细，万国趋陪綵仗开。","黄道正中当御座，碧空遥映入仙杯。","两阶拜舞俱沾醉，已有欢声动蛰雷。"]},{"t":"丁酉除夜","f":"七言律诗","c":["十年除夕总天涯，帝里今宵鬓已华。","历尽苦心难报国，拨残新火倍思家。","凤楼缥缈回银汉，宫漏迢遥隔紫霞。","閒倚画屏清不寐，独将春信问梅花。"]},{"t":"岁暮旅馆灯花异常有作","f":"七言律诗","c":["雪封虚馆烛开花，乍吐红英晕紫霞。","四壁图书看照影，一行儿女念还家。","金莲恩重身难称，白玉堂高鬓有华。","应是明朝当献纳，坐听宫漏隔窗纱。"]},{"t":"介溪宗伯荣赐麟袍和甬川少宰韵","f":"七言律诗","c":["白玉阑前紫兽铺，黄金台下古燕都。","千年典礼开纶阁，万里风云护帝图。","藜影木天时战蚁，钟声长乐晓听凫。","由来此地文章海，杯视三江与五湖。"]},{"t":"送沈大华下第还","f":"七言律诗","c":["旧业长杨满箧閒，春风燕市买驴还。","轻尘鸟背频挥麈，曙月鸡声欲度关。","世味旋尝随路酒，乡心遥慰隔州山。","怜君无计能留住，草草诗成空厚颜。"]},{"t":"龟峰晚兴","f":"七言律诗","c":["度壑穿岩兴未遒，更从灯火数奇游。","风高八月寒先到，地僻千年事转幽。","碧涧每逢春涨合，丹崖疑共暮云稠。","平临北斗长安近，身在天南重倚楼。"]},{"t":"次韵白雁","f":"七言律诗","c":["波澄照影度潇湘，回雁峰高近帝乡。","星阵望穷云半没，雪翎风急字斜行。","芦花深处惊遥火，木叶催时护晓霜。","记得上林栖宿处，每因彤矢识君王。"]},{"t":"登太白楼","f":"七言律诗","c":["夜郎一去几千秋，尚有任城太白楼。","身后功名空自好，眼前汶泗只交流。","当年狂客心偏恋，近代风人谁与俦。","拍碎阑干呼不起，月明风细忆神游。"]},{"t":"赠别郑宜简","f":"七言律诗","c":["扁舟五月大江东，鲍管千年见古风。","天北天南三十载，听风听雨几宵同。","閒来只爱青山好，老去方知白发公。","我已倦游君作别，相思多在月明中。"]},{"t":"和介溪赏莲","f":"七言律诗","c":["雨气自天香冉冉，风光临水碧飔飔。","移来玉井仙人掌，开傍金波太液池。","本为怜芳衙散早，翻因解语酒行迟。","新欢旧赏年华里，倚遍阑干有所思。"]},{"t":"送张懋勉之赴新建县丞","f":"七言律诗","c":["云间文献旧名家，艺苑驰声几岁华。","新捧除书辞赤陛，满斟别酒对黄花。","东湖古庙馀尘榻，南浦疏帘捲落霞。","少府胜游还胜地，好将清誉遍天涯。"]},{"t":"送崔都尉奉使显陵","f":"七言律诗","c":["雪中送客重徘徊，白马银鞍画角哀。","云绕鼎湖龙卧起，月明辽海鹤归来。","金符玉节山陵使，戚畹侯封将相才。","万里皇图元咫尺，东风回首凤凰台。"]},{"t":"内丘大风尘","f":"七言律诗","c":["沙曲风尘冉冉高，行行偏念圣躬劳。","九天日月悬平野，万乘旌旗捲怒涛。","山势远随驯象辇，春光正满衮龙袍。","侍臣亦有扬雄赋，欲奏河东愧二毛。"]},{"t":"送黄甥标东归","f":"七言律诗","c":["送汝黄金台下路，西风多少渭阳情。","愁看世态如云变，须遣乡关似月评。","海内胜游吾欲倦，江东好事若为成。","过家上冢俱如礼，来趁鹏抟九万程。"]},{"t":"送魏佥都伯深镇汴","f":"七言律诗","c":["中丞玉节下承明，风动中州数十程。","乔岳一时瞻气象，长河万里为澄清。","旌旗号令新开府，藩省官僚古帝京。","若向周公旧台下，六符先候泰阶平。"]},{"t":"五月十三日下湾始入舟居","f":"七言律诗","c":["淡云微雨带青山，细柳新蒲水一湾。","人世百年真梦里，圣恩今日是生还。","来看海鹤迎风舞，坐爱江鸥尽日閒。","京国风尘能化白，临流偏诧鬓毛斑。"]},{"t":"和答陶南川兵侍","f":"七言律诗","c":["晓开画鹢带遥山，夜泊溪渔细柳湾。","鸿雁逢时知北乡，莼鲈有约待南还。","虚传海外千年药，且向人间一日閒。","寄语隔船陶士雅，故园新笋鹿胎斑。"]},{"t":"后乐堂家宴守岁","f":"七言律诗","c":["歌管声喧饯岁除，大江东下抱閒居。","夜筵椒酒元随量，春帖桃符手自书。","老去何妨髫鹤发，归来犹及馔鲈鱼。","十年万里风和雨，此夕团圞画不如。"]},{"t":"客从海上馈杜鹃花甚佳薄暮移灯照之有作","f":"七言律诗","c":["秾绿深红照夜明，自从西蜀识佳名。","年芳不隔关山道，胜事新添洛社盟。","高阁捲帘看不足，一春啼鸟恨难平。","阑干六曲催花信，芳草王孙空复情。"]},{"t":"壬寅中秋夜同姜明叔王元采玩月","f":"七言律诗","c":["蓬瀛东望月华圆，咫尺烟霄万里天。","屏翳驱云怜浩荡，铢衣和露斗婵娟。","良宵嘉会俱难得，天上人间各有缘。","十二阑干须遍倚，莫论风雨是何年。"]},{"t":"自潭山取道过玄墓","f":"七言律诗","c":["尽日湖山不厌多，画船初泊綵舆过。","路从鸟道冲黄叶，浪打渔矶湿绿蓑。","閒处风光岩壑占，望中天气水云和。","相逢莫问鸱夷事，爱听沧浪隔树歌。"]},{"t":"雨后对花和答沈叔明","f":"七言律诗","c":["三径归来春水生，送春初觉病魂轻。","名花旧种浑无恙，携酒频过倍有情。","十尺阑干围紫艳，一番风雨妒红英。","殷勤寄语怜芳客，尚保丹心向日倾。"]},{"t":"中秋后二夜与姜蓉塘诸友登楼","f":"七言律诗","c":["月到中秋分外清，共登江阁俯空明。","参差渔火遥通海，缥缈鸾笙欲近城。","满目星辰分上下，百年尘世半阴晴。","一樽且尽今宵醉，乡国宾朋倍有情。"]},{"t":"东轩春兴","f":"七言律诗","c":["笙歌院落养花天，六十年踰七十前。","坐隐尚馀经国手，卧游无藉买山钱。","江流东下饶鲑菜，风信南来有雁笺。","双鬓不嫌搔更短，老人心事爱随缘。"]},{"t":"初夏移舟天马山过嘉树林听僧道净弹琴","f":"七言律诗","c":["城阴水木夏初临，十里来过嘉树林。","乘兴不妨灵运屐，赏心先到颖师琴。","望中海日依微见，物外烟霞次第寻。","欲上前山最高处，扁舟应向五湖深。"]},{"t":"史泾西发","f":"七言律诗","c":["西去青山入望多，栋花风信水云和。","田家秧马黄梅雨，谷口渔榔白苧歌。","星馆宛如天上列，画船疑向镜中过。","人生合住江南老，何处沧浪与碧波。"]},{"t":"喜雨次答郑文峰正郎","f":"七言律诗","c":["使君本意为澄清，先遣仁声作雨声。","百里望馀青障合，三农舞破绿蓑轻。","贪看䆉稏行来湿，爱听芭蕉坐到明。","无数乡心与时事，每吟佳句候秋成。"]},{"t":"筑堤","f":"七言律诗","c":["海门东启护长堤，小筑江沙旧屋西。","十里芦花依岸转，一川月色向人低。","尽从鸥鸟忘机下，或有龙孙挟雨啼。","便拟种为桃李巷，春风无语自成蹊。"]},{"t":"甲辰元宵后二夜观市灯","f":"七言律诗","c":["好怀佳节是乡园，歌舞楼台开上元。","万里团圞春正月，千家灯火水西村。","太平有象瞻天阙，老大何心倚市门。","但愿年年同此夕，田蚕花竹长儿孙。"]},{"t":"有草类藜而干生其本多绿叶至末始敷为红紫经霜更绚烂可爱一名雁来红俗呼老少年山居小阁前倚阑一株尤茂密高可文馀病起过宿相对甚适偶成一律","f":"七言律诗","c":["老去谁能更少年，此来相对亦欣然。","人间白日无绳系，炉里金丹有诀传。","秋水芦花三亩宅，西风鹤唳五更天。","晓来霜重红于染，伴我梅花纸帐眠。"]},{"t":"初夏五首 其一","f":"五言绝句","c":["野旷孤亭迥，昼长花影迟。","蒹葭飞白鸟，杨柳啭黄鹂。"]},{"t":"初夏五首 其二","f":"五言绝句","c":["芍药花初谢，芭蕉叶已斜。","窗前一夜雨，浮绿涨文纱。"]},{"t":"初夏五首 其三","f":"五言绝句","c":["林日不到地，溪风常满船。","雨馀黄犊健，天际白鸥眠。"]},{"t":"初夏五首 其四","f":"五言绝句","c":["初日浮空动，微风刬地凉。","苧衣人尚怯，看竹过横塘。"]},{"t":"初夏五首 其五","f":"五言绝句","c":["细草缘层砌，幽禽语画梁。","好风排户入，吹散午时香。"]},{"t":"和安鸿渐登楼曲四首 其一","f":"五言绝句","c":["登楼览春晖，春晖可怜晚。","所思在天涯，欲往道里远。"]},{"t":"和安鸿渐登楼曲四首 其二","f":"五言绝句","c":["日夕倚楼望，行人归未归。","断魂与残梦，相逐雁南飞。"]},{"t":"和安鸿渐登楼曲四首 其三","f":"五言绝句","c":["雪后楼偏好，青山破白看。","客衣无奈薄，高处许多寒。"]},{"t":"和安鸿渐登楼曲四首 其四","f":"五言绝句","c":["楼头红粉妆，楼下紫骝马。","两处总相思，无言泪成把。"]},{"t":"与周适斋潮州过张龙山樊柳圃纳凉","f":"五言绝句","c":["明月谷阳水，长桥卧綵虹。","绿杨风不动，人在镜光中。"]},{"t":"我有江南屋","f":"五言绝句","c":["我有江南屋，春深草映门。","湘帘低不捲，宝鼎夜常温。"]},{"t":"西岩","f":"五言绝句","c":["我爱西岩好，桑乾绕帝城。","黄金台下骏，细柳月中营。"]},{"t":"西湖","f":"五言绝句","c":["夜气消残暑，天光浸晓星。","草青藏白鸟，波绿泛红菱。"]},{"t":"成晋驿庭槐繁阴戏为一绝","f":"五言绝句","c":["雨意将云白，山光隐树青。","总看行蚁梦，何日报鸡醒。"]},{"t":"暮至清源","f":"五言绝句","c":["积雪千峰白，层冰十尺强。","吴儿浑不解，只道为炎凉。"]},{"t":"疑冢","f":"五言绝句","c":["疑冢七十二，冢冢浑相似。","春风草又青，斜日牛羊里。"]},{"t":"辛丑归途中绝句八首 其一","f":"五言绝句","c":["高鸟依依没，长河淼淼流。","风尘随短鬓，去住任扁舟。"]},{"t":"辛丑归途中绝句八首 其二","f":"五言绝句","c":["弱柳风前转，新凉水际浮。","莼鲈如有待，归日正逢秋。"]},{"t":"辛丑归途中绝句八首 其三","f":"五言绝句","c":["村村喜麦黄，南风散初暑。","古岸绿阴中，行人自来去。"]},{"t":"辛丑归途中绝句八首 其四","f":"五言绝句","c":["日落山烟紫，林深暝色寒。","殷勤问前路，今夜宿新安。"]},{"t":"辛丑归途中绝句八首 其六","f":"五言绝句","c":["水色拖苍玉，槐阴堕绿云。","会心诗半属，得意酒微醺。"]},{"t":"辛丑归途中绝句八首 其七","f":"五言绝句","c":["目力耽书短，归心引路长。","深林喧鸟雀，斜日下牛羊。"]},{"t":"辛丑归途中绝句八首 其八","f":"五言绝句","c":["海月和潮上，风帆接画船。","故乡连夕梦，景物正依然。"]},{"t":"碧云寺","f":"五言绝句","c":["鸟道千盘迥，羊肠一径斜。","年年二三月，红杏碧桃花。"]},{"t":"过丛台","f":"五言绝句","c":["青山不改色，绿树有新姿。","昔人歌舞地，今见草离离。"]},{"t":"白槿","f":"五言绝句","c":["寻常红与紫，不及淡梳妆。","木槿篱边过，冰肌照拒霜。"]},{"t":"题小景二首 其一","f":"五言绝句","c":["箬叶舟能大，桃花水正新。","了知鱼有乐，袖手捲丝纶。"]},{"t":"题小景二首 其二","f":"五言绝句","c":["自爱看秋水，鸥閒我更閒。","蓼花洲渚里，随意弄潺湲。"]},{"t":"偶成","f":"五言绝句","c":["蓬莱波浪浅，汀洲杜若新。","暖云不作雨，閒杀钓鳌人。"]},{"t":"过淮阴","f":"古风","c":["故堞初惊雨歇，古祠高枕江流。","一抹霏微轻霭，片帆归去清秋。"]},{"t":"馆中","f":"七言绝句","c":["天上文章白玉堂，日华浮动郁金香。","词头封罢浑无事，独步花砖绕画廊。"]},{"t":"春阴送客即事","f":"七言绝句","c":["洞口桃花带女萝，不知春色几分过。","长驱白日红尘净，无数青山细雨多。"]},{"t":"和俞生暮春闺怨二首 其一","f":"七言绝句","c":["落花庭院草萋萋，雨鹳晴鸠各自啼。","倦绣一春长闭阁，忽将清梦过辽西。"]},{"t":"和俞生暮春闺怨二首 其二","f":"七言绝句","c":["鱼书欲寄转多情，锦字回文织不成。","落尽桃花飞燕子，一番风雨又清明。"]},{"t":"雨窗春兴四首 其一","f":"七言绝句","c":["芳草王孙湿未归，江南凭望转霏微。","疏疏密密俱成阵，留住杨花不肯飞。"]},{"t":"雨窗春兴四首 其二","f":"七言绝句","c":["听风听雨隔窗纱，爱弄潺湲试早茶。","更喜园丁报新事，鱼苗随水上平沙。"]},{"t":"雨窗春兴四首 其三","f":"七言绝句","c":["东风吹雨带龙腥，散作春声绕画屏。","人倚碧窗初避湿，芸香翻尽太玄经。"]},{"t":"雨窗春兴四首 其四","f":"七言绝句","c":["水心亭馆午风多，别有长条许客过。","无数落花红作阵，一篙新雨绿生波。"]},{"t":"漫兴六首 其一","f":"七言绝句","c":["东风成阵落红稀，日日溪头坐钓矶。","传语白鸥休避我，此心虽在已忘机。"]},{"t":"漫兴六首 其二","f":"七言绝句","c":["好山多在夕阳西，十曲清溪护石堤。","临水草堂春事晚，垆香惊堕燕衔泥。"]},{"t":"漫兴六首 其三","f":"七言绝句","c":["麦秀风行宿雨乾，苧罗衣袂薄生寒。","行藏欲问吾何似，尽日花开独倚阑。"]},{"t":"漫兴六首 其四","f":"七言绝句","c":["一卧林居独下帏，斩新时物换春衣。","丝丝细柳湾湾水，步到前村看雁飞。"]},{"t":"漫兴六首 其五","f":"七言绝句","c":["细柳新蒲已满溪，独寻春过小桥西。","奚囊佩得诗多少，欲寄相思手自题。"]},{"t":"漫兴六首 其六","f":"七言绝句","c":["满蓑风雨楚江天，钓得鲈鱼不卖钱。","十里溪桥趁归路，酒垆茅屋背花眠。"]},{"t":"书扇寄黄竹泉","f":"七言绝句","c":["溪堂山馆带江城，睡起催花雨正晴。","闻说閒人多乐事，臂鹰调马过清明。"]},{"t":"初夏即事二首 其一","f":"七言绝句","c":["水亭山馆绿阴肥，渐觉心情与世违。","午睡觉来香未烬，一群新燕学交飞。"]},{"t":"初夏即事二首 其二","f":"七言绝句","c":["云日阴阴水气凉，园林梅子半青黄。","农歌野唱元无谱，和合沧浪意自长。"]},{"t":"四月一日与客登梅亭","f":"七言绝句","c":["隔篱修竹隔溪花，浅映深围整复斜。","风外数声啼布谷，桔槔随处野人家。"]},{"t":"野航","f":"七言绝句","c":["身世元同不系舟，落花时节雨初收。","束书一枕江湖梦，流过江南杜若洲。"]},{"t":"泛舟","f":"七言绝句","c":["乾坤湖海总浮沤，风月图书共一舟。","向晚酒阑何处宿，芦花千顷近沙鸥。"]},{"t":"题画赠唐云东","f":"七言绝句","c":["扁舟只隔五湖东，红树青山万里通。","回首白云閒似我，却疑人在水晶宫。"]},{"t":"黄葵","f":"七言绝句","c":["碧纱高捲不胜情，晓梦初回半宿酲。","独有丹心待高日，小阑干外雨新晴。"]},{"t":"芙蓉","f":"七言绝句","c":["轻红浅绿殿芳晨，野水凌寒避软尘。","一曲楚辞渔子去，隔江愁杀采花人。"]},{"t":"登楼","f":"七言绝句","c":["小楼西下小西湖，淼淼烟波望转孤。","连日南风吹不歇，自添新水浸菖蒲。"]},{"t":"题蒲泉","f":"七言绝句","c":["移得通灵上品苗，云根新水暗通潮。","晓来绝胜金茎露，多少明珠湿未消。"]},{"t":"秋兴二首 其一","f":"七言绝句","c":["春光不比秋光好，料理精神只自知。","三月花时常卧病，晚凉日日有新诗。"]},{"t":"秋兴二首 其二","f":"七言绝句","c":["翠竹高梧一径斜，草堂开占白鸥沙。","秋来几阵催寒雨，报道芙蓉又着花。"]},{"t":"中秋节后黄葵作花满园甚富病起坐对二首 其一","f":"七言绝句","c":["满院晚葵秋日清，裹头强起坐前楹。","谁云欠却看花福，病里看花别有情。"]},{"t":"中秋节后黄葵作花满园甚富病起坐对二首 其二","f":"七言绝句","c":["翠节亭亭摇翠云，淡鹅黄剪薄罗纹。","向阳心事依然在，不共南风早策勋。"]},{"t":"秋江钓舟图","f":"七言绝句","c":["西风吹满荻芦花，酿作霜寒啼乱鸦。","买得钓船如屋里，只将秋水老南华。"]},{"t":"芙蓉","f":"七言绝句","c":["柳外风前生晚烟，一江秋水碧于天。","吴娃越女相思调，只爱银塘歌采莲。"]},{"t":"偶成","f":"七言绝句","c":["黄花翠竹动秋容，白日沧江有卧龙。","不是扁舟归去急，隔溪相约采芙蓉。"]},{"t":"重阳试笔","f":"七言绝句","c":["积水澄鲜云日凉，花芳开过木犀黄。","一年又是重阳节，閒倚西楼看雁行。"]},{"t":"漫兴五首 其一","f":"七言绝句","c":["花枝压雨粉墙偏，淡白轻红尽可怜。","独立晓风无限意，为谁零落为谁妍。"]},{"t":"漫兴五首 其二","f":"七言绝句","c":["月明吹彻紫鸾箫，火宿沉檀暖未消。","风送海潮来别浦，卖鱼人过竹西桥。"]},{"t":"漫兴五首 其三","f":"七言绝句","c":["溪亭山馆隔花分，更起江楼和水云。","八月木犀风雨信，遍抽缃帙散香芸。"]},{"t":"漫兴五首 其四","f":"七言绝句","c":["萧萧凉雨报秋衣，云影岚光锁翠微。","人在竹窗初睡起，坐看蛛网织危机。"]},{"t":"漫兴五首 其五","f":"七言绝句","c":["水芳无数长溪毛，秀色遥连翠浪高。","欲寄佳人无处所，漫依楚调注离骚。"]},{"t":"重阳后六日登镜光阁","f":"七言绝句","c":["下方僧梵杂鸣钟，身上危阑复几重。","微看太液波光净，更接蓬莱雨气浓。"]},{"t":"西轩凿壁作南窗打炕其下以供夜坐","f":"七言绝句","c":["地炉煤火夜如年，旋作南窗映月眠。","谁种庭中数竿竹，一时弄影到窗前。"]},{"t":"丙子除夕","f":"七言绝句","c":["一枝银烛坐更阑，小几摊书只自看。","家在江南四千里，有人今夜说长安。"]},{"t":"二月望晨起","f":"七言绝句","c":["修竹深溪带浅沙，隔篱初见小桃花。","东风最是无情物，却与人间管岁华。"]},{"t":"晓起","f":"七言绝句","c":["雨洗春容淡有姿，柳丝花雾共参差。","人家住在青山曲，无事朝来睡起迟。"]},{"t":"园居杂咏三首 其一","f":"七言绝句","c":["回廊曲曲面青山，身世悠悠蝶梦间。","半郭半村秋色里，听风听雨夜深还。"]},{"t":"园居杂咏三首 其二","f":"七言绝句","c":["竹阑干外石方塘，映月含风贮早凉。","乞得名花周匝种，为谁着意最怜芳。"]},{"t":"园居杂咏三首 其三","f":"七言绝句","c":["芙蓉洞口石坡陀，橘刺藤梢带女萝。","一夜好风吹雨过，晓来添起碧嵯峨。"]},{"t":"春日杂兴二十七首 其一","f":"七言绝句","c":["绿杨如线草如茵，紫竹肩舆白叠巾。","不是为春禁不得，老来心绪最怜春。"]},{"t":"春日杂兴二十七首 其二","f":"七言绝句","c":["山中春色二分强，次第开花到海棠。","风日一帘初病起，斜摊黄素写官方。"]},{"t":"春日杂兴二十七首 其三","f":"七言绝句","c":["临池草阁背山堂，乳燕泥融补画梁。","却按茶经试江水，自开阳羡阅旗枪。"]},{"t":"春日杂兴二十七首 其四","f":"七言绝句","c":["种成修竹倚云看，新筑方塘漾翠寒。","一夜落花风信急，隔溪吹折钓鱼竿。"]},{"t":"春日杂兴二十七首 其五","f":"七言绝句","c":["隔江楼阁郁岧峣，掩映繁花更柳条。","红日半窗春睡足，独携藤杖过溪桥。"]},{"t":"春日杂兴二十七首 其六","f":"七言绝句","c":["上临风雨下尘氛，一上层台思不群。","更爱草深成小坐，摩挲双眼看江云。"]},{"t":"春日杂兴二十七首 其七","f":"七言绝句","c":["重重帘幕护馀寒，拓得兰亭映日看。","颇觉近来诸念尽，偏于笔砚遣犹难。"]},{"t":"春日杂兴二十七首 其八","f":"七言绝句","c":["久忘把镜照容姿，风动屏开见鬓丝。","岩背好花浑未发，莫将春色怨迟迟。"]},{"t":"春日杂兴二十七首 其九","f":"七言绝句","c":["土作坡陀石作岩，晓乘甘雨种松杉。","门前日日春潮到，定有双鱼寄一椷。"]},{"t":"春日杂兴二十七首 其十","f":"七言绝句","c":["细雨庭除湿未匀，小山毛骨长精神。","呼儿半捲湘帘坐，满涧飞花苦恋春。"]},{"t":"春日杂兴二十七首 其十一","f":"七言绝句","c":["春深山馆日如年，品石尝泉各有缘。","好客远从云外至，自移尘榻向花前。"]},{"t":"春日杂兴二十七首 其十二","f":"七言绝句","c":["湘帘面面拥孤亭，雨弄春晴草更青。","山静日长无一事，倚阑閒看鹤梳翎。"]},{"t":"春日杂兴二十七首 其十三","f":"七言绝句","c":["高槐细柳俨成行，远水遥山护草堂。","一片浮云飏空碧，半分寒气酿春光。"]},{"t":"春日杂兴二十七首 其十四","f":"七言绝句","c":["侍儿日日报花开，白白红红尽手栽。","我自白头春自好，莫教风雨便相催。"]},{"t":"春日杂兴二十七首 其十五","f":"七言绝句","c":["江上高楼隔晚霞，蒲团静结倚窗纱。","暗香一道随风力，知是前村枳橘花。"]},{"t":"春日杂兴二十七首 其十六","f":"七言绝句","c":["寂寂春阴江阁閒，绿浮新雨涨潺湲。","隔花一犬足高卧，门外借书人未还。"]},{"t":"春日杂兴二十七首 其十七","f":"七言绝句","c":["花傍高楼半掩扉，河豚风起钓鱼矶。","沙鸥似解閒人意，时向蒹葭深处飞。"]},{"t":"春日杂兴二十七首 其十八","f":"七言绝句","c":["春江一曲绕孤村，鹤有双雏竹有孙。","爱听沧浪临水坐，背人新月弄黄昏。"]},{"t":"春日杂兴二十七首 其十九","f":"七言绝句","c":["遥闻大药驻衰颜，我付行藏与鬓斑。","多事一春眠白日，无言十里对青山。"]},{"t":"春日杂兴二十七首 其二十","f":"七言绝句","c":["漠漠杨花闹晓晴，穿帘入幕太多情。","如何无力遮春住，点破沧浪万里清。"]},{"t":"春日杂兴二十七首 其二十一","f":"七言绝句","c":["一溪一曲大江东，细柳新蒲窈窕通。","寒食楼台三日雨，捲帘庭院百花风。"]},{"t":"春日杂兴二十七首 其二十二","f":"七言绝句","c":["花木阴阴午漏长，迁莺啼近读书堂。","谁能料理春多少，閒写新诗上粉墙。"]},{"t":"春日杂兴二十七首 其二十三","f":"七言绝句","c":["纸帐蒲茵白板床，秪将春睡答春光。","梦中几曲溪南路，水浴风行总未忘。"]},{"t":"春日杂兴二十七首 其二十四","f":"七言绝句","c":["莺啼燕语各分明，最爱春声自物情。","风送夕阳宾客退，一帘香雾浪纹生。"]}]};